import cmath
import math

def discrete_fourier_transform(signal, precision=2):
    if not signal:
        raise ValueError("signal must be non-empty")

    n = len(signal)
    result = []

    for k in range(n):
        value = sum(
            sample * cmath.exp(-2j * math.pi * k * i / n)
            for i, sample in enumerate(signal)
        )
        result.append((round(value.real, precision), round(value.imag, precision)))

    return result
