def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must not be empty")
    if (
        not isinstance(n_clusters, int)
        or isinstance(n_clusters, bool)
        or n_clusters <= 0
    ):
        raise ValueError("n_clusters must be a positive integer")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    pts = [(float(x), float(y)) for x, y in points]

    def distance_squared(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic farthest-first initialization.
    centers = [pts[0]]
    while len(centers) < n_clusters:
        next_point = max(
            pts,
            key=lambda p: min(distance_squared(p, c) for c in centers),
        )
        centers.append(next_point)

    for _ in range(300):
        clusters = [[] for _ in range(n_clusters)]

        for point in pts:
            closest = min(
                range(n_clusters),
                key=lambda i: distance_squared(point, centers[i]),
            )
            clusters[closest].append(point)

        updated = []
        for i, cluster in enumerate(clusters):
            if cluster:
                updated.append((
                    sum(p[0] for p in cluster) / len(cluster),
                    sum(p[1] for p in cluster) / len(cluster),
                ))
            else:
                # Keep the previous center if its cluster is empty.
                updated.append(centers[i])

        if updated == centers:
            break
        centers = updated

    return [[x, y] for x, y in sorted(centers)]
