        clusters = [[] for _ in centers]
        point_distances = []

        for point in points:
            distances = [squared_distance(point, center) for center in centers]
            nearest = min(range(len(centers)), key=distances.__getitem__)
            clusters[nearest].append(point)
            point_distances.append(distances[nearest])

        new_centers = []
