def kmeans_centers(points, n_clusters):
    """Return k-means centers for 2D points, sorted by x then y."""
    if not points:
        raise ValueError("points must not be empty")
    if not isinstance(n_clusters, int) or isinstance(n_clusters, bool) or n_clusters <= 0:
        raise ValueError("n_clusters must be a positive integer")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    points = [[float(x), float(y)] for x, y in points]
    centers = [point[:] for point in points[:n_clusters]]

    for _ in range(1000):
        groups = [[] for _ in range(n_clusters)]

        for point in points:
            nearest = min(
                range(n_clusters),
                key=lambda i: (point[0] - centers[i][0]) ** 2
                             + (point[1] - centers[i][1]) ** 2,
            )
            groups[nearest].append(point)

        new_centers = []
        for i, group in enumerate(groups):
            if group:
                new_centers.append([
                    sum(point[0] for point in group) / len(group),
                    sum(point[1] for point in group) / len(group),
                ])
            else:
                # Keep the old center if no points were assigned to it.
                new_centers.append(centers[i])

        if new_centers == centers:
            break
        centers = new_centers

    return sorted(centers, key=lambda center: (center[0], center[1]))
