    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    def squared_distance(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic farthest-point initialization.
    centers = [points[0][:]]
    while len(centers) < n_clusters:
        next_point = max(
            points,
            key=lambda p: min(squared_distance(p, c) for c in centers),
        )
        centers.append(next_point[:])

    for _ in range(300):
        groups = [[] for _ in range(n_clusters)]
        for point in points:
            nearest = min(
                range(n_clusters),
                key=lambda i: squared_distance(point, centers[i]),
            )
            groups[nearest].append(point)

        new_centers = []
        for group in groups:
            if group:
                new_centers.append([
                    sum(p[0] for p in group) / len(group),
                    sum(p[1] for p in group) / len(group),
                ])
            else:
                new_centers.append(None)

        # Re-seed empty clusters with points farthest from the current centers.
        for i, center in enumerate(new_centers):
            if center is None:
                existing = [c for c in new_centers if c is not None]
                point = max(
                    points,
                    key=lambda p: min(squared_distance(p, c) for c in existing),
                )
                new_centers[i] = point[:]

        if new_centers == centers:
            break
        centers = new_centers

    return [list(center) for center in sorted(centers, key=lambda c: (c[0], c[1]))]
