import re
from collections import Counter
from math import sqrt


def text_similarity_scores(text1, text2):
    def clean(text):
        # \W matches non-alphanumeric characters; include underscores explicitly.
        return re.sub(r"[\W_]+", " ", text.lower()).strip()

    s1, s2 = clean(text1), clean(text2)

    words1 = Counter(s1.split())
    words2 = Counter(s2.split())

    dot = sum(count * words2[word] for word, count in words1.items())
    norm1 = sqrt(sum(count * count for count in words1.values()))
    norm2 = sqrt(sum(count * count for count in words2.values()))
    cosine = dot / (norm1 * norm2) if norm1 and norm2 else 0.0

    if not s1 and not s2:
        ratio = 1.0
    else:
        # The insertion/deletion similarity is 2 * LCS / (len(s1) + len(s2)).
        a, b = s1, s2
        if len(a) < len(b):
            a, b = b, a

        previous = [0] * (len(b) + 1)
        for char_a in a:
            current = [0]
            for j, char_b in enumerate(b, 1):
                if char_a == char_b:
                    current.append(previous[j - 1] + 1)
                else:
                    current.append(max(previous[j], current[-1]))
            previous = current

        lcs_length = previous[-1]
        ratio = 2 * lcs_length / (len(s1) + len(s2))

    return float(cosine), float(ratio)
```

The ratio uses the longest common subsequence of the cleaned strings, so each unmatched character corresponds to an insertion or deletion.

