import math
import re
from collections import Counter

def text_similarity_scores(text1, text2):
    def clean(text):
        return re.sub(r"[^a-z0-9]+", " ", text.lower()).strip()

    a, b = clean(text1), clean(text2)
    words_a, words_b = Counter(a.split()), Counter(b.split())

    if not words_a or not words_b:
        cosine = 0.0
    else:
        dot = sum(count * words_b[word] for word, count in words_a.items())
        norm_a = math.sqrt(sum(count * count for count in words_a.values()))
        norm_b = math.sqrt(sum(count * count for count in words_b.values()))
        cosine = dot / (norm_a * norm_b)

    if not a and not b:
        ratio = 1.0
    else:
        # LCS gives the minimum number of character insertions and deletions.
        if len(a) < len(b):
            a, b = b, a
        row = [0] * (len(b) + 1)
        for char_a in a:
            diagonal = 0
            for j, char_b in enumerate(b, 1):
                above = row[j]
                if char_a == char_b:
                    row[j] = diagonal + 1
                else:
                    row[j] = max(row[j], row[j - 1])
                diagonal = above

        ratio = 2 * row[-1] / (len(a) + len(b))

    return float(cosine), float(ratio)
