import numpy as np

def fit_linear_regression(features, values):
    X = np.asarray(features, dtype=float)
    y = np.asarray(values, dtype=float)

    if X.ndim != 2:
        raise ValueError("features must be a 2D list")
    if y.ndim != 1 or len(y) != X.shape[0]:
        raise ValueError("values must contain one target per feature row")
    if X.shape[0] == 0:
        raise ValueError("at least one row is required")

    # Put the intercept in the first column.
    design = np.column_stack((np.ones(X.shape[0]), X))
    params, *_ = np.linalg.lstsq(design, y, rcond=None)

    return {
        "coefficients": params[1:].tolist(),
        "intercept": float(params[0]),
    }
