from math import sqrt

def column_correlation_matrix(data, cols):
    """Return the Pearson correlation matrix in the order given by cols."""
    n = len(data)
    k = len(cols)

    if n == 0:
        return [[float("nan") for _ in range(k)] for _ in range(k)]

    columns = [[row[j] for row in data] for j in range(k)]
    means = [sum(column) / n for column in columns]
    centered = [
        [value - means[j] for value in columns[j]]
        for j in range(k)
    ]
    sums_of_squares = [
        sum(value * value for value in centered[j])
        for j in range(k)
    ]

    result = [[float("nan")] * k for _ in range(k)]
    for i in range(k):
        for j in range(i, k):
            denominator = sqrt(sums_of_squares[i] * sums_of_squares[j])
            if denominator != 0:
                correlation = sum(
                    centered[i][r] * centered[j][r] for r in range(n)
                ) / denominator
                result[i][j] = result[j][i] = correlation

    return result
```

