from math import nan, sqrt

def column_correlation_matrix(data, cols):
    ncols = len(cols)

    if any(len(row) != ncols for row in data):
        raise ValueError("Each row must have one value per column")

    if not data:
        return [[nan] * ncols for _ in range(ncols)]

    columns = [[row[j] for row in data] for j in range(ncols)]
    means = [sum(column) / len(column) for column in columns]
    centered = [
        [value - means[j] for value in columns[j]]
        for j in range(ncols)
    ]
    sums_of_squares = [
        sum(value * value for value in column)
        for column in centered
    ]

    result = []
    for i in range(ncols):
        row = []
        for j in range(ncols):
            denominator = sqrt(sums_of_squares[i] * sums_of_squares[j])
            if denominator == 0:
                row.append(nan)  # Pearson correlation is undefined for a constant column
            else:
                numerator = sum(
                    a * b for a, b in zip(centered[i], centered[j])
                )
                row.append(numerator / denominator)
        result.append(row)

    return result
