        return None

    try:
        return int(value)
    except ValueError:
        try:
            return float(value)
        except ValueError:
            return value


def merge_csv_texts(csv_texts):
    tables = []
    columns = []

    for text in csv_texts:
        rows = list(csv.reader(io.StringIO(text, newline="")))
        if not rows:
            continue

        header = rows[0]
        tables.append((header, rows[1:]))

        for column in header:
            if column not in columns:
                columns.append(column)

    merged = []
    for header, rows in tables:
        for row in rows:
            values = dict(zip(header, row))
            merged.append({
                column: _convert_value(values.get(column, ""))
                for column in columns
            })

    return merged
