import csv
import io


def merge_csv_texts(csv_texts):
    columns = []
    rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        headers = next(reader, [])
        for header in headers:
            if header not in columns:
                columns.append(header)

        for values in reader:
            if not values:  # Skip blank lines
                continue
            row = {}
            for i, header in enumerate(headers):
                value = values[i] if i < len(values) else ""
                row[header] = value
            rows.append(row)

    def convert(value):
        if value is None or value.strip() == "":
            return None

        value = value.strip()
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return value

    return [
        {column: convert(row.get(column)) for column in columns}
        for row in rows
    ]
