        centered_x = [value - mean_x for value in counts[x]]
        result[x] = {}

        for y in letters:
            mean_y = sum(counts[y]) / len(strings)
            centered_y = [value - mean_y for value in counts[y]]

            numerator = sum(a * b for a, b in zip(centered_x, centered_y))
            denominator = sqrt(
                sum(a * a for a in centered_x) *
                sum(b * b for b in centered_y)
            )
            result[x][y] = numerator / denominator

    return result
