from statistics import mean, pstdev

def standardize_series(x, y, labels):
    if not (len(x) == len(y) == len(labels)):
        raise ValueError("x, y, and labels must have the same length")

    def z_scores(values):
        if not values:
            raise ValueError("Each series must contain at least one value")

        avg = mean(values)
        std = pstdev(values)  # Population standard deviation
        if std == 0:
            return [0.0] * len(values)

        return [(value - avg) / std for value in values]

    return {
        label: [z_scores(x_values), z_scores(y_values)]
        for x_values, y_values, label in zip(x, y, labels)
    }
```

A series with no variation is returned as all zeros, since its standard deviation is zero.

