from math import sqrt

def standardize_series(x, y, labels):
    if not (len(x) == len(y) == len(labels)):
        raise ValueError("x, y, and labels must have the same number of series")

    def z_scores(values):
        if not values:
            raise ValueError("Each series must contain at least one value")

        mean = sum(values) / len(values)
        std = sqrt(sum((value - mean) ** 2 for value in values) / len(values))

        # A constant series has zero variance; return zeros for its z-scores.
        if std == 0:
            return [0.0] * len(values)

        return [(value - mean) / std for value in values]

    return {
        label: [z_scores(x_values), z_scores(y_values)]
        for label, x_values, y_values in zip(labels, x, y)
    }
```

