def top_regression_residuals(data, feature, target, n=10):
    if feature not in data or target not in data:
        raise ValueError("feature and target must both be keys in data")

    x = data[feature]
    y = data[target]

    if len(x) != len(y):
        raise ValueError("feature and target columns must have equal lengths")
    if not x:
        raise ValueError("cannot fit a regression line to empty data")
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")

    count = len(x)
    x_mean = sum(x) / count
    y_mean = sum(y) / count

    xx = sum((xi - x_mean) ** 2 for xi in x)
    if xx == 0:
        # A constant feature has no unique slope; this is a valid
        # least-squares solution.
        slope = 0.0
    else:
        slope = sum(
            (xi - x_mean) * (yi - y_mean) for xi, yi in zip(x, y)
        ) / xx

    intercept = y_mean - slope * x_mean
    residuals = [
        yi - (slope * xi + intercept)
        for xi, yi in zip(x, y)
    ]

    indices = sorted(
        range(count),
        key=lambda i: (-abs(residuals[i]), i),
    )[:n]

    return indices, slope, intercept
```

Ties in absolute residual size are ordered by row position. For the example, this returns `([2, 0, 3], 0.6, 2.6)`.

