def top_regression_residuals(data, feature, target, n=10):
    if feature not in data or target not in data:
        raise ValueError("feature and target columns must exist in data")
    if n < 0:
        raise ValueError("n must be non-negative")

    x = data[feature]
    y = data[target]
    if not x:
        raise ValueError("cannot fit a regression line to empty data")

    x_mean = sum(x) / len(x)
    y_mean = sum(y) / len(y)

    variance = sum((value - x_mean) ** 2 for value in x)
    if variance == 0:
        slope = 0
    else:
        covariance = sum(
            (x_value - x_mean) * (y_value - y_mean)
            for x_value, y_value in zip(x, y)
        )
        slope = covariance / variance

    intercept = y_mean - slope * x_mean
    residuals = [
        y_value - (slope * x_value + intercept)
        for x_value, y_value in zip(x, y)
    ]

    indices = sorted(
        range(len(residuals)),
        key=lambda i: (-abs(residuals[i]), i),
    )[:n]

    return indices, slope, intercept
```

Ties in absolute residual are ordered by row position. If the feature is constant, the function uses slope `0` and predicts the target mean.

