        numeric_columns += 1
        low, high = min(numbers), max(numbers)

        if low == high:
            columns[header] = [0.0] * len(numbers)
        else:
            columns[header] = [(value - low) / (high - low) for value in numbers]

    if numeric_columns == 0:
        raise ValueError("CSV contains no numeric columns")

    return columns
