import csv
import io


def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        headers = next(reader)
    except StopIteration:
        raise ValueError("CSV must contain a header row")

    rows = [row for row in reader if row]

    if any(len(row) != len(headers) for row in rows):
        raise ValueError("Each row must have the same number of values as the header")

    result = {}
    numeric_count = 0

    for index, header in enumerate(headers):
        values = [row[index] for row in rows]

        try:
            numbers = [float(value) for value in values]
            is_numeric = bool(values)
        except ValueError:
            is_numeric = False

        if is_numeric:
            numeric_count += 1
            minimum = min(numbers)
            maximum = max(numbers)

            result[header] = (
                [0.0] * len(numbers)
                if minimum == maximum
                else [(value - minimum) / (maximum - minimum) for value in numbers]
            )
        else:
            result[header] = values

    if numeric_count == 0:
        raise ValueError("CSV has no numeric columns")

    return result
