from math import sqrt

def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("Input must contain at least one row")
    if any(len(row) != 5 for row in array):
        raise ValueError("Each row must contain exactly 5 values")

    columns = [[row[j] for row in array] for j in range(5)]
    means = [sum(column) / len(array) for column in columns]
    centered = [
        [value - means[j] for value in columns[j]]
        for j in range(5)
    ]
    sums_of_squares = [
        sum(value * value for value in column)
        for column in centered
    ]

    if any(total == 0 for total in sums_of_squares):
        raise ValueError("Correlation is undefined for a constant column")

    matrix = []
    for i in range(5):
        row = []
        for j in range(5):
            cross_sum = sum(
                centered[i][k] * centered[j][k]
                for k in range(len(array))
            )
            row.append(cross_sum / sqrt(sums_of_squares[i] * sums_of_squares[j]))
        matrix.append(row)

    return matrix
