from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, target):
        super().__init__(convert_charrefs=True)
        self.target = target.lower()
        self.found = False
        self.finished = False
        self.stack = []
        self.parts = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if self.finished:
            return

        if not self.found:
            if tag == self.target:
                self.found = True
                if tag in _VOID_TAGS:
                    self.finished = True
                else:
                    self.stack.append(tag)
        elif tag not in _VOID_TAGS:
            self.stack.append(tag)

    def handle_endtag(self, tag):
        if not self.found or self.finished:
            return

        tag = tag.lower()
        if tag in self.stack:
            # Close this element and any unclosed descendants.
            index = len(self.stack) - 1 - self.stack[::-1].index(tag)
            del self.stack[index:]
            if not self.stack:
                self.finished = True

    def handle_data(self, data):
        if self.found and not self.finished:
            self.parts.append(data)


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    if not parser.found:
        return None

    text = "".join(parser.parts)
    return text if text else None
```

It preserves whitespace, includes descendant text, and decodes character references. For example, `first_tag_text('<p>A <b>&amp; B</b></p>', 'p')` returns `'A & B'`.

