from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}


class _FirstTagTextParser(HTMLParser):
    def __init__(self, target):
        super().__init__(convert_charrefs=True)
        self.target = target.lower()
        self.depth = 0
        self.started = False
        self.done = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if not self.started and tag == self.target:
            self.started = True
            if tag in _VOID_TAGS:
                self.done = True
            else:
                self.depth = 1
        elif self.started and not self.done and tag == self.target:
            self.depth += 1

    def handle_endtag(self, tag):
        if self.started and not self.done and tag.lower() == self.target:
            self.depth -= 1
            if self.depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.started and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    text = "".join(parser.parts)
    return text if text else None
```

Tags are matched case-insensitively. Nested elements’ text is included, and HTML entities are decoded. Whitespace-only text is returned as-is.

