from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}


class _FirstTagTextParser(HTMLParser):
    def __init__(self, target):
        super().__init__(convert_charrefs=True)
        self.target = target.lower()
        self.found = False
        self.done = False
        self.stack = []
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        if self.stack:
            if tag not in _VOID_TAGS:
                self.stack.append(tag)
        elif not self.found and tag == self.target:
            self.found = True
            if tag in _VOID_TAGS:
                self.done = True
            else:
                self.stack.append(tag)

    def handle_startendtag(self, tag, attrs):
        if not self.done and not self.stack and not self.found and tag == self.target:
            self.found = True
            self.done = True

    def handle_endtag(self, tag):
        if self.done or not self.stack:
            return

        # Close the matching element and any unclosed descendants.
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i] == tag:
                del self.stack[i:]
                if not self.stack:
                    self.done = True
                return

    def handle_data(self, data):
        if self.stack and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    text = "".join(parser.parts)
    return text if parser.found and text else None
```

For example, `first_tag_text('<html><body><p>First</p><p>Second</p></body></html>', 'p')` returns `'First'`. Whitespace-only text is returned as-is; only an empty string produces `None`.

