import csv
from datetime import date
from io import StringIO


def filter_rows_by_date_range(csv_text, column_name, start_date, end_date):
    def parse_date(value):
        try:
            parsed = date.fromisoformat(value)
        except (TypeError, ValueError):
            return None
        # Require exactly YYYY-MM-DD, including zero-padding.
        return parsed if parsed.isoformat() == value else None

    start = parse_date(start_date)
    end = parse_date(end_date)
    if start is None or end is None:
        raise ValueError("Bounds must be valid dates in YYYY-MM-DD format")

    reader = csv.reader(StringIO(csv_text, newline=""))
    try:
        header = next(reader)
        date_index = header.index(column_name)
    except (StopIteration, ValueError):
        raise ValueError(f"Column {column_name!r} does not exist") from None

    matching_rows = []
    for row in reader:
        if date_index >= len(row):
            continue
        row_date = parse_date(row[date_index])
        if row_date is not None and start <= row_date <= end:
            matching_rows.append(row)

    return matching_rows
```

Rows with missing or invalid dates are skipped. If `start_date` is after `end_date`, the function returns an empty list.

