        if not math.isfinite(number):
            raise ValueError(f"Missing or non-numeric value: {value!r}")
        return number

    train_header, train_rows = read_csv(train_csv)
    test_header, test_rows = read_csv(test_csv)

    if len(set(train_header)) != len(train_header):
        raise ValueError("Duplicate column names are not supported")
    if train_header != test_header:
        raise ValueError("Training and test CSVs must have the same columns")
    if target not in train_header:
        raise ValueError(f"Target column {target!r} not found")

    target_index = train_header.index(target)
    feature_indices = [i for i in range(len(train_header)) if i != target_index]

    def check_row_width(row):
        if len(row) != len(train_header):
            raise ValueError("CSV row has the wrong number of columns")

    x_train, y_train = [], []
    for row in train_rows:
        check_row_width(row)
        x_train.append([to_float(row[i]) for i in feature_indices])
        y_train.append(to_float(row[target_index]))

    x_test = []
    for row in test_rows:
        check_row_width(row)
        # The target column in test data is deliberately not read.
        x_test.append([to_float(row[i]) for i in feature_indices])

    if not y_train:
        raise ValueError("Training CSV must contain at least one data row")

    # Add a column of ones to fit the intercept.
    train_design = np.column_stack((np.ones(len(x_train)), np.asarray(x_train).reshape(len(x_train), -1)))
    test_design = np.column_stack((np.ones(len(x_test)), np.asarray(x_test).reshape(len(x_test), -1)))

    coefficients, *_ = np.linalg.lstsq(train_design, np.asarray(y_train), rcond=None)
    return [float(value) for value in test_design @ coefficients]
```

This uses NumPy’s least-squares solver, so it also handles rank-deficient feature matrices.

