import csv
import io
import math

import numpy as np


def predict_linear_regression(train_csv, test_csv, target):
    def read_csv(text):
        try:
            return list(csv.reader(io.StringIO(text)))
        except csv.Error as exc:
            raise ValueError("Invalid CSV") from exc

    train_rows = read_csv(train_csv)
    test_rows = read_csv(test_csv)

    if not train_rows or not test_rows:
        raise ValueError("CSV must include a header row")

    train_header = train_rows[0]
    test_header = test_rows[0]

    if (
        len(set(train_header)) != len(train_header)
        or len(set(test_header)) != len(test_header)
        or target not in train_header
        or set(train_header) != set(test_header)
    ):
        raise ValueError("Headers must be unique, contain the target, and match")

    feature_names = [name for name in train_header if name != target]
    train_indices = {name: train_header.index(name) for name in train_header}
    test_indices = {name: test_header.index(name) for name in test_header}

    def number(value):
        try:
            result = float(value.strip())
        except (AttributeError, ValueError) as exc:
            raise ValueError("Values used for fitting or prediction must be numeric") from exc
        if not math.isfinite(result):
            raise ValueError("Values used for fitting or prediction must be finite")
        return result

    x_train, y_train = [], []
    for row in train_rows[1:]:
        if not row:  # Ignore blank lines.
            continue
        if len(row) > len(train_header):
            raise ValueError("CSV row has more fields than its header")
        x_train.append([
            number(row[train_indices[name]])
            if train_indices[name] < len(row) else number("")
            for name in feature_names
        ])
        target_index = train_indices[target]
        y_train.append(number(row[target_index]) if target_index < len(row) else number(""))

    if not y_train:
        raise ValueError("Training CSV must contain at least one data row")

    x_test = []
    for row in test_rows[1:]:
        if not row:  # Ignore blank lines.
            continue
        if len(row) > len(test_header):
            raise ValueError("CSV row has more fields than its header")
        x_test.append([
            number(row[test_indices[name]])
            if test_indices[name] < len(row) else number("")
            for name in feature_names
        ])

    # Add an intercept column and solve the least-squares problem.
    train_design = np.column_stack((np.ones(len(x_train)), np.asarray(x_train, dtype=float)))
    coefficients, *_ = np.linalg.lstsq(train_design, np.asarray(y_train), rcond=None)

    if not x_test:
        return []

    test_design = np.column_stack((np.ones(len(x_test)), np.asarray(x_test, dtype=float)))
    return (test_design @ coefficients).astype(float).tolist()
```

The target column is not read from the test rows, so missing or non-numeric target values there do not affect predictions. The function uses NumPy’s least-squares solver, including when the predictors are collinear.

