from math import sqrt

def find_zscore_outliers(prices, z_threshold):
    if not prices:
        return []

    mean = sum(prices) / len(prices)
    population_std = sqrt(
        sum((price - mean) ** 2 for price in prices) / len(prices)
    )

    # With zero variance, every price equals the mean, so there are no outliers.
    if population_std == 0:
        return []

    return [
        (index, price, (price - mean) / population_std)
        for index, price in enumerate(prices)
        if abs((price - mean) / population_std) > z_threshold
    ]
