import csv
import io

def normalize_csv_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        headers = next(reader)
    except StopIteration:
        return {}

    rows = [row for row in reader if row]
    columns = [[] for _ in headers]

    for row in rows:
        for i, value in enumerate(row):
            columns[i].append(float(value))

    result = {}
    for header, values in zip(headers, columns):
        low, high = min(values), max(values)
        result[header] = (
            [0.0] * len(values)
            if low == high
            else [(value - low) / (high - low) for value in values]
        )

    return result
```

For example, `normalize_csv_columns('a,b\n1,10\n3,20\n5,10')` returns `{'a': [0.0, 0.5, 1.0], 'b': [0.0, 1.0, 0.0]}`. This assumes each data row has a value for every header and that header names are unique.

