import csv
from io import StringIO


def normalize_csv_columns(csv_text):
    reader = csv.reader(StringIO(csv_text))

    try:
        headers = next(reader)
    except StopIteration:
        return {}

    columns = [[] for _ in headers]

    for row in reader:
        if not row:  # Ignore blank lines
            continue
        if len(row) != len(headers):
            raise ValueError("Each data row must have the same number of fields as the header")

        for column, value in zip(columns, row):
            column.append(float(value))

    result = {}
    for name, values in zip(headers, columns):
        if not values:
            result[name] = []
            continue

        minimum = min(values)
        maximum = max(values)
        span = maximum - minimum

        result[name] = (
            [0.0 for _ in values]
            if span == 0
            else [(value - minimum) / span for value in values]
        )

    return result
```

