def normalize_with_row_averages(data):
    if not data:
        return []

    n_features = len(data[0])
    mins = [min(row[col] for row in data) for col in range(n_features)]
    maxs = [max(row[col] for row in data) for col in range(n_features)]

    result = []
    for row in data:
        scaled = [
            0.0 if maxs[col] == mins[col]
            else (row[col] - mins[col]) / (maxs[col] - mins[col])
            for col in range(n_features)
        ]
        average = sum(scaled) / len(scaled) if scaled else 0.0
        result.append(scaled + [average])

    return result
