from html.parser import HTMLParser


def extract_data_table_rows(html):
    class Parser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.found_table = False
            self.table_depth = 0
            self.rows = []
            self.row = None
            self.cell = None

        def handle_starttag(self, tag, attrs):
            if not self.found_table:
                if tag == "table":
                    class_value = next(
                        (value for name, value in attrs if name == "class"),
                        None,
                    )
                    if class_value == "data-table":
                        self.found_table = True
                        self.table_depth = 1
                return

            if tag == "table":
                self.table_depth += 1
                return

            # Ignore rows and cells belonging to nested tables.
            if self.table_depth != 1:
                return

            if tag == "tr":
                self._finish_row()
                self.row = []
            elif tag == "td" and self.row is not None:
                self._finish_cell()

        def handle_endtag(self, tag):
            if not self.found_table:
                return

            if tag == "table":
                if self.table_depth > 1:
                    self.table_depth -= 1
                else:
                    self._finish_row()
                    self.table_depth = 0
                return

            if self.table_depth != 1:
                return

            if tag == "td":
                self._finish_cell()
            elif tag == "tr":
                self._finish_row()

        def handle_data(self, data):
            if self.cell is not None:
                self.cell.append(data)

        def _finish_cell(self):
            if self.cell is not None:
                self.row.append("".join(self.cell))
                self.cell = None

        def _finish_row(self):
            if self.row is not None:
                self._finish_cell()
                self.rows.append(self.row)
                self.row = None

    parser = Parser()
    parser.feed(html)
    parser.close()
    parser._finish_row()  # Also include a row if the markup leaves it unclosed.
    return parser.rows
```

The class value is compared exactly, cell text keeps its whitespace, and character entities are decoded. Nested-table rows are not included.

