from html.parser import HTMLParser


def extract_data_table_rows(html):
    class Parser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.table_depth = 0
            self.target_depth = None
            self.rows = []
            self.row = None
            self.cell_parts = None
            self.cell_depth = None

        def finish_cell(self):
            if self.cell_parts is not None:
                self.row.append("".join(self.cell_parts))
                self.cell_parts = None
                self.cell_depth = None

        def finish_row(self):
            if self.row is not None:
                self.finish_cell()
                self.rows.append(self.row)
                self.row = None

        def handle_starttag(self, tag, attrs):
            if tag == "table":
                self.table_depth += 1
                if self.target_depth is None:
                    attributes = dict(attrs)
                    if attributes.get("class") == "data-table":
                        self.target_depth = self.table_depth
                return

            if self.table_depth != self.target_depth:
                return

            if tag == "tr":
                self.finish_row()
                self.row = []
            elif tag == "td" and self.row is not None and self.cell_parts is None:
                self.cell_parts = []
                self.cell_depth = self.table_depth

        def handle_endtag(self, tag):
            if tag == "td" and self.cell_depth == self.table_depth:
                self.finish_cell()
            elif tag == "tr" and self.table_depth == self.target_depth:
                self.finish_row()
            elif tag == "table":
                if self.table_depth == self.target_depth:
                    self.finish_row()
                self.table_depth -= 1

        def handle_data(self, data):
            if self.cell_parts is not None:
                self.cell_parts.append(data)

    parser = Parser()
    parser.feed(html)
    parser.close()
    parser.finish_row()
    return parser.rows
