from html.parser import HTMLParser


class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.found_table = False
        self.in_target = False
        self.nested_tables = 0
        self.current_row = None
        self.current_cell = None

    def _close_cell(self):
        if self.current_cell is not None:
            self.current_row.append("".join(self.current_cell))
            self.current_cell = None

    def _close_row(self):
        if self.current_row is not None:
            self._close_cell()
            self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            if self.in_target:
                self.nested_tables += 1
            elif not self.found_table:
                classes = [value for name, value in attrs if name == "class"]
                if classes and classes[0] == "data-table":
                    self.found_table = True
                    self.in_target = True
            return

        if not self.in_target or self.nested_tables:
            return

        if tag == "tr":
            self._close_row()
            self.current_row = []
        elif tag == "td" and self.current_row is not None:
            self._close_cell()
            self.current_cell = []

    def handle_endtag(self, tag):
        if not self.in_target:
            return

        if tag == "table":
            if self.nested_tables:
                self.nested_tables -= 1
            else:
                self._close_row()
                self.in_target = False
            return

        if self.nested_tables:
            return

        if tag == "td":
            self._close_cell()
        elif tag == "tr":
            self._close_row()

    def handle_data(self, data):
        if self.current_cell is not None:
            self.current_cell.append(data)


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()

    # Also finish a target table that was not explicitly closed.
    if parser.in_target:
        parser._close_row()

    return parser.rows
```

It returns one list per row, including rows with no `<td>` cells. Cell text is concatenated without trimming, and character references are decoded.

