def min_max_scale_columns(data, columns):
    columns_to_scale = set(columns)
    result = {}

    for name, values in data.items():
        if name not in columns_to_scale:
            result[name] = values.copy()
            continue

        if not values:
            result[name] = []
            continue

        minimum = min(values)
        maximum = max(values)

        if minimum == maximum:
            result[name] = [0.0] * len(values)
        else:
            result[name] = [
                (value - minimum) / (maximum - minimum)
                for value in values
            ]

    return result
