from math import copysign, fsum, sqrt


def fit_quadratic(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    if len(xs) < 3:
        raise ValueError("at least three points are required")

    # Build the design matrix with columns x², x, and 1.
    a = [[float(x) ** 2, float(x), 1.0] for x in xs]
    b = [float(y) for y in ys]
    column_norms = [
        sqrt(fsum(row[j] ** 2 for row in a))
        for j in range(3)
    ]

    # Householder QR decomposition, applying each reflector to b as well.
    for k in range(3):
        v = [a[i][k] for i in range(k, len(a))]
        norm = sqrt(fsum(value * value for value in v))

        if norm <= 1e-12 * column_norms[k]:
            raise ValueError("the x values do not determine a unique quadratic")

        alpha = -copysign(norm, v[0])
        v[0] -= alpha
        v_norm_sq = fsum(value * value for value in v)

        for j in range(k, 3):
            factor = 2 * fsum(v[i] * a[k + i][j] for i in range(len(v))) / v_norm_sq
            for i in range(len(v)):
                a[k + i][j] -= factor * v[i]

        factor = 2 * fsum(v[i] * b[k + i] for i in range(len(v))) / v_norm_sq
        for i in range(len(v)):
            b[k + i] -= factor * v[i]

    # Solve the resulting upper-triangular system.
    coefficients = [0.0, 0.0, 0.0]
    for i in range(2, -1, -1):
        coefficients[i] = (
            b[i] - fsum(a[i][j] * coefficients[j] for j in range(i + 1, 3))
        ) / a[i][i]

    return [float(value) for value in coefficients]
```

For the example, the result is approximately `[3.0, 2.0, 1.0]`. A `ValueError` is also raised if the x values cannot determine a unique quadratic.

```python
def fit_quadratic(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    if len(xs) < 3:
        raise ValueError("at least three points are required")

    # Normal equations for the design matrix columns [x², x, 1].
    sums = [sum(x**k for x in xs) for k in range(5)]
    rhs = [
        sum(x * x * y for x, y in zip(xs, ys)),
        sum(x * y for x, y in zip(xs, ys)),
        sum(ys),
    ]
    matrix = [
        [sums[4], sums[3], sums[2]],
        [sums[3], sums[2], sums[1]],
        [sums[2], sums[1], len(xs)],
    ]
    augmented = [row + [value] for row, value in zip(matrix, rhs)]

    # Solve the 3×3 system with Gaussian elimination and partial pivoting.
    for col in range(3):
        pivot = max(range(col, 3), key=lambda r: abs(augmented[r][col]))
        if augmented[pivot][col] == 0:
            raise ValueError("the x values do not determine a unique quadratic fit")
        augmented[col], augmented[pivot] = augmented[pivot], augmented[col]

        pivot_value = augmented[col][col]
        augmented[col] = [value / pivot_value for value in augmented[col]]

        for row in range(3):
            if row != col:
                factor = augmented[row][col]
                augmented[row] = [
                    value - factor * pivot_entry
                    for value, pivot_entry in zip(augmented[row], augmented[col])
                ]

    return [float(augmented[i][3]) for i in range(3)]
