        std = sqrt(sum((value - mean) ** 2 for value in values) / len(values))

        for row in rows1:
            value = row.get(column)
            if value is not None:
                standardized[(row["id"], column)] = (
                    0.0 if std == 0 else (value - mean) / std
                )

