def one_hot_encode_rows(rows):
    if not rows:
        return []

    columns = list(zip(*rows))
    values_by_column = [sorted(set(column)) for column in columns]
    lookups = [
        {value: index for index, value in enumerate(values)}
        for values in values_by_column
    ]

    encoded = []
    for row in rows:
        result = []
        for value, values, lookup in zip(row, values_by_column, lookups):
            result.extend(
                1 if i == lookup[value] else 0
                for i in range(len(values))
            )
        encoded.append(result)

    return encoded
