def seasonal_decomposition(values, period, model):
    """Classically decompose a series into trend, seasonal, and residual parts."""
    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    values = list(values)
    trend = [None] * n
    half = period // 2

    if period % 2:  # Odd period: ordinary centered moving average.
        for i in range(half, n - half):
            trend[i] = sum(values[i - half : i + half + 1]) / period
    else:  # Even period: center the moving average with half-weighted endpoints.
        for i in range(half, n - half):
            window = values[i - half : i + half + 1]
            trend[i] = (
                0.5 * window[0]
                + sum(window[1:-1])
                + 0.5 * window[-1]
            ) / period

    # Estimate a seasonal value for each position in the period.
    by_phase = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                by_phase[i % period].append(value - trend[i])
            else:
                if trend[i] == 0:
                    raise ValueError("cannot compute multiplicative ratios with a zero trend")
                by_phase[i % period].append(value / trend[i])

    seasonal_by_phase = [
        sum(items) / len(items) for items in by_phase
    ]

    # Normalize the seasonal indices.
    seasonal_mean = sum(seasonal_by_phase) / period
    if model == "additive":
        seasonal_by_phase = [s - seasonal_mean for s in seasonal_by_phase]
    else:
        if seasonal_mean == 0:
            raise ValueError("cannot normalize multiplicative seasonal indices")
        seasonal_by_phase = [s / seasonal_mean for s in seasonal_by_phase]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]

    residual = [None] * n
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                residual[i] = value - trend[i] - seasonal[i]
            else:
                denominator = trend[i] * seasonal[i]
                if denominator == 0:
                    raise ValueError("cannot compute multiplicative residual with a zero denominator")
                residual[i] = value / denominator

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
```

For an even period, the centered moving average uses half-weighted endpoints. The seasonal component is estimated from detrended values (or ratios) where the trend is defined, then normalized across the period.

