def seasonal_decomposition(values, period, model):
    """Classically decompose a series into trend, seasonal, and residual components."""
    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if len(values) < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    n = len(values)
    trend = [None] * n
    half = period // 2

    if period % 2:  # Odd period: a centered period-length moving average.
        for i in range(half, n - half):
            window = values[i - half : i + half + 1]
            trend[i] = sum(window) / period
    else:  # Even period: center by averaging adjacent moving averages.
        for i in range(half, n - half):
            first = values[i - half : i + half]
            second = values[i - half + 1 : i + half + 1]
            trend[i] = (sum(first) / period + sum(second) / period) / 2

    phase_values = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                phase_values[i % period].append(value - trend[i])
            else:
                if trend[i] == 0:
                    raise ValueError("multiplicative decomposition requires nonzero trend values")
                phase_values[i % period].append(value / trend[i])

    seasonal_by_phase = [
        sum(phase) / len(phase) if phase else None
        for phase in phase_values
    ]
    if any(value is None for value in seasonal_by_phase):
        raise ValueError("could not estimate a seasonal index for every phase")

    mean_seasonal = sum(seasonal_by_phase) / period
    if model == "additive":
        seasonal_by_phase = [value - mean_seasonal for value in seasonal_by_phase]
    else:
        if mean_seasonal == 0:
            raise ValueError("cannot normalize multiplicative seasonal indices")
        seasonal_by_phase = [value / mean_seasonal for value in seasonal_by_phase]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]
    residual = [None] * n

    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                residual[i] = value - trend[i] - seasonal[i]
            else:
                residual[i] = value / (trend[i] * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
