        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:  # Even period: center by averaging adjacent moving averages
        half = period // 2
        for i in range(half, n - half):
            first = sum(values[i - half:i + half]) / period
            second = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (first + second) / 2

    phase_values = [[] for _ in range(period)]
    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                phase_values[i % period].append(values[i] - t)
            else:
                if t == 0:
                    raise ValueError("multiplicative decomposition requires nonzero trend values")
                phase_values[i % period].append(values[i] / t)

    seasonal = [
        sum(phase_values[p]) / len(phase_values[p])
        for p in range(period)
    ]

    if model == "additive":
        adjustment = sum(seasonal) / period
        seasonal = [s - adjustment for s in seasonal]
    else:
        adjustment = sum(seasonal) / period
        if adjustment == 0:
            raise ValueError("cannot normalise multiplicative seasonal indices")
        seasonal = [s / adjustment for s in seasonal]

    seasonal = [seasonal[i % period] for i in range(n)]

    residual = [None] * n
    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                residual[i] = values[i] - t - seasonal[i]
            else:
                denominator = t * seasonal[i]
                if denominator == 0:
                    raise ValueError("cannot compute multiplicative residual with a zero denominator")
                residual[i] = values[i] / denominator

    return {
        "trend": trend,
        "seasonal": seasonal,
