def seasonal_decomposition(values, period, model):
    """Classically decompose a series into trend, seasonal, and residual components."""
    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError("period must be a positive integer")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    # Centered moving average. For an even period, center by averaging
    # the two adjacent period-length moving averages.
    trend = [None] * n
    for i in range(n):
        if period % 2:
            start = i - period // 2
            if start >= 0 and start + period <= n:
                trend[i] = sum(values[start:start + period]) / period
        else:
            start = i - period // 2
            if start >= 0 and start + period + 1 <= n:
                first = sum(values[start:start + period]) / period
                second = sum(values[start + 1:start + period + 1]) / period
                trend[i] = (first + second) / 2

    # Estimate one seasonal value per position in the period.
    by_phase = [[] for _ in range(period)]
    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                by_phase[i % period].append(values[i] - t)
            else:
                if t == 0:
                    raise ValueError("multiplicative decomposition is undefined for a zero trend")
                by_phase[i % period].append(values[i] / t)

    seasonal_by_phase = [sum(xs) / len(xs) for xs in by_phase]

    if model == "additive":
        offset = sum(seasonal_by_phase) / period
        seasonal_by_phase = [s - offset for s in seasonal_by_phase]
    else:
        mean = sum(seasonal_by_phase) / period
        if mean == 0:
            raise ValueError("multiplicative seasonal indices cannot be normalized")
        seasonal_by_phase = [s / mean for s in seasonal_by_phase]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]

    residual = [None] * n
    for i, t in enumerate(trend):
        if t is not None:
            if model == "additive":
                residual[i] = values[i] - t - seasonal[i]
            else:
                residual[i] = values[i] / (t * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
