    for i, name in enumerate(columns):
        values = [row[i] for row in rows]

        if not values:
            result[name] = []
            continue

        low, high = min(values), max(values)
        result[name] = (
            [0.0] * len(values)
            if low == high
            else [(value - low) / (high - low) for value in values]
        )

