from geographiclib.geodesic import Geodesic


def pairwise_geodesic_distances(locations):
    """Return WGS-84 geodesic distances in kilometres for each pair of locations."""
    if not locations:
        raise ValueError("locations must not be empty")

    items = list(locations.items())
    distances = {}

    for i, (name_a, coord_a) in enumerate(items):
        for name_b, coord_b in items[i + 1:]:
            result = Geodesic.WGS84.Inverse(
                coord_a["Lat"], coord_a["Lon"],
                coord_b["Lat"], coord_b["Lon"],
            )
            distances[(name_a, name_b)] = result["s12"] / 1000

    return distances
