import numpy as np


def column_linear_regression(rows, columns, target):
    if len(rows) == 0:
        raise ValueError("rows must not be empty")
    if target not in columns:
        raise ValueError(f"target column {target!r} was not found")

    if any(len(row) != len(columns) for row in rows):
        raise ValueError("each row must have one value per column")

    target_index = columns.index(target)
    feature_indices = [i for i in range(len(columns)) if i != target_index]

    # Put the intercept first in the design matrix.
    design = [
        [1.0] + [float(row[i]) for i in feature_indices]
        for row in rows
    ]
    values = [float(row[target_index]) for row in rows]

    parameters, *_ = np.linalg.lstsq(
        np.asarray(design), np.asarray(values), rcond=None
    )
    return parameters[1:].tolist(), float(parameters[0])
```

For the example, this returns `([2.0], 1.0)`. This implementation uses NumPy’s least-squares solver.

```python
import numpy as np

def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows must not be empty")
    if target not in columns:
        raise ValueError(f"target {target!r} is not in columns")

    target_idx = columns.index(target)
    feature_indices = [i for i in range(len(columns)) if i != target_idx]

    if any(len(row) != len(columns) for row in rows):
        raise ValueError("each row must have one value per column")

    y = np.asarray([row[target_idx] for row in rows], dtype=float)

    if not feature_indices:
        return [], float(y.mean())

    X = np.asarray(
        [[row[i] for i in feature_indices] for row in rows],
        dtype=float,
    )
    design = np.column_stack((np.ones(len(rows)), X))
    params = np.linalg.lstsq(design, y, rcond=None)[0]

    return params[1:].tolist(), float(params[0])
```

`np.linalg.lstsq` computes the ordinary least-squares fit, including the intercept.

