def weather_column_summary(column, data):
    column_indices = {
        "Temperature": 1,
        "Humidity": 2,
        "Wind Speed": 3,
        "Precipitation": 4,
    }

    if column not in column_indices:
        raise ValueError(f"Invalid column: {column!r}")

    values = [row[column_indices[column]] for row in data]

    if not values:
        return {
            "sum": 0,
            "mean": None,
            "min": None,
            "max": None,
            "histogram": [0] * 10,
        }

    minimum = min(values)
    maximum = max(values)
    histogram = [0] * 10

    if minimum == maximum:
        # For a zero-width range, place every value in the first bin.
        histogram[0] = len(values)
    else:
        bin_width = (maximum - minimum) / 10
        for value in values:
            bin_index = int((value - minimum) / bin_width)
            histogram[min(bin_index, 9)] += 1  # The last bin includes the maximum.

    return {
        "sum": sum(values),
        "mean": sum(values) / len(values),
        "min": minimum,
        "max": maximum,
        "histogram": histogram,
    }
