from collections import Counter, defaultdict

def association_chi_square(left, right):
    left_by_id = defaultdict(list)
    right_by_id = defaultdict(list)

    for id_, category in left:
        left_by_id[id_].append(category)
    for id_, category in right:
        right_by_id[id_].append(category)

    # Count joined category pairs. Repeated IDs produce the usual
    # Cartesian matches for a join.
    cells = Counter()
    for id_ in left_by_id.keys() & right_by_id.keys():
        for left_category in left_by_id[id_]:
            for right_category in right_by_id[id_]:
                cells[left_category, right_category] += 1

    if not cells:
        return 0.0, 0

    row_totals = Counter()
    col_totals = Counter()
    for (row, col), count in cells.items():
        row_totals[row] += count
        col_totals[col] += count

    n = sum(cells.values())
    statistic = sum(
        (observed - row_totals[row] * col_totals[col] / n) ** 2
        / (row_totals[row] * col_totals[col] / n)
        for (row, col), observed in cells.items()
    )
    dof = (len(row_totals) - 1) * (len(col_totals) - 1)

    return float(statistic), int(dof)
```

For no joined records, this returns `(0.0, 0)`. For the example, it returns `(3.0, 1)`.

