def association_chi_square(left, right):
    left_by_id = dict(left)
    right_by_id = dict(right)

    joined = [
        (left_by_id[id_], right_by_id[id_])
        for id_ in left_by_id.keys() & right_by_id.keys()
    ]
    if not joined:
        raise ValueError("No IDs are shared between left and right")

    rows = list(dict.fromkeys(a for a, _ in joined))
    cols = list(dict.fromkeys(b for _, b in joined))

    row_totals = {a: sum(x == a for x, _ in joined) for a in rows}
    col_totals = {b: sum(y == b for _, y in joined) for b in cols}
    total = len(joined)

    statistic = 0.0
    for a in rows:
        for b in cols:
            observed = sum(x == a and y == b for x, y in joined)
            expected = row_totals[a] * col_totals[b] / total
            statistic += (observed - expected) ** 2 / expected

    dof = (len(rows) - 1) * (len(cols) - 1)
    return statistic, int(dof)
```

This assumes IDs are unique in each list. For the example, it returns `(3.0, 1)`.

