from collections import Counter


def cluster_unique_points(points, n_clusters):
    """Return duplicate counts and deterministic k-means clusters of distinct points."""
    if n_clusters < 1:
        raise ValueError("n_clusters must be at least 1")

    counts = Counter(tuple(point) for point in points)
    duplicates = {point: count for point, count in counts.items() if count > 1}
    unique = sorted(counts)

    if not unique:
        return duplicates, []

    k = min(n_clusters, len(unique))

    def distance_squared(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Deterministic farthest-first initialization.
    centers = [unique[0]]
    while len(centers) < k:
        next_point = max(
            unique,
            key=lambda p: min(distance_squared(p, c) for c in centers),
        )
        centers.append(next_point)

    previous_labels = None

    for _ in range(300):
        labels = [
            min(range(k), key=lambda i: distance_squared(point, centers[i]))
            for point in unique
        ]

        # Keep clusters nonempty by moving a faraway point from a cluster
        # that has more than one member.
        cluster_sizes = [labels.count(i) for i in range(k)]
        for empty in range(k):
            if cluster_sizes[empty] == 0:
                candidates = [
                    j for j, label in enumerate(labels)
                    if cluster_sizes[label] > 1
                ]
                j = max(
                    candidates,
                    key=lambda j: distance_squared(unique[j], centers[labels[j]]),
                )
                cluster_sizes[labels[j]] -= 1
                labels[j] = empty
                cluster_sizes[empty] += 1

        new_centers = []
        for cluster_index in range(k):
            members = [
                unique[j] for j, label in enumerate(labels)
                if label == cluster_index
            ]
            new_centers.append(tuple(
                sum(point[dim] for point in members) / len(members)
                for dim in range(len(members[0]))
            ))

        centers = new_centers
        if labels == previous_labels:
            break
        previous_labels = labels

    clusters = [
        sorted(unique[j] for j, label in enumerate(labels) if label == i)
        for i in range(k)
    ]
    return duplicates, sorted(clusters)
```

The duplicate points are counted but only distinct points are clustered. Initialization is deterministic, so repeated calls with the same input produce the same result.

