from collections import Counter


def cluster_unique_points(points, n_clusters):
    """Return duplicate counts and deterministic k-means clusters of distinct points."""
    if n_clusters < 1:
        raise ValueError("n_clusters must be at least 1")

    counts = Counter(tuple(point) for point in points)
    duplicates = {point: count for point, count in counts.items() if count > 1}
    unique = sorted(counts)

    if not unique:
        return duplicates, []

    k = min(n_clusters, len(unique))

    def distance_sq(p, center):
        return (p[0] - center[0]) ** 2 + (p[1] - center[1]) ** 2

    # Deterministic farthest-point initialization.
    centers = [unique[0]]
    while len(centers) < k:
        centers.append(max(
            (p for p in unique if p not in centers),
            key=lambda p: min(distance_sq(p, c) for c in centers),
        ))

    labels = None
    for _ in range(300):
        new_labels = [
            min(range(k), key=lambda i: distance_sq(p, centers[i]))
            for p in unique
        ]

        # Keep every cluster nonempty by moving a farthest point from a cluster
        # that has more than one point into each empty cluster.
        sizes = [new_labels.count(i) for i in range(k)]
        for empty in (i for i, size in enumerate(sizes) if size == 0):
            candidates = [
                j for j, label in enumerate(new_labels) if sizes[label] > 1
            ]
            moved = max(
                candidates,
                key=lambda j: distance_sq(unique[j], centers[new_labels[j]]),
            )
            sizes[new_labels[moved]] -= 1
            new_labels[moved] = empty
            sizes[empty] += 1

        new_centers = []
        for i in range(k):
            members = [p for p, label in zip(unique, new_labels) if label == i]
            new_centers.append((
                sum(p[0] for p in members) / len(members),
                sum(p[1] for p in members) / len(members),
            ))

        if new_labels == labels:
            labels = new_labels
            break
        labels, centers = new_labels, new_centers

    clusters = [
        sorted(p for p, label in zip(unique, labels) if label == i)
        for i in range(k)
    ]
    return duplicates, sorted(clusters)
```

This uses deterministic farthest-point initialization and Lloyd-style k-means updates. Each cluster and the list of clusters are sorted in the returned result.

```python
from collections import Counter


def cluster_unique_points(points, n_clusters):
    """Return duplicate counts and k-means clusters of the distinct points."""
    if n_clusters < 1:
        raise ValueError("n_clusters must be at least 1")

    counts = Counter(tuple(point) for point in points)
    duplicates = {
        point: count
        for point, count in sorted(counts.items())
        if count > 1
    }
    unique_points = sorted(counts)

    if not unique_points:
        return duplicates, []

    k = min(n_clusters, len(unique_points))
    coords = [tuple(map(float, point)) for point in unique_points]

    def squared_distance(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Deterministic farthest-first initialization.
    centers = [coords[0]]
    while len(centers) < k:
        next_index = max(
            range(len(coords)),
            key=lambda i: (
                min(squared_distance(coords[i], center) for center in centers),
                -i,
            ),
        )
        centers.append(coords[next_index])

    labels = None

    # Lloyd's k-means iterations.
    for _ in range(100):
        new_labels = [
            min(
                range(k),
                key=lambda j: (squared_distance(point, centers[j]), j),
            )
            for point in coords
        ]

        # Keep every cluster nonempty by moving a point from a cluster
        # containing more than one point into each empty cluster.
        cluster_sizes = [new_labels.count(j) for j in range(k)]
        for empty in range(k):
            if cluster_sizes[empty] == 0:
                candidates = [
                    i for i, label in enumerate(new_labels)
                    if cluster_sizes[label] > 1
                ]
                moved = max(
                    candidates,
                    key=lambda i: (
                        squared_distance(coords[i], centers[new_labels[i]]),
                        -i,
                    ),
                )
                cluster_sizes[new_labels[moved]] -= 1
                new_labels[moved] = empty
                cluster_sizes[empty] += 1

        new_centers = []
        for j in range(k):
            members = [coords[i] for i, label in enumerate(new_labels) if label == j]
            new_centers.append(tuple(
                sum(point[axis] for point in members) / len(members)
                for axis in range(2)
            ))

        if new_labels == labels:
            labels = new_labels
            break

        labels = new_labels
        centers = new_centers

    clusters = [
        sorted(unique_points[i] for i, label in enumerate(labels) if label == j)
        for j in range(k)
    ]
    return duplicates, sorted(clusters)
```

Duplicate counts are total occurrences, as in the example. The initialization and tie-breaking are deterministic; the clustering uses Lloyd’s k-means algorithm.

