from collections import Counter
from sklearn.cluster import KMeans


def cluster_unique_points(points, n_clusters):
    if not isinstance(n_clusters, int) or n_clusters < 1:
        raise ValueError("n_clusters must be a positive integer")

    counts = Counter(tuple(point) for point in points)
    unique_points = sorted(counts)

    duplicates = {
        point: counts[point]
        for point in unique_points
        if counts[point] > 1
    }

    if not unique_points:
        return duplicates, []

    k = min(n_clusters, len(unique_points))

    if k == len(unique_points):
        clusters = [[point] for point in unique_points]
    else:
        model = KMeans(n_clusters=k, random_state=0, n_init=10)
        labels = model.fit_predict(unique_points)

        clusters = [
            sorted(
                point
                for point, label in zip(unique_points, labels)
                if label == cluster_id
            )
            for cluster_id in range(k)
        ]
        clusters = [cluster for cluster in clusters if cluster]

    return duplicates, sorted(clusters)
```

This uses scikit-learn’s `KMeans`. The fixed `random_state` makes the result reproducible.

