from math import sqrt

def column_correlations(data):
    """Return pairwise Pearson correlations; constant columns get NaN."""
    columns = list(data)
    if not columns:
        return {}

    lengths = {len(data[name]) for name in columns}
    if len(lengths) != 1:
        raise ValueError("All columns must have equal length")

    n = lengths.pop()
    if n == 0:
        raise ValueError("Columns must not be empty")

    centered = {}
    sums_of_squares = {}
    for name in columns:
        values = data[name]
        mean = sum(values) / n
        centered[name] = [value - mean for value in values]
        sums_of_squares[name] = sum(x * x for x in centered[name])

    result = {x: {} for x in columns}
    for x in columns:
        for y in columns:
            sx, sy = sums_of_squares[x], sums_of_squares[y]
            if sx == 0 or sy == 0:
                result[x][y] = float("nan")
            elif x == y:
                result[x][y] = 1.0
            else:
                covariance_sum = sum(
                    a * b for a, b in zip(centered[x], centered[y])
                )
                result[x][y] = covariance_sum / sqrt(sx * sy)

    return result
