def column_correlations(data):
    """Return pairwise Pearson correlations for the columns in data.

    Correlations involving a constant column are undefined and returned as NaN.
    """
    if not data:
        return {}

    lengths = {len(values) for values in data.values()}
    if len(lengths) != 1:
        raise ValueError("All columns must have equal lengths")

    n = lengths.pop()
    if n == 0:
        raise ValueError("Columns must not be empty")

    means = {
        name: sum(values) / n
        for name, values in data.items()
    }
    centered = {
        name: [value - means[name] for value in values]
        for name, values in data.items()
    }
    sums_of_squares = {
        name: sum(value * value for value in values)
        for name, values in centered.items()
    }

    result = {}
    for x in data:
        result[x] = {}
        for y in data:
            denominator = sqrt(sums_of_squares[x] * sums_of_squares[y])
            if denominator == 0:
                result[x][y] = float("nan")
            else:
                numerator = sum(
                    a * b for a, b in zip(centered[x], centered[y])
                )
                result[x][y] = numerator / denominator

    return result
