from math import sqrt

def column_correlations(data):
    columns = list(data)
    if not columns:
        return {}

    lengths = {len(data[name]) for name in columns}
    if len(lengths) != 1:
        raise ValueError("All columns must have equal length")

    n = lengths.pop()
    if n == 0:
        raise ValueError("Columns must contain at least one value")

    centered = {}
    norms = {}

    for name in columns:
        values = data[name]
        mean = sum(values) / n
        centered[name] = [value - mean for value in values]
        norms[name] = sqrt(sum(value * value for value in centered[name]))
        if norms[name] == 0:
            raise ValueError(f"Correlation is undefined for constant column {name!r}")

    result = {}
    for x in columns:
        result[x] = {}
        for y in columns:
            numerator = sum(a * b for a, b in zip(centered[x], centered[y]))
            result[x][y] = numerator / (norms[x] * norms[y])

    return result
```

This uses Pearson correlation and raises `ValueError` when a column is constant, since its correlation is undefined.

