import csv
import io


def sort_csv_rows(csv_text, sort_by_column="title"):
    reader = csv.reader(io.StringIO(csv_text))
    headers = next(reader, None)

    if not headers:
        return []
    if sort_by_column not in headers:
        raise ValueError(f"Unknown column: {sort_by_column}")

    rows = [row for row in reader if row]

    # Pad short rows with empty strings; ignore any extra fields.
    rows = [
        (row + [""] * len(headers))[:len(headers)]
        for row in rows
    ]

    def parse_number(value):
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return None

    numeric_columns = {}
    for index, column in enumerate(headers):
        parsed = [parse_number(row[index]) for row in rows]
        if rows and all(value is not None for value in parsed):
            numeric_columns[column] = parsed

    result = []
    for row_index, row in enumerate(rows):
        item = {}
        for index, column in enumerate(headers):
            if column in numeric_columns:
                item[column] = numeric_columns[column][row_index]
            else:
                item[column] = row[index]
        result.append(item)

    return sorted(result, key=lambda item: item[sort_by_column])
