import csv
import io


def sort_csv_rows(csv_text, sort_by_column="title"):
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return []

    headers = rows[0]
    if sort_by_column not in headers:
        raise ValueError(f"Column not found: {sort_by_column}")

    values = [row for row in rows[1:] if row]
    columns = list(zip(*values)) if values else [()] * len(headers)

    def as_number(value):
        try:
            return float(value)
        except ValueError:
            return None

    numeric = [
        bool(column) and all(value.strip() and as_number(value) is not None
                             for value in column)
        for column in columns
    ]

    def convert(value, is_numeric):
        if not is_numeric:
            return value
        number = float(value)
        return int(number) if number.is_integer() and not any(
            marker in value.lower() for marker in (".", "e")
        ) else number

    result = [
        {
            header: convert(row[i], numeric[i])
            for i, header in enumerate(headers)
        }
        for row in values
    ]

    result.sort(key=lambda row: row[sort_by_column])
    return result
