            return None

        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return None

    # Convert a column only when every row has a numeric value for it.
    for column in columns:
        numbers = [parse_number(row[column]) for row in rows]
        if numbers and all(number is not None for number in numbers):
            for row, number in zip(rows, numbers):
                row[column] = number

    return sorted(rows, key=lambda row: row[sort_by_column])
