def format_sorted_dict_table(my_dict):
    rows = [(str(key), str(value)) for key, value in sorted(my_dict.items())]

    key_width = max([len("Key")] + [len(key) for key, _ in rows])
    value_width = max([len("Value")] + [len(value) for _, value in rows])

    def border():
        return f"+{'-' * (key_width + 2)}+{'-' * (value_width + 2)}+"

    def row(key, value):
        return (
            f"| {key.center(key_width)} "
            f"| {value.center(value_width)} |"
        )

    lines = [
        border(),
        row("Key", "Value"),
        border(),
        *(row(key, value) for key, value in rows),
        border(),
    ]
    return "\n".join(lines)
