def encode_csv_column(csv_text, column_name):
    rows = list(csv.reader(StringIO(csv_text, newline="")))

    try:
        column_index = rows[0].index(column_name)
    except (IndexError, ValueError):
        raise ValueError(f"Column {column_name!r} does not exist") from None

    def clean(value):
        return value.replace("\r\n", "\n").replace("\r", "\n").replace("\n", "<br>")

    values = [clean(row[column_index]) for row in rows[1:]]
    classes = sorted(set(values))
    class_index = {value: i for i, value in enumerate(classes)}
    codes = [class_index[value] for value in values]

    return classes, codes
