import math


def spectrum_magnitude_histogram(pairs):
    values = [value for _, value in pairs]
    n = len(values)

    if n == 0:
        return [], []

    magnitudes = []
    for k in range(n):
        real = sum(
            value * math.cos(2 * math.pi * k * j / n)
            for j, value in enumerate(values)
        )
        imag = -sum(
            value * math.sin(2 * math.pi * k * j / n)
            for j, value in enumerate(values)
        )
        magnitudes.append(math.hypot(real, imag))

    counts = [0] * 10
    low = min(magnitudes)
    high = max(magnitudes)

    if low == high:
        counts[0] = n
    else:
        width = (high - low) / 10
        for magnitude in magnitudes:
            bin_index = min(int((magnitude - low) / width), 9)
            counts[bin_index] += 1

    return magnitudes, counts
```

