        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError("Malformed XML") from exc

    def convert(element):
        children = list(element)

        # Include direct text before, between, and after child elements.
        text_parts = [element.text or ""]
        text_parts.extend(child.tail or "" for child in children)
        text = "".join(text_parts).strip()

        if not element.attrib and not children:
            return text or None

        result = {f"@{key}": value for key, value in element.attrib.items()}

        if text:
            result["#text"] = text

        for child in children:
            tag = child.tag
            value = convert(child)

            if tag not in result:
                result[tag] = value
            elif isinstance(result[tag], list):
                result[tag].append(value)
            else:
                result[tag] = [result[tag], value]

        return result

    return {root.tag: convert(root)}
