import math
from numbers import Real


def row_averages_and_correlations(data):
    """Return (row averages, Pearson correlation matrix of the columns)."""
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")

    if not data:
        return [], []

    if any(not isinstance(row, list) for row in data):
        raise ValueError("each row must be a list")

    ncols = len(data[0])
    if any(len(row) != ncols for row in data):
        raise ValueError("data must be rectangular")
    if ncols == 0:
        raise ValueError("rows must contain at least one number")

    for row in data:
        for value in row:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError("all entries must be real numbers")

    values = [[float(value) for value in row] for row in data]
    averages = [math.fsum(row) / ncols for row in values]

    nrows = len(values)
    if nrows < 2:
        raise ValueError("correlations require at least two rows")

    columns = [[row[j] for row in values] for j in range(ncols)]
    means = [math.fsum(col) / nrows for col in columns]
    centered = [
        [value - means[j] for value in col]
        for j, col in enumerate(columns)
    ]
    sums_of_squares = [
        math.fsum(value * value for value in col)
        for col in centered
    ]

    if any(s == 0 for s in sums_of_squares):
        raise ValueError("correlation is undefined for a constant column")

    corr = []
    for i in range(ncols):
        row = []
        for j in range(ncols):
            numerator = math.fsum(
                centered[i][k] * centered[j][k] for k in range(nrows)
            )
            row.append(numerator / math.sqrt(sums_of_squares[i] * sums_of_squares[j]))
        corr.append(row)

    return averages, corr
```

A correlation is undefined when a column is constant or there are fewer than two rows, so those cases raise `ValueError` as well.

```python
from math import sqrt
from numbers import Real


def row_averages_and_correlations(data):
    """Return row means and the Pearson correlation matrix of the columns.

    Correlations involving a constant column, or computed from fewer than
    two observations, are undefined and returned as float("nan").
    """
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")
    if not data:
        return [], []
    if any(not isinstance(row, list) for row in data):
        raise ValueError("each row must be a list")

    ncols = len(data[0])
    if ncols == 0:
        raise ValueError("rows must contain at least one number")
    if any(len(row) != ncols for row in data):
        raise ValueError("data must be rectangular")
    if any(not isinstance(value, Real) for row in data for value in row):
        raise ValueError("all entries must be numbers")

    nrows = len(data)
    averages = [sum(row) / ncols for row in data]

    columns = [[data[r][c] for r in range(nrows)] for c in range(ncols)]
    col_means = [sum(col) / nrows for col in columns]
    centered = [
        [value - col_means[c] for value in columns[c]]
        for c in range(ncols)
    ]
    sums_of_squares = [sum(x * x for x in col) for col in centered]

    corr = []
    for i in range(ncols):
        row = []
        for j in range(ncols):
            denominator = sqrt(sums_of_squares[i] * sums_of_squares[j])
            if denominator == 0:
                row.append(float("nan"))
            else:
                value = sum(
                    centered[i][k] * centered[j][k] for k in range(nrows)
                ) / denominator
                row.append(max(-1.0, min(1.0, value)))
        corr.append(row)

    return averages, corr
```

For the example, this returns `([3.0, 2.0, 3.5], [[1.0, 0.5], [0.5, 1.0]])`. Empty input returns `([], [])`; rows with no columns raise `ValueError` because their averages are undefined.

