from math import sqrt


def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must be nonempty")

    if any(not row for row in P):
        raise ValueError("P must have at least one column")

    m = len(P)
    k = len(P[0])
    if any(len(row) != k for row in P):
        raise ValueError("P must be rectangular")

    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")

    if any(not layer for layer in T):
        raise ValueError("T must have a nonempty second dimension")

    n = len(T[0])
    if any(len(layer) != n for layer in T):
        raise ValueError("T must have a consistent second dimension")

    if not T[0][0]:
        raise ValueError("T must have a nonempty third dimension")

    p = len(T[0][0])
    if any(len(row) != p for layer in T for row in layer):
        raise ValueError("T must have a consistent third dimension")

    # Compute each slice product and flatten its rows.
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for q in range(p):
                row.append(sum(P[i][a] * T[a][j][q] for a in range(k)))
        table.append(row)

    # Standardize each column using population standard deviation.
    for c in range(m * p):
        mean = sum(row[c] for row in table) / n
        std = sqrt(sum((row[c] - mean) ** 2 for row in table) / n)
        for row in table:
            row[c] = 0.0 if std == 0 else float((row[c] - mean) / std)

    return table
