import math


def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must be non-empty")

    m = len(P)
    k = len(P[0])
    if k == 0 or any(len(row) != k for row in P):
        raise ValueError("P must be a non-empty rectangular matrix")

    if len(T) != k:
        raise ValueError("P's number of columns must match T's first dimension")

    n = len(T[0])
    if n == 0:
        raise ValueError("T must be non-empty")

    p = len(T[0][0]) if T[0] else 0
    if p == 0 or any(
        len(slice_) != n or any(len(row) != p for row in slice_)
        for slice_ in T
    ):
        raise ValueError("T must be a non-empty rectangular tensor")

    # Each table row is the flattened product P @ T[:, j, :].
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for col in range(p):
                value = sum(P[i][a] * T[a][j][col] for a in range(k))
                row.append(float(value))
        table.append(row)

    # Standardise each column using the population standard deviation.
    for col in range(m * p):
        mean = sum(row[col] for row in table) / n
        variance = sum((row[col] - mean) ** 2 for row in table) / n
        if variance == 0:
            for row in table:
                row[col] = 0.0
        else:
            stddev = math.sqrt(variance)
            for row in table:
                row[col] = (row[col] - mean) / stddev

    return table
