def scale_by_group_with_histogram(ids, ages, incomes):
    if not ids:
        raise ValueError("At least one row is required")
    if len(ids) != len(ages) or len(ids) != len(incomes):
        raise ValueError("ids, ages, and incomes must have equal lengths")

    bounds = {}
    for group_id, age, income in zip(ids, ages, incomes):
        if group_id not in bounds:
            bounds[group_id] = [age, age, income, income]
        else:
            b = bounds[group_id]
            b[0] = min(b[0], age)
            b[1] = max(b[1], age)
            b[2] = min(b[2], income)
            b[3] = max(b[3], income)

    scaled = []
    counts = [0] * 10

    for group_id, age, income in zip(ids, ages, incomes):
        min_age, max_age, min_income, max_income = bounds[group_id]

        if min_age == max_age:
            scaled_age = 0.0
        else:
            scale = 1.0 / (max_age - min_age)
            scaled_age = age * scale - min_age * scale

        if min_income == max_income:
            scaled_income = 0.0
        else:
            scale = 1.0 / (max_income - min_income)
            scaled_income = income * scale - min_income * scale

        scaled.append([scaled_age, scaled_income])

        # The final bin includes 1; clamp for floating-point edge cases.
        bin_index = min(9, max(0, int(scaled_income * 10)))
        counts[bin_index] += 1

    return scaled, counts
