def scale_by_group_with_histogram(ids, ages, incomes):
    if not (len(ids) == len(ages) == len(incomes)):
        raise ValueError("ids, ages, and incomes must have equal lengths")
    if not ids:
        raise ValueError("at least one row is required")

    groups = {}
    for i, group_id in enumerate(ids):
        groups.setdefault(group_id, []).append(i)

    scaled = [[0.0, 0.0] for _ in ids]

    for indices in groups.values():
        for column, values in enumerate((ages, incomes)):
            group_values = [values[i] for i in indices]
            low, high = min(group_values), max(group_values)

            if low == high:
                continue  # Constant within the group: leave values at 0.0.

            scale = 1.0 / (high - low)
            offset = -low * scale
            for i in indices:
                scaled[i][column] = values[i] * scale + offset

    counts = [0] * 10
    for _, scaled_income in scaled:
        # Clamp the bin index to handle the endpoint 1 and floating-point
        # rounding near the endpoints.
        bin_index = max(0, min(9, int(scaled_income * 10)))
        counts[bin_index] += 1

    return scaled, counts
