import numpy as np

def fit_linear_regression(records, target="z"):
    if not records:
        raise ValueError("records must not be empty")

    keys = list(records[0])
    if target not in keys:
        raise KeyError(f"target {target!r} is not in the records")

    predictors = [key for key in keys if key != target]
    X = np.array(
        [[1.0] + [record[key] for key in predictors] for record in records],
        dtype=float,
    )
    y = np.array([record[target] for record in records], dtype=float)

    fitted, *_ = np.linalg.lstsq(X, y, rcond=None)
    intercept = float(fitted[0])
    coefficients = {
        key: float(fitted[i + 1])
        for i, key in enumerate(predictors)
    }
    return intercept, coefficients
```

This uses NumPy’s least-squares solver, including when predictors are linearly dependent.

