import math

def first_column_match_stats(target_value, rows):
    indices = [
        i for i, row in enumerate(rows)
        if row and row[0] == target_value
    ]

    if not indices:
        return ('N/A', 'N/A', 'N/A', 'N/A')

    mean = math.fsum(indices) / len(indices)

    if len(indices) == 1:
        return (mean, 'N/A', 'N/A', 'N/A')

    deviations = [i - mean for i in indices]
    variance = math.fsum(d * d for d in deviations) / len(indices)
    skewness = (
        math.fsum(d ** 3 for d in deviations) / len(indices)
        / variance ** 1.5
    )
    kurtosis = (
        math.fsum(d ** 4 for d in deviations) / len(indices)
        / variance ** 2
        - 3
    )

    return (mean, variance, skewness, kurtosis)
```

This uses zero-based row indices, population variance, biased skewness, and excess (Fisher) kurtosis. Empty rows are ignored because they have no first cell.

