from math import sqrt


def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}

    for column, values in data.items():
        # Apply replacements first.
        values = [
            replacements[value] if value in replacements else value
            for value in values
        ]

        # Encode distinct values in sorted order if the column contains strings.
        if any(isinstance(value, str) for value in values):
            categories = sorted(set(values))
            codes = {value: i for i, value in enumerate(categories)}
            values = [codes[value] for value in values]

        numbers = [float(value) for value in values]
        n = len(numbers)
        if n < 2:
            raise ValueError(f"column {column!r} needs at least two values")

        mean = sum(numbers) / n
        sample_std = sqrt(sum((x - mean) ** 2 for x in numbers) / (n - 1))
        if sample_std == 0:
            raise ValueError(f"column {column!r} has zero sample standard deviation")

        result[column] = [(x - mean) / sample_std for x in numbers]

    return result
```

This uses the sample standard deviation (denominator `n - 1`). Columns with fewer than two values or zero variance cannot be standardized this way, so the function raises `ValueError` for them.

