import math


def encode_and_standardize(data, replacements):
    """Replace values, encode string columns, then standardize each column."""
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    if not data:
        return {}

    columns = {}
    lengths = set()

    for name, values in data.items():
        values = list(values)
        lengths.add(len(values))

        replaced = []
        for value in values:
            try:
                value = replacements.get(value, value)
            except TypeError:  # For unhashable values, no dict key can match.
                pass
            replaced.append(value)

        if any(isinstance(value, str) for value in replaced):
            try:
                categories = sorted(set(replaced))
            except TypeError as exc:
                raise ValueError(
                    f"Column {name!r} contains values that cannot be sorted together"
                ) from exc
            codes = {value: i for i, value in enumerate(categories)}
            replaced = [codes[value] for value in replaced]

        columns[name] = replaced

    if len(lengths) > 1:
        raise ValueError("All columns must have equal length")

    result = {}
    for name, values in columns.items():
        n = len(values)
        if n < 2:
            raise ValueError("At least two rows are needed for sample standardization")

        mean = sum(values) / n
        sample_std = math.sqrt(sum((value - mean) ** 2 for value in values) / (n - 1))
        if sample_std == 0:
            raise ValueError(f"Column {name!r} has zero sample standard deviation")

        result[name] = [(value - mean) / sample_std for value in values]

    return result
```

