import math

def standardize_and_correlate(rows):
    if not rows:
        return [], []

    n_rows = len(rows)
    n_cols = len(rows[0])

    if any(len(row) != n_cols for row in rows):
        raise ValueError("All rows must have the same number of columns.")

    standardized_columns = []

    for j in range(n_cols):
        observed = [row[j] for row in rows if row[j] is not None]
        if not observed:
            raise ValueError(f"Column {j} contains only missing values.")

        mean = math.fsum(observed) / len(observed)
        filled = [mean if row[j] is None else row[j] for row in rows]

        variance = math.fsum((x - mean) ** 2 for x in filled) / n_rows
        std = math.sqrt(variance)
        if std == 0:
            raise ValueError(f"Column {j} has zero variance.")

        standardized_columns.append([(x - mean) / std for x in filled])

    standardized = [
        [standardized_columns[j][i] for j in range(n_cols)]
        for i in range(n_rows)
    ]

    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for j in range(n_cols):
        corr[j][j] = 1.0
        for k in range(j + 1, n_cols):
            value = math.fsum(
                standardized_columns[j][i] * standardized_columns[k][i]
                for i in range(n_rows)
            ) / n_rows
            corr[j][k] = corr[k][j] = value

    return standardized, corr
```

