```python
from math import fsum, sqrt


def standardize_and_correlate(rows):
    """Mean-impute missing values, standardize columns, and return their correlations.

    Raises ValueError for all-missing or constant columns, whose standard
    deviation or Pearson correlations are undefined.
    """
    if not rows:
        return [], []

    n_rows = len(rows)
    n_cols = len(rows[0])

    if any(len(row) != n_cols for row in rows):
        raise ValueError("All rows must have the same number of columns")

    filled = [list(row) for row in rows]

    for j in range(n_cols):
        observed = [row[j] for row in rows if row[j] is not None]
        if not observed:
            raise ValueError(f"Column {j} contains only missing values")

        mean = fsum(observed) / len(observed)
        for row in filled:
            if row[j] is None:
                row[j] = mean

    means = [
        fsum(filled[i][j] for i in range(n_rows)) / n_rows
        for j in range(n_cols)
    ]
    stds = [
        sqrt(fsum((filled[i][j] - means[j]) ** 2 for i in range(n_rows)) / n_rows)
        for j in range(n_cols)
    ]

    if any(std == 0 for std in stds):
        raise ValueError("Cannot standardize a constant column")

    standardized = [
        [(filled[i][j] - means[j]) / stds[j] for j in range(n_cols)]
        for i in range(n_rows)
    ]

    corr = []
    for j in range(n_cols):
        corr_row = []
        for k in range(n_cols):
            value = fsum(
                standardized[i][j] * standardized[i][k]
                for i in range(n_rows)
            ) / n_rows
            corr_row.append(1.0 if j == k else value)
        corr.append(corr_row)

    return standardized, corr
