import math


def summarize_stock_column(column, data):
    columns = {"Open": 1, "High": 2, "Low": 3, "Close": 4, "Volume": 5}

    if column not in columns:
        raise ValueError(f"Unknown column: {column!r}")

    values = []
    for row in data:
        if len(row) != 6:
            raise ValueError("Each row must have exactly six entries")
        value = row[columns[column]]
        if value is not None:
            values.append(float(value))

    count = len(values)
    if count == 0:
        missing = float("nan")
        return {
            "count": 0, "mean": missing, "std": missing, "min": missing,
            "25%": missing, "50%": missing, "75%": missing, "max": missing,
        }

    values.sort()
    mean = sum(values) / count
    std = (
        math.sqrt(sum((value - mean) ** 2 for value in values) / (count - 1))
        if count > 1 else float("nan")
    )

    def percentile(p):
        position = (count - 1) * p
        lower = int(position)
        upper = min(lower + 1, count - 1)
        fraction = position - lower
        return values[lower] + fraction * (values[upper] - values[lower])

    return {
        "count": count,
        "mean": mean,
        "std": std,
        "min": values[0],
        "25%": percentile(0.25),
        "50%": percentile(0.50),
        "75%": percentile(0.75),
        "max": values[-1],
    }
