def correlation_without_column(data, column):
    numeric = {
        name: [float(value) for value in values]
        for name, values in data.items()
        if name != column
        and all(isinstance(value, Real) and not isinstance(value, bool)
                for value in values)
    }

    if not numeric:
        return None

    centered = {}
    variances = {}

    for name, values in numeric.items():
        mean = math.fsum(values) / len(values) if values else float("nan")
        centered[name] = [value - mean for value in values]
        variances[name] = math.fsum(delta * delta for delta in centered[name])

    result = {}
    for x in numeric:
        result[x] = {}
        for y in numeric:
            denominator = math.sqrt(variances[x] * variances[y])
            result[x][y] = (
                math.fsum(a * b for a, b in zip(centered[x], centered[y]))
                / denominator
                if denominator
                else float("nan")
            )

    return result
