import math
from numbers import Real


def correlation_without_column(data, column):
    """Return Pearson correlations for numeric columns, excluding `column`.

    Columns containing non-numeric values are ignored. Correlations involving
    a constant column (or too few observations) are returned as NaN.
    """
    numeric = {
        name: [float(value) for value in values]
        for name, values in data.items()
        if name != column
        and all(isinstance(value, Real) and not isinstance(value, bool)
                for value in values)
    }

    if not numeric:
        return None

    names = list(numeric)
    result = {name: {} for name in names}

    for x in names:
        xs = numeric[x]
        mean_x = math.fsum(xs) / len(xs) if xs else float("nan")
        centered_x = [value - mean_x for value in xs]
        sum_x = math.fsum(value * value for value in centered_x)

        for y in names:
            ys = numeric[y]
            mean_y = math.fsum(ys) / len(ys) if ys else float("nan")
            centered_y = [value - mean_y for value in ys]
            sum_y = math.fsum(value * value for value in centered_y)

            if sum_x == 0 or sum_y == 0:
                result[x][y] = float("nan")
            else:
                covariance = math.fsum(
                    a * b for a, b in zip(centered_x, centered_y)
                )
                result[x][y] = covariance / math.sqrt(sum_x * sum_y)

    return result
