    means = {
        name: math.fsum(numeric[name]) / len(numeric[name])
        for name in names
    }
    centered = {
        name: [value - means[name] for value in numeric[name]]
        for name in names
    }
    sums_of_squares = {
        name: math.fsum(value * value for value in centered[name])
        for name in names
    }

    result = {}
    for x in names:
        result[x] = {}
        for y in names:
            denominator = math.sqrt(sums_of_squares[x] * sums_of_squares[y])
            result[x][y] = (
                math.fsum(a * b for a, b in zip(centered[x], centered[y]))
                / denominator
                if denominator
                else float("nan")
            )

    return result
