    def centered(values):
        if not values:
            return None
        mean = sum(values) / len(values)
        return [value - mean for value in values]

    centered_columns = {name: centered(values) for name, values in numeric.items()}
    result = {name: {} for name in numeric}

    for x, xs in centered_columns.items():
        for y, ys in centered_columns.items():
            if xs is None or ys is None:
                result[x][y] = math.nan
                continue

            sum_xx = sum(value * value for value in xs)
            sum_yy = sum(value * value for value in ys)
            if sum_xx == 0 or sum_yy == 0:
                result[x][y] = math.nan
            else:
                sum_xy = sum(a * b for a, b in zip(xs, ys))
                result[x][y] = sum_xy / math.sqrt(sum_xx * sum_yy)

    return result
