def column_histograms(table):
    if not isinstance(table, dict) or not table:
        raise ValueError("table must be a non-empty dict")

    histograms = {}

    for name, values in table.items():
        # Empty columns have no range, so they cannot produce a histogram.
        if not values or not all(
            isinstance(value, Real) and not isinstance(value, bool)
            for value in values
        ):
            continue

        minimum = min(values)
        maximum = max(values)
        counts = [0] * 10

        if minimum == maximum:
            # With a zero-width range, put every value in the last bin.
            counts[-1] = len(values)
        else:
            width = (maximum - minimum) / 10
            for value in values:
                index = int((value - minimum) / width)
                counts[min(index, 9)] += 1  # The maximum belongs in the last bin.

        histograms[name] = counts

    if not histograms:
        raise ValueError("table has no numeric columns")

    return histograms
