        return {}

    tokenized = [
        re.findall(r"\w{2,}", content.lower())
        for content in selected
    ]
    term_counts = [Counter(tokens) for tokens in tokenized]

    n_articles = len(selected)
    document_frequency = Counter(
        word
        for counts in term_counts
        for word in counts
    )

    totals = defaultdict(float)

    for counts in term_counts:
        weighted = {
            word: count * (math.log((1 + n_articles) / (1 + document_frequency[word])) + 1)
            for word, count in counts.items()
        }
        norm = math.sqrt(sum(score * score for score in weighted.values()))

        if norm:
            for word, score in weighted.items():
                totals[word] += score / norm

