        weighted = {
            word: count * (math.log((1 + n_documents) / (1 + document_frequency[word])) + 1)
            for word, count in document.items()
        }

        norm = math.sqrt(sum(score * score for score in weighted.values()))
        if norm:
            for word, score in weighted.items():
                totals[word] += score / norm

    return dict(totals)
