import re

def bag_of_words_vector(text, corpus):
    def words(s):
        return [word.casefold() for word in re.findall(r"\w{2,}", s)]

    text_words = words(text)
    vocabulary = sorted(set(text_words).union(
        word for sentence in corpus for word in words(sentence)
    ))

    counts = {word: 0 for word in vocabulary}
    for word in text_words:
        counts[word] += 1

    return [counts[word] for word in vocabulary]
