from math import sqrt
from numbers import Real


def summarize_distribution(values, bins):
    if not values:
        raise ValueError("values must be non-empty")
    if isinstance(bins, bool) or not isinstance(bins, int) or bins <= 0:
        raise ValueError("bins must be a positive integer")
    if any(not isinstance(value, Real) for value in values):
        raise TypeError("values must contain numbers")

    count = len(values)
    mean = sum(values) / count

    ordered = sorted(values)
    middle = count // 2
    if count % 2:
        median = ordered[middle]
    else:
        median = (ordered[middle - 1] + ordered[middle]) / 2

    frequencies = {}
    for value in values:
        frequencies[value] = frequencies.get(value, 0) + 1
    highest_frequency = max(frequencies.values())
    mode = next(value for value in values
                if frequencies[value] == highest_frequency)

    std_dev = sqrt(sum((value - mean) ** 2 for value in values) / count)

    histogram = [0] * bins
    minimum, maximum = min(values), max(values)
    if minimum == maximum:
        # With a zero-width range, put all values in the first bin.
        histogram[0] = count
    else:
        width = (maximum - minimum) / bins
        for value in values:
            index = int((value - minimum) / width)
            histogram[min(index, bins - 1)] += 1  # Include the maximum.

    return {
        "mean": mean,
        "median": median,
        "mode": mode,
        "std_dev": std_dev,
        "histogram": histogram,
    }
