import math
import re
from collections import Counter

def bracket_free_tfidf(texts):
    tokenized = [
        re.findall(r"\w{2,}", re.sub(r"\[.*?\]", "", text, flags=re.DOTALL).lower())
        for text in texts
    ]

    n = len(texts)
    counts = [Counter(words) for words in tokenized]
    document_frequency = Counter(
        word for counter in counts for word in counter
    )

    result = []
    for counter in counts:
        scores = {
            word: count * (math.log((1 + n) / (1 + document_frequency[word])) + 1)
            for word, count in counter.items()
        }
        norm = math.sqrt(sum(score * score for score in scores.values()))
        result.append(
            {word: score / norm for word, score in scores.items()}
            if norm else {}
        )

    return result
```

