import math
import re
from collections import Counter

_WORD_RE = re.compile(r"\w{2,}", re.UNICODE)


def _without_brackets(text):
    """Remove bracketed text, including nested bracket pairs."""
    result = []
    depth = 0

    for char in text:
        if char == "[":
            depth += 1
            if depth == 1:
                result.append(" ")
        elif char == "]":
            if depth:
                depth -= 1
                if depth == 0:
                    result.append(" ")
            elif depth == 0:
                result.append(char)
        elif depth == 0:
            result.append(char)

    return "".join(result)


def bracket_free_tfidf(texts):
    counts = [
        Counter(word.lower() for word in _WORD_RE.findall(_without_brackets(text)))
        for text in texts
    ]

    n = len(texts)
    document_frequency = Counter(
        word for doc in counts for word in doc
    )

    result = []
    for doc in counts:
        weighted = {
            word: count * (math.log((1 + n) / (1 + document_frequency[word])) + 1)
            for word, count in doc.items()
        }
        length = math.sqrt(sum(score * score for score in weighted.values()))
        result.append(
            {word: score / length for word, score in weighted.items()}
            if length else {}
        )

    return result
