def column_histogram(records, column_name):
    if not records or any(column_name not in row for row in records):
        raise ValueError(f"Column {column_name!r} does not exist in the table")

    values = [row[column_name] for row in records]

    if all(isinstance(value, str) for value in values):
        categories = sorted(set(values))
        indices = {value: i for i, value in enumerate(categories)}
        values = [indices[value] for value in values]
    elif any(isinstance(value, str) for value in values):
        raise TypeError("Column values must be all strings or all numeric")

    minimum = min(values)
    maximum = max(values)
    counts = [0] * 10

    if minimum == maximum:
        # The sole value is also the maximum, so it belongs in the last bin.
        counts[9] = len(values)
        return counts

    for value in values:
        if value == maximum:
            bin_index = 9
        else:
            bin_index = int((value - minimum) * 10 / (maximum - minimum))
            bin_index = min(bin_index, 9)
        counts[bin_index] += 1

    return counts
```

