    y_mean = sum(train_y) / len(train_y)

    x_variance = sum((x - x_mean) ** 2 for x in train_x)
    if x_variance == 0:
        raise ValueError("training x values must not all be identical")

    slope = sum(
        (x - x_mean) * (y - y_mean)
        for x, y in zip(train_x, train_y)
    ) / x_variance
    intercept = y_mean - slope * x_mean

    test_y_mean = sum(test_y) / len(test_y)
    residual_sum = sum(
        (y - (slope * x + intercept)) ** 2
        for x, y in zip(test_x, test_y)
    )
    total_sum = sum((y - test_y_mean) ** 2 for y in test_y)

    r_squared = 1 - residual_sum / total_sum if total_sum else math.nan
