        "%Y.%m.%d", "%m.%d.%Y", "%d.%m.%Y",
        "%B %d, %Y", "%b %d, %Y",
        "%d %B %Y", "%d %b %Y",
    )
    counts = Counter()

    for row in rows:
        if not row:  # Ignore blank lines.
            continue

        try:
            value = row[column_index].strip()
        except IndexError:
            raise ValueError("A CSV row is missing the date column") from None

        parsed = None
        try:
            parsed = date.fromisoformat(value)
        except ValueError:
            try:
                parsed = datetime.fromisoformat(
                    value.replace("Z", "+00:00")
                ).date()
            except ValueError:
                for fmt in formats:
                    try:
                        parsed = datetime.strptime(value, fmt).date()
                        break
                    except ValueError:
                        pass

        if parsed is None:
            raise ValueError(f"Invalid date: {value!r}")

        counts[parsed.year] += 1

    return dict(counts)
```

The parser supports the listed date formats, ISO dates, and ISO timestamps. Any nonblank value it cannot parse raises `ValueError`.

