def count_dates_by_year(csv_text, date_column):
    reader = csv.DictReader(io.StringIO(csv_text))

    if reader.fieldnames is None or date_column not in reader.fieldnames:
        raise ValueError(f"Column {date_column!r} not found")

    formats = (
        "%Y/%m/%d",
        "%m/%d/%Y",
        "%m-%d-%Y",
        "%B %d, %Y",
        "%b %d, %Y",
        "%B %d %Y",
        "%b %d %Y",
        "%d %B %Y",
        "%d %b %Y",
    )

    counts = {}

    for row_number, row in enumerate(reader, start=2):
        value = row.get(date_column)
        parsed = None

        if value is not None:
            value = value.strip()
            try:
                parsed = date.fromisoformat(value)
            except ValueError:
                for fmt in formats:
                    try:
                        parsed = datetime.strptime(value, fmt).date()
                        break
                    except ValueError:
                        pass

        if parsed is None:
            raise ValueError(f"Invalid date in row {row_number}: {value!r}")

        counts[parsed.year] = counts.get(parsed.year, 0) + 1

    return counts
