import xml.etree.ElementTree as ET


def xml_to_dict(s):
    if not s or not s.strip():
        raise ValueError("XML input must not be empty")

    root = ET.fromstring(s)

    def convert(element):
        children = list(element)

        # Include text before, between, and after child elements.
        text_parts = [element.text or ""]
        for child in children:
            text_parts.append(child.tail or "")
        text = "".join(text_parts)

        if not children and not element.attrib:
            return text if text else None

        result = {f"@{name}": value for name, value in element.attrib.items()}

        grouped = {}
        for child in children:
            grouped.setdefault(child.tag, []).append(convert(child))

        for tag, values in grouped.items():
            result[tag] = values[0] if len(values) == 1 else values

        if text:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
```

