import xml.etree.ElementTree as ET


def xml_to_dict(s):
    if not s or not s.strip():
        raise ValueError("XML input must not be empty or whitespace")

    root = ET.fromstring(s)

    def convert(elem):
        children = list(elem)

        # A plain text element maps directly to its text; an empty one to None.
        if not elem.attrib and not children:
            return elem.text

        result = {"@" + name: value for name, value in elem.attrib.items()}

        # Collect text belonging directly to this element, including text after
        # child elements.
        text = (elem.text or "") + "".join(child.tail or "" for child in children)
        if text:
            result["#text"] = text

        for child in children:
            value = convert(child)
            if child.tag in result:
                if not isinstance(result[child.tag], list):
                    result[child.tag] = [result[child.tag]]
                result[child.tag].append(value)
            else:
                result[child.tag] = value

        return result

    return {root.tag: convert(root)}
