def dbscan_cluster_labels(points):
    eps_squared = 3 ** 2
    min_samples = 2
    n = len(points)

    labels = [None] * n
    visited = [False] * n

    def region(point_index):
        return [
            j for j, point in enumerate(points)
            if sum(
                (a - b) ** 2
                for a, b in zip(points[point_index], point)
            ) <= eps_squared
        ]

    cluster_id = 0

    for i in range(n):
        if visited[i]:
            continue

        visited[i] = True
        neighbors = region(i)

        if len(neighbors) < min_samples:
            labels[i] = -1
            continue

        labels[i] = cluster_id
        queue = list(neighbors)
        queued = set(queue)
        cursor = 0

        while cursor < len(queue):
            j = queue[cursor]
            cursor += 1

            if not visited[j]:
                visited[j] = True
                more_neighbors = region(j)

                if len(more_neighbors) >= min_samples:
                    for k in more_neighbors:
                        if k not in queued:
                            queue.append(k)
                            queued.add(k)

            # A previously marked noise point can be a border point.
            if labels[j] is None or labels[j] == -1:
                labels[j] = cluster_id

        cluster_id += 1

    return labels
```

