def dbscan_cluster_labels(points):
    eps_squared = 3 ** 2
    min_samples = 2
    n = len(points)

    # -2 means not yet visited; -1 means noise.
    labels = [-2] * n

    def neighbors(i):
        result = []
        for j, point in enumerate(points):
            distance_squared = sum(
                (a - b) ** 2 for a, b in zip(points[i], point)
            )
            if distance_squared <= eps_squared:
                result.append(j)
        return result

    cluster_id = 0

    for i in range(n):
        if labels[i] != -2:
            continue

        nearby = neighbors(i)
        if len(nearby) < min_samples:
            labels[i] = -1
            continue

        labels[i] = cluster_id
        queue = [j for j in nearby if j != i]
        queued = set(queue)

        while queue:
            j = queue.pop(0)

            if labels[j] == -1:
                # A noise point can be a border point of this cluster.
                labels[j] = cluster_id
            elif labels[j] != -2:
                continue
            else:
                labels[j] = cluster_id
                nearby_j = neighbors(j)
                if len(nearby_j) >= min_samples:
                    for k in nearby_j:
                        if k not in queued:
                            queue.append(k)
                            queued.add(k)

        cluster_id += 1

    return labels
