from datetime import date, timedelta

def second_friday_sales_report(start_date, periods, categories, sales):
    start = date.fromisoformat(start_date)
    dates = []
    year, month = start.year, start.month

    while len(dates) < periods:
        first_day = date(year, month, 1)
        days_until_friday = (4 - first_day.weekday()) % 7
        second_friday = first_day + timedelta(days=days_until_friday + 7)

        if second_friday >= start:
            dates.append(second_friday.isoformat())

        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1

    return [
        (dates[i // len(categories)], category, sales[i])
        for i, category in enumerate(categories * periods)
    ]
