from math import sqrt

def threshold_and_standardize(data):
    if not data:
        return []

    values = [[float(x) if x >= 0.5 else 0.0 for x in row] for row in data]
    n_rows = len(values)
    n_cols = len(values[0])

    means = [
        sum(values[r][c] for r in range(n_rows)) / n_rows
        for c in range(n_cols)
    ]
    stds = [
        sqrt(sum((values[r][c] - means[c]) ** 2 for r in range(n_rows)) / n_rows)
        for c in range(n_cols)
    ]

    return [
        [
            (values[r][c] - means[c]) / stds[c] if stds[c] != 0 else 0.0
            for c in range(n_cols)
        ]
        for r in range(n_rows)
    ]
