from html.parser import HTMLParser


class _TableParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.found = False
        self.table_depth = 0
        self.rows = []
        self.row = None
        self.cell_parts = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)

        if tag == "table":
            if self.table_depth:
                self.table_depth += 1
            elif not self.found and attrs.get("id") == self.table_id:
                self.found = True
                self.table_depth = 1
            return

        if self.table_depth != 1:
            return

        if tag == "tr":
            self._finish_row()
            self.row = []
        elif tag in ("th", "td") and self.row is not None:
            self._finish_cell()
            self.cell_parts = []

    def handle_endtag(self, tag):
        if tag == "table" and self.table_depth:
            self.table_depth -= 1
            return

        if self.table_depth != 1:
            return

        if tag in ("th", "td"):
            self._finish_cell()
        elif tag == "tr":
            self._finish_row()

    def handle_data(self, data):
        if self.cell_parts is not None:
            self.cell_parts.append(data)

    def _finish_cell(self):
        if self.cell_parts is not None:
            self.row.append("".join(self.cell_parts).strip())
            self.cell_parts = None

    def _finish_row(self):
        if self.row is not None:
            self._finish_cell()
            self.rows.append(self.row)
            self.row = None


def html_table_records(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")

    if not parser.rows:
        return []

    headers = parser.rows[0]
    return [
        dict(zip(headers, row))
        for row in parser.rows[1:]
    ]
