                    self.found = True
                    self.target_depth = self.table_depth
                return

            if self.table_depth != self.target_depth:
                return

            if tag == "tr":
                self._finish_row()
                self.row = []
            elif tag in ("th", "td") and self.row is not None:
                self._finish_cell()
                self.cell_parts = []

        def handle_endtag(self, tag):
            if tag in ("th", "td") and self.table_depth == self.target_depth:
                self._finish_cell()
