                self._finish_row()
            elif tag == "table":
                if self.table_depth == self.target_depth:
                    self._finish_row()
                    self.target_depth = None
                self.table_depth -= 1

        def handle_data(self, data):
            if self.cell_parts is not None and self.table_depth == self.target_depth:
                self.cell_parts.append(data)

