import csv
import io


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    columns = None
    rows = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=""))
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("Each CSV document must have a header") from None

        if len(set(header)) != len(header):
            raise ValueError("CSV headers must not contain duplicate columns")

        if columns is None:
            columns = header
        elif len(header) != len(columns) or set(header) != set(columns):
            raise ValueError("All CSV documents must have the same columns")

        positions = [header.index(column) for column in columns]

        for row in reader:
            if not row:  # Ignore blank lines
                continue
            if len(row) != len(header):
                raise ValueError("CSV row has a different number of fields than its header")
            rows.append([row[i] for i in positions])

    def parse_number(value):
        try:
            return int(value)
        except ValueError:
            try:
                return float(value)
            except ValueError:
                return None

    parsed_columns = [
        [parse_number(row[i]) for row in rows]
        for i in range(len(columns))
    ]

    numeric = [
        all(value is not None for value in values)
        for values in parsed_columns
    ]

    return [
        {
            column: parsed_columns[i][row_index]
            if numeric[i] else rows[row_index][i]
            for i, column in enumerate(columns)
        }
        for row_index in range(len(rows))
    ]
```

