def column_summary_stats(csv_text, column_name):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV has no header row")

    try:
        column_index = header.index(column_name)
    except ValueError:
        raise ValueError(f"Column {column_name!r} not found")

    values = []
    for row in reader:
        # Treat blank or missing cells as absent values.
        if column_index >= len(row) or not row[column_index].strip():
            continue
        try:
            values.append(float(row[column_index]))
        except ValueError:
            raise ValueError(
                f"Non-numeric value in column {column_name!r}: "
                f"{row[column_index]!r}"
            )

    if not values:
        raise ValueError(f"Column {column_name!r} has no numeric values")

    return {
        "mean": statistics.mean(values),
        "median": statistics.median(values),
        "std_dev": statistics.pstdev(values),
    }
