from math import fsum, sqrt


def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = {
        name: [mapping[value] if value in mapping else value for value in values]
        for name, values in data.items()
    }

    result = {name: {} for name in columns}
    names = list(columns)

    for a in names:
        for b in names:
            x, y = columns[a], columns[b]
            mean_x = fsum(x) / len(x) if x else 0
            mean_y = fsum(y) / len(y) if y else 0
            centered_x = [value - mean_x for value in x]
            centered_y = [value - mean_y for value in y]

            sum_x = fsum(value * value for value in centered_x)
            sum_y = fsum(value * value for value in centered_y)

            # Pearson correlation is undefined for empty or constant columns.
            if not x or sum_x == 0 or sum_y == 0:
                result[a][b] = float("nan")
            else:
                numerator = fsum(
                    u * v for u, v in zip(centered_x, centered_y)
                )
                result[a][b] = numerator / sqrt(sum_x * sum_y)

    return result
