import math


def mapped_correlation_matrix(data, mapping):
    """Return the pairwise Pearson correlation matrix after applying mapping."""
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    columns = {}
    for name, values in data.items():
        converted = []
        for value in values:
            try:
                value = mapping[value]
            except (KeyError, TypeError):
                pass
            converted.append(float(value))
        columns[name] = converted

    result = {name: {} for name in columns}

    for a, x in columns.items():
        for b, y in columns.items():
            mean_x = math.fsum(x) / len(x) if x else 0.0
            mean_y = math.fsum(y) / len(y) if y else 0.0
            dx = [value - mean_x for value in x]
            dy = [value - mean_y for value in y]

            sum_x = math.fsum(value * value for value in dx)
            sum_y = math.fsum(value * value for value in dy)

            if not x or sum_x == 0 or sum_y == 0:
                correlation = math.nan
            else:
                numerator = math.fsum(u * v for u, v in zip(dx, dy))
                correlation = numerator / math.sqrt(sum_x * sum_y)

            result[a][b] = correlation

    return result
