import math
import statistics


def abs_sin_cos_spectrum_stats(range_start, range_end, step):
    if range_start > range_end:
        raise ValueError("range_start must not be greater than range_end")
    if not step > 0:
        raise ValueError("step must be positive")

    samples = []
    i = 0
    while True:
        x = range_start + i * step
        if x >= range_end:
            break
        samples.append(abs(math.sin(x) - math.cos(x)))
        i += 1

    if not samples:
        raise ValueError("the range must contain at least one sample")

    n = len(samples)
    magnitudes = [
        abs(sum(
            samples[j] * cmath.exp(-2j * math.pi * k * j / n)
            for j in range(n)
        ))
        for k in range(n)
    ]

    return float(statistics.mean(magnitudes)), float(statistics.median(magnitudes))
