import math

def score_grade_correlation(scores, grades):
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    numeric_scores = []
    for score in scores:
        try:
            value = float(score)
        except (TypeError, ValueError) as exc:
            raise ValueError(f"invalid score: {score!r}") from exc
        if not math.isfinite(value):
            raise ValueError(f"invalid score: {score!r}")
        numeric_scores.append(value)

    if len(scores) < 2:
        return None

    grade_positions = {grade: i for i, grade in enumerate(sorted(set(grades)))}
    encoded_grades = [grade_positions[grade] for grade in grades]

    mean_score = sum(numeric_scores) / len(numeric_scores)
    mean_grade = sum(encoded_grades) / len(encoded_grades)

    score_diffs = [score - mean_score for score in numeric_scores]
    grade_diffs = [grade - mean_grade for grade in encoded_grades]

    score_variance = sum(diff * diff for diff in score_diffs)
    grade_variance = sum(diff * diff for diff in grade_diffs)
    if score_variance == 0 or grade_variance == 0:
        raise ValueError("correlation is undefined when either list has no variation")

    covariance = sum(s * g for s, g in zip(score_diffs, grade_diffs))
    return covariance / math.sqrt(score_variance * grade_variance)
