import math


def score_grade_correlation(scores, grades):
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    numeric_scores = []
    for score in scores:
        try:
            value = float(score)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(f"Invalid score: {score!r}") from exc

        if not math.isfinite(value):
            raise ValueError(f"Invalid score: {score!r}")
        numeric_scores.append(value)

    if len(scores) < 2:
        return None

    grade_codes = {
        grade: index
        for index, grade in enumerate(sorted(set(grades)))
    }
    encoded_grades = [grade_codes[grade] for grade in grades]

    mean_score = sum(numeric_scores) / len(numeric_scores)
    mean_grade = sum(encoded_grades) / len(encoded_grades)

    score_deviations = [score - mean_score for score in numeric_scores]
    grade_deviations = [grade - mean_grade for grade in encoded_grades]

    score_ss = sum(d * d for d in score_deviations)
    grade_ss = sum(d * d for d in grade_deviations)
    if score_ss == 0 or grade_ss == 0:
        raise ValueError("Correlation is undefined when either list is constant")

    covariance = sum(
        score_dev * grade_dev
        for score_dev, grade_dev in zip(score_deviations, grade_deviations)
    )
    return covariance / math.sqrt(score_ss * grade_ss)
```

