def score_grade_correlation(scores, grades):
    if len(scores) != len(grades):
        raise ValueError("scores and grades must have the same length")

    try:
        numeric_scores = [float(score) for score in scores]
    except (TypeError, ValueError) as exc:
        raise ValueError("every score must be a valid number") from exc

    if len(scores) < 2:
        return None

    grade_positions = {
        grade: position
        for position, grade in enumerate(sorted(set(grades)))
    }
    encoded_grades = [grade_positions[grade] for grade in grades]

    score_mean = sum(numeric_scores) / len(numeric_scores)
    grade_mean = sum(encoded_grades) / len(encoded_grades)

    score_deviations = [score - score_mean for score in numeric_scores]
    grade_deviations = [grade - grade_mean for grade in encoded_grades]

    numerator = sum(
        score_dev * grade_dev
        for score_dev, grade_dev in zip(score_deviations, grade_deviations)
    )
    denominator = math.sqrt(
        sum(dev * dev for dev in score_deviations)
        * sum(dev * dev for dev in grade_deviations)
    )

    # Pearson correlation is undefined when either input has zero variance.
    return numerator / denominator if denominator else float("nan")
