from itertools import combinations

def voronoi_neighbors(points):
    """Return sorted index pairs whose Voronoi cells share an edge."""
    n = len(points)
    if n < 3:
        raise ValueError("at least three points are required")

    def orient(a, b, c):
        return ((b[0] - a[0]) * (c[1] - a[1])
                - (b[1] - a[1]) * (c[0] - a[0]))

    def incircle(a, b, c, p):
        # Positive when p lies inside the circumcircle of a, b, c,
        # after accounting for the orientation of a, b, c.
        ax, ay = a[0] - p[0], a[1] - p[1]
        bx, by = b[0] - p[0], b[1] - p[1]
        cx, cy = c[0] - p[0], c[1] - p[1]

        det = ((ax * ax + ay * ay) * (bx * cy - by * cx)
               - (bx * bx + by * by) * (ax * cy - ay * cx)
               + (cx * cx + cy * cy) * (ax * by - ay * bx))
        return det if orient(a, b, c) > 0 else -det

    edges = set()

    # Each empty-circumcircle triangle is a Delaunay triangle; its
    # sides are Voronoi-neighbor pairs.
    for i, j, k in combinations(range(n), 3):
        a, b, c = points[i], points[j], points[k]
        if all(
            incircle(a, b, c, points[m]) <= 0
            for m in range(n)
            if m not in (i, j, k)
        ):
            edges.update((u, v) for u, v in ((i, j), (i, k), (j, k)))

    return sorted(edges)
```

This uses the empty-circumcircle characterization of Delaunay triangles. It takes \(O(n^4)\) time. Floating-point inputs very close to a degenerate configuration can be affected by rounding.

```python
def box_blur(image, kernel_size):
    if (
        isinstance(kernel_size, bool)
        or not isinstance(kernel_size, int)
        or kernel_size <= 0
        or kernel_size % 2 == 0
    ):
        raise ValueError("kernel_size must be a positive odd integer")

    height = len(image)
    if height == 0:
        return []

    width = len(image[0])
    if width == 0:
        return [[] for _ in range(height)]

    channels = len(image[0][0])
    radius = kernel_size // 2
    area = kernel_size * kernel_size

    def mirror(index, length):
        if length == 1:
            return 0
        period = 2 * (length - 1)
        index %= period
        return index if index < length else period - index

    blurred = []
    for row in range(height):
        output_row = []
        for col in range(width):
            sums = [0] * channels

            for dr in range(-radius, radius + 1):
                source_row = mirror(row + dr, height)
                for dc in range(-radius, radius + 1):
                    source_col = mirror(col + dc, width)
                    for channel in range(channels):
                        sums[channel] += image[source_row][source_col][channel]

            output_row.append([total / area for total in sums])
        blurred.append(output_row)

    return blurred
```

For example, `box_blur([[[0], [9]], [[9], [0]]], 3)` returns `[[[4.0], [5.0]], [[5.0], [4.0]]]`. This assumes the image is rectangular and its pixels have a consistent number of channels.

