def cluster_centroids(points, k):
    """Return k-means centroids, sorted lexicographically by (x, y)."""
    pts = [(float(x), float(y)) for x, y in points]

    if not 1 <= k <= len(pts):
        raise ValueError("k must be between 1 and the number of points")

    def squared_distance(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic farthest-first initialization.
    selected = [0]
    while len(selected) < k:
        remaining = (i for i in range(len(pts)) if i not in selected)
        next_i = max(
            remaining,
            key=lambda i: (
                min(squared_distance(pts[i], pts[j]) for j in selected),
                -i,  # Break ties by choosing the earliest point.
            ),
        )
        selected.append(next_i)

    centroids = [pts[i] for i in selected]

    for _ in range(300):
        groups = [[] for _ in range(k)]

        for point in pts:
            nearest = min(
                range(k),
                key=lambda i: squared_distance(point, centroids[i]),
            )
            groups[nearest].append(point)

        new_centroids = []
        for i, group in enumerate(groups):
            if group:
                new_centroids.append((
                    sum(point[0] for point in group) / len(group),
                    sum(point[1] for point in group) / len(group),
                ))
            else:
                # Keep an empty cluster's previous centroid.
                new_centroids.append(centroids[i])

        if new_centroids == centroids:
            break
        centroids = new_centroids

    return sorted(centroids)
```

The initialization is deterministic, and the returned tuples are sorted lexicographically by `x`, then `y`.

