def cluster_centroids(points, k):
    """Return k-means centroids as sorted (x, y) float tuples."""
    if not points:
        raise ValueError("points must not be empty")
    if not 1 <= k <= len(points):
        raise ValueError("k must be between 1 and the number of points")

    points = [(float(x), float(y)) for x, y in points]

    def dist2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic farthest-first initialization.
    centers = [points[0]]
    chosen = {0}
    while len(centers) < k:
        i = max(
            (i for i in range(len(points)) if i not in chosen),
            key=lambda i: min(dist2(points[i], c) for c in centers),
        )
        chosen.add(i)
        centers.append(points[i])

    previous_labels = None

    for _ in range(300):
        labels = [
            min(range(k), key=lambda j: dist2(point, centers[j]))
            for point in points
        ]

        new_centers = []
        for j in range(k):
            members = [p for p, label in zip(points, labels) if label == j]
            if members:
                new_centers.append((
                    sum(p[0] for p in members) / len(members),
                    sum(p[1] for p in members) / len(members),
                ))
            else:
                # Keep the previous center if a cluster has no assigned points.
                new_centers.append(centers[j])

        centers = new_centers
        if labels == previous_labels:
            break
        previous_labels = labels

    return sorted((float(x), float(y)) for x, y in centers)
