            if self.current is not None:
                self.current.append(data)

        def handle_endtag(self, tag):
            if tag.lower() == "script" and self.current is not None:
                scripts.append("".join(self.current))
                self.current = None

    parser = ScriptParser()
    parser.feed(html)
    parser.close()

    result = []
    for body in scripts:
        try:
            value = ast.literal_eval(body.strip())
        except (SyntaxError, ValueError):
            continue
        if isinstance(value, dict):
            result.append(value)

    return result
```

`ast.literal_eval` accepts Python literals without executing arbitrary code, and non-dictionary or invalid script bodies are skipped.

