        if not match:
            raise ValueError("freq must be 'month-end', 'quarter-end', or a code like '2-FRI'")
        week_number, weekday = int(match.group(1)), weekdays[match.group(2)]
        rule = ("weekday", week_number, weekday)
    else:
        raise ValueError("Invalid freq")

    result = []
    year, month = start.year, start.month

    for sale in sales:
        while True:
            if rule == "month-end":
                day = monthrange(year, month)[1]
            elif rule == "quarter-end":
                if month not in (3, 6, 9, 12):
                    day = None
                else:
                    day = monthrange(year, month)[1]
            else:
                _, week_number, weekday = rule
                first_weekday = date(year, month, 1).weekday()
                day = 1 + (weekday - first_weekday) % 7 + 7 * (week_number - 1)

            if day is not None:
                candidate = date(year, month, day)
