        "FRI": 4, "SAT": 5, "SUN": 6,
    }

    if freq == "month-end":
        kind, interval = "month-end", 1
    elif freq == "quarter-end":
        kind, interval = "quarter-end", 3
    else:
        match = re.fullmatch(r"([1-4])-(MON|TUE|WED|THU|FRI|SAT|SUN)", freq) if isinstance(freq, str) else None
        if not match:
            raise ValueError("freq must be 'month-end', 'quarter-end', or a code such as '2-FRI'")
        week = int(match.group(1))
        weekday = weekday_codes[match.group(2)]
        kind, interval = "weekday", 1

    def month_date(year, month):
        if kind == "month-end":
            day = calendar.monthrange(year, month)[1]
            return date(year, month, day)

        if kind == "quarter-end":
            if month not in (3, 6, 9, 12):
                return None
            day = calendar.monthrange(year, month)[1]
            return date(year, month, day)

        first = date(year, month, 1)
        day = 1 + (weekday - first.weekday()) % 7 + 7 * (week - 1)
        return date(year, month, day)

    year, month = start.year, start.month
    while True:
        first_date = month_date(year, month)
        if first_date is not None and first_date >= start:
            break
        month += 1
        if month == 13:
            year, month = year + 1, 1

    result = []
    for amount in sales:
        result.append((first_date.isoformat(), amount))

        month_index = year * 12 + (month - 1) + interval
        year, month = divmod(month_index, 12)
        month += 1
        first_date = month_date(year, month)

    return result
