            raise ValueError("freq must be 'month-end', 'quarter-end', or a code like '2-FRI'")
        kind = "weekday"
        week = int(match.group(1))
        weekday = weekdays[match.group(2)]

    def add_months(year, month, count):
        index = year * 12 + month - 1 + count
        year, month0 = divmod(index, 12)
        return year, month0 + 1

    def date_in_month(year, month):
        if kind == "month-end":
            day = calendar.monthrange(year, month)[1]
        elif kind == "quarter-end":
            if month not in (3, 6, 9, 12):
                return None
            day = calendar.monthrange(year, month)[1]
        else:
            first_weekday = date(year, month, 1).weekday()
            day = 1 + (weekday - first_weekday) % 7 + 7 * (week - 1)
        return date(year, month, day)

    result = []
    if not sales:
        return result

    year, month = start.year, start.month
    while True:
        current = date_in_month(year, month)
        if current is not None and current >= start:
            break
        year, month = add_months(year, month, 1)

    step = 3 if kind == "quarter-end" else 1
    for sale in sales:
        result.append((current.isoformat(), sale))
        year, month = add_months(current.year, current.month, step)
        current = date_in_month(year, month)

