import csv
from collections import Counter
from io import StringIO


def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(StringIO(csv_text))
    required = {"Customer", "Category", "Sales"}
    if reader.fieldnames is None or not required.issubset(reader.fieldnames):
        raise ValueError("CSV must include Customer, Category, and Sales columns")

    seen_customers = set()
    total_sales = 0
    categories = Counter()

    for row in reader:
        customer = row["Customer"]
        if customer in seen_customers:
            continue

        seen_customers.add(customer)
        sales = row["Sales"]

        try:
            amount = int(sales)
        except ValueError:
            amount = float(sales)

        total_sales += amount
        categories[row["Category"]] += 1

    popular_category = (
        min(categories, key=lambda category: (-categories[category], category))
        if categories
        else None
    )

    return {
        "Total Sales": total_sales,
        "Most Popular Category": popular_category,
    }
