def country_score_summary(records):
    if not records:
        raise ValueError("records must not be empty")

    required = {"Name", "Country", "Score"}
    first_by_name = {}

    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError("Each record must contain Name, Country, and Score")
        first_by_name.setdefault(record["Name"], record)

    scores_by_country = {}
    for record in first_by_name.values():
        scores_by_country.setdefault(record["Country"], []).append(record["Score"])

    def five_number_summary(scores):
        values = sorted(scores)
        last = len(values) - 1

        def percentile(p):
            position = p * last
            lower = int(position)
            upper = min(lower + 1, last)
            fraction = position - lower
            return float(values[lower] + fraction * (values[upper] - values[lower]))

        return [
            float(values[0]),
            percentile(0.25),
            percentile(0.5),
            percentile(0.75),
            float(values[-1]),
        ]

    return {
        country: five_number_summary(scores)
        for country, scores in scores_by_country.items()
    }
