def country_score_summary(records):
    required = ("Name", "Country", "Score")

    if not records:
        raise ValueError("records must not be empty")

    seen_names = set()
    scores_by_country = {}

    for record in records:
        if any(key not in record for key in required):
            raise ValueError("each record must contain Name, Country, and Score")

        name = record["Name"]
        if name in seen_names:
            continue

        seen_names.add(name)
        scores_by_country.setdefault(record["Country"], []).append(record["Score"])

    def interpolate(sorted_values, fraction):
        position = (len(sorted_values) - 1) * fraction
        lower = int(position)
        upper = min(lower + 1, len(sorted_values) - 1)
        weight = position - lower
        return sorted_values[lower] * (1 - weight) + sorted_values[upper] * weight

    result = {}
    for country, scores in scores_by_country.items():
        scores.sort()
        result[country] = [
            float(scores[0]),
            interpolate(scores, 0.25),
            interpolate(scores, 0.50),
            interpolate(scores, 0.75),
            float(scores[-1]),
        ]

    return result
