from numbers import Number


def column_covariance(columns):
    if not columns:
        raise ValueError("table must contain at least one column")

    for name, values in columns.items():
        if any(not isinstance(value, Number) for value in values):
            raise TypeError(f"column {name!r} contains a non-numeric value")

    lengths = {len(values) for values in columns.values()}
    if len(lengths) != 1:
        raise ValueError("columns must have equal lengths")

    n = lengths.pop()
    if n == 0:
        raise ValueError("table must contain at least one row")
    if n < 2:
        raise ValueError("at least two rows are required")

    means = {
        name: sum(values) / n
        for name, values in columns.items()
    }

    return {
        a: {
            b: sum(
                (x - means[a]) * (y - means[b])
                for x, y in zip(columns[a], columns[b])
            ) / (n - 1)
            for b in columns
        }
        for a in columns
    }
