import csv
import io
from datetime import datetime


def upcoming_rows(csv_text, column_name, today, date_format="%Y-%m-%d"):
    if not csv_text:
        return []

    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None:
        return []
    if column_name not in reader.fieldnames:
        raise ValueError(f"Column {column_name!r} not found")

    cutoff = datetime.strptime(today, "%Y-%m-%d").date()
    matches = []

    for row in reader:
        row_date = datetime.strptime(row[column_name], date_format).date()
        if row_date >= cutoff:
            matches.append((row_date, {
                name: row[name] for name in reader.fieldnames
            }))

    # Python's sort is stable, so rows with tied dates keep their original order.
    matches.sort(key=lambda item: item[0])
    return [row for _, row in matches]
