def cluster_point_indices(points, n_clusters):
    """Group point indices with deterministic k-means."""
    points = [list(point) for point in points]

    if not points:
        raise ValueError("points must not be empty")
    if not 1 <= n_clusters <= len(points):
        raise ValueError("n_clusters must be between 1 and len(points)")

    dimension = len(points[0])
    if any(len(point) != dimension for point in points):
        raise ValueError("all points must have the same dimension")

    def squared_distance(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Deterministic farthest-first initialization.
    chosen = [0]
    while len(chosen) < n_clusters:
        next_index = max(
            (i for i in range(len(points)) if i not in chosen),
            key=lambda i: min(
                squared_distance(points[i], points[j]) for j in chosen
            ),
        )
        chosen.append(next_index)

    centers = [points[i][:] for i in chosen]
    labels = None

    for _ in range(100):
        new_labels = [
            min(range(n_clusters),
                key=lambda c: squared_distance(point, centers[c]))
            for point in points
        ]

        # Reseed empty clusters by moving a faraway point from a cluster
        # that has more than one point.
        counts = [new_labels.count(c) for c in range(n_clusters)]
        for empty in (c for c in range(n_clusters) if counts[c] == 0):
            candidates = [
                i for i, label in enumerate(new_labels) if counts[label] > 1
            ]
            point_index = max(
                candidates,
                key=lambda i: squared_distance(points[i], centers[new_labels[i]]),
            )
            source = new_labels[point_index]
            new_labels[point_index] = empty
            counts[source] -= 1
            counts[empty] += 1

        new_centers = []
        for c in range(n_clusters):
            members = [points[i] for i, label in enumerate(new_labels) if label == c]
            new_centers.append([
                sum(point[d] for point in members) / len(members)
                for d in range(dimension)
            ])

        if new_labels == labels:
            break
        labels = new_labels
        centers = new_centers

    clusters = [
        [i for i, label in enumerate(labels) if label == c]
        for c in range(n_clusters)
    ]
    return sorted(clusters, key=lambda cluster: cluster[0])
```

For the example, this returns `[[0, 1], [2, 3]]`. The initialization and tie-breaking are deterministic.

