def cluster_point_indices(points, n_clusters):
    """Cluster points with deterministic k-means and return their indices."""
    if not points:
        raise ValueError("points must not be empty")
    if not isinstance(n_clusters, int) or not 1 <= n_clusters <= len(points):
        raise ValueError("n_clusters must be between 1 and len(points)")

    points = [list(point) for point in points]
    dimension = len(points[0])
    if dimension == 0 or any(len(point) != dimension for point in points):
        raise ValueError("all points must have the same nonzero dimension")

    def squared_distance(a, b):
        return sum((x - y) ** 2 for x, y in zip(a, b))

    # Deterministic farthest-first initialization.
    chosen = [0]
    centers = [points[0][:]]
    while len(centers) < n_clusters:
        next_index = max(
            (i for i in range(len(points)) if i not in chosen),
            key=lambda i: (
                min(squared_distance(points[i], center) for center in centers),
                -i,
            ),
        )
        chosen.append(next_index)
        centers.append(points[next_index][:])

    previous_labels = None

    for _ in range(300):
        labels = [
            min(
                range(n_clusters),
                key=lambda c: squared_distance(point, centers[c]),
            )
            for point in points
        ]

        # Reassign points to any empty clusters so every cluster is nonempty.
        counts = [labels.count(c) for c in range(n_clusters)]
        for empty in range(n_clusters):
            if counts[empty] == 0:
                candidates = [
                    i for i, label in enumerate(labels) if counts[label] > 1
                ]
                moved = max(
                    candidates,
                    key=lambda i: (
                        squared_distance(points[i], centers[labels[i]]),
                        -i,
                    ),
                )
                counts[labels[moved]] -= 1
                labels[moved] = empty
                counts[empty] += 1

        if labels == previous_labels:
            break
        previous_labels = labels[:]

        centers = []
        for c in range(n_clusters):
            members = [points[i] for i, label in enumerate(labels) if label == c]
            centers.append([
                sum(point[d] for point in members) / len(members)
                for d in range(dimension)
            ])

    clusters = [
        [i for i, label in enumerate(labels) if label == c]
        for c in range(n_clusters)
    ]
    return sorted(clusters, key=lambda cluster: cluster[0])
```

The initialization and tie-breaking are deterministic. The returned indices are ascending within each cluster, and the clusters are ordered by their smallest index.

