from collections import Counter, defaultdict

def summarize_student_records(data):
    required = ("Name", "Age", "Score")
    if any(key not in data for key in required):
        raise ValueError("data must contain 'Name', 'Age', and 'Score'")

    names, ages, scores = (data[key] for key in required)
    if not (len(names) == len(ages) == len(scores)):
        raise ValueError("Name, Age, and Score lists must have equal lengths")

    records = [[name, age, score] for name, age, score in zip(names, ages, scores)]
    records.sort(key=lambda record: (record[0], record[1]))  # Stable sort.

    scores_by_name = defaultdict(list)
    for name, score in zip(names, scores):
        scores_by_name[name].append(score)

    averages = {
        name: sum(student_scores) / len(student_scores)
        for name, student_scores in scores_by_name.items()
    }

    most_common_age = Counter(ages).most_common(1)
    return records, averages, most_common_age[0][0] if most_common_age else None
```

If ages are tied for most common, this returns the age that appears first in the input.

