import csv
from decimal import Decimal, InvalidOperation


def sort_csv_rows(csv_text, sort_key):
    reader = csv.reader(csv_text.splitlines())
    headers = next(reader, [])

    if sort_key not in headers:
        raise ValueError(f"Column {sort_key!r} does not exist")

    rows = [row for row in reader if row]

    def parse_number(value):
        try:
            number = Decimal(value.strip())
        except InvalidOperation:
            return None

        if not number.is_finite():
            return None
        return int(number) if number == number.to_integral_value() else float(number)

    # Convert a column only when it has values and every value is numeric.
    numeric_columns = {}
    for index, header in enumerate(headers):
        values = [row[index] for row in rows]
        parsed = [parse_number(value) for value in values]
        numeric_columns[header] = bool(values) and all(
            value is not None for value in parsed
        )

        if numeric_columns[header]:
            for row, value in zip(rows, parsed):
                row[index] = value

    result = [dict(zip(headers, row)) for row in rows]
    return sorted(result, key=lambda row: row[sort_key])
```

Python’s sort is stable, so rows with equal sort-key values retain their original order.

