import csv
import io


def sort_csv_rows(csv_text, sort_key):
    reader = csv.DictReader(io.StringIO(csv_text))
    if reader.fieldnames is None or sort_key not in reader.fieldnames:
        raise ValueError(f"Column {sort_key!r} does not exist")

    rows = list(reader)

    def parse_number(value):
        try:
            return int(value)
        except (TypeError, ValueError):
            try:
                return float(value)
            except (TypeError, ValueError):
                return None

    # Convert a column only if every value in it is numeric.
    for column in reader.fieldnames:
        parsed = [parse_number(row[column]) for row in rows]
        if rows and all(value is not None for value in parsed):
            for row, value in zip(rows, parsed):
