def kmeans_clusters(xs, ys, n_clusters):
    """Cluster 2D points and return sorted index lists, ordered by smallest index."""
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if (
        not isinstance(n_clusters, int)
        or isinstance(n_clusters, bool)
        or not 1 <= n_clusters <= n
    ):
        raise ValueError("n_clusters must be between 1 and the number of points")

    points = list(zip(xs, ys))

    # Deterministic farthest-point initialization.
    chosen = [0]
    while len(chosen) < n_clusters:
        unchosen = [i for i in range(n) if i not in chosen]

        def distance_to_nearest_center(i):
            return min(
                (points[i][0] - points[j][0]) ** 2
                + (points[i][1] - points[j][1]) ** 2
                for j in chosen
            )

        chosen.append(
            max(unchosen, key=lambda i: (distance_to_nearest_center(i), -i))
        )

    centers = [points[i] for i in chosen]
    assignments = None

    for _ in range(300):
        distances = [
            [
                (x - cx) ** 2 + (y - cy) ** 2
                for cx, cy in centers
            ]
            for x, y in points
        ]
        labels = [min(range(n_clusters), key=lambda c: distances[i][c])
                  for i in range(n)]

        # Keep every cluster nonempty, including when points have identical coordinates.
        counts = [labels.count(c) for c in range(n_clusters)]
        for empty in range(n_clusters):
            if counts[empty] == 0:
                candidates = [i for i in range(n) if counts[labels[i]] > 1]
                moved = max(candidates, key=lambda i: (min(distances[i]), -i))
                counts[labels[moved]] -= 1
                labels[moved] = empty
                counts[empty] += 1

        new_centers = []
        for c in range(n_clusters):
            members = [i for i, label in enumerate(labels) if label == c]
            new_centers.append((
                sum(xs[i] for i in members) / len(members),
                sum(ys[i] for i in members) / len(members),
            ))

        if labels == assignments:
            break

        assignments = labels
        centers = new_centers

    clusters = [
        [i for i, label in enumerate(assignments) if label == c]
        for c in range(n_clusters)
    ]
    return sorted(clusters, key=lambda cluster: cluster[0])
