def kmeans_clusters(xs, ys, n_clusters):
    """Cluster 2D points and return sorted point indices for each cluster."""
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if not isinstance(n_clusters, int) or not 1 <= n_clusters <= n:
        raise ValueError("n_clusters must be between 1 and the number of points")

    points = list(zip(xs, ys))

    def squared_distance(p, q):
        return (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2

    # Deterministic farthest-first initialization.
    centers = [points[0]]
    while len(centers) < n_clusters:
        next_index = max(
            range(n),
            key=lambda i: (
                min(squared_distance(points[i], c) for c in centers),
                -i,
            ),
        )
        centers.append(points[next_index])

    assignments = None

    for _ in range(300):
        # Assign each point to its nearest center; ties go to the first center.
        new_assignments = [
            min(
                range(n_clusters),
                key=lambda c: squared_distance(points[i], centers[c]),
            )
            for i in range(n)
        ]

        # Keep every cluster nonempty by moving a farthest point from a
        # cluster that has more than one point.
        sizes = [new_assignments.count(c) for c in range(n_clusters)]
        for empty in range(n_clusters):
            if sizes[empty] == 0:
                candidates = [
                    i for i, c in enumerate(new_assignments) if sizes[c] > 1
                ]
                moved = max(
                    candidates,
                    key=lambda i: (
                        squared_distance(points[i], centers[new_assignments[i]]),
                        -i,
                    ),
                )
                donor = new_assignments[moved]
                new_assignments[moved] = empty
                sizes[donor] -= 1
                sizes[empty] += 1

        if new_assignments == assignments:
            break
        assignments = new_assignments

        # Update centers to the mean of their assigned points.
        centers = [
            (
                sum(xs[i] for i, c in enumerate(assignments) if c == cluster)
                / sizes[cluster],
                sum(ys[i] for i, c in enumerate(assignments) if c == cluster)
                / sizes[cluster],
            )
            for cluster in range(n_clusters)
        ]

    clusters = [
        [i for i, c in enumerate(assignments) if c == cluster]
        for cluster in range(n_clusters)
    ]
    return sorted(clusters, key=lambda cluster: cluster[0])
