def kmeans_clusters(xs, ys, n_clusters):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")

    n = len(xs)
    if not isinstance(n_clusters, int) or isinstance(n_clusters, bool):
        raise ValueError("n_clusters must be an integer")
    if not 1 <= n_clusters <= n:
        raise ValueError("n_clusters must be between 1 and the number of points")

    points = list(zip(xs, ys))

    def dist2(a, b):
        return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

    # Deterministic farthest-first initialization.
    centers = [points[0]]
    selected = {0}
    while len(centers) < n_clusters:
        i = max(
            (i for i in range(n) if i not in selected),
            key=lambda i: (min(dist2(points[i], c) for c in centers), -i),
        )
        centers.append(points[i])
        selected.add(i)

    previous_labels = None

    for _ in range(300):
        labels = [
            min(range(n_clusters), key=lambda c: dist2(point, centers[c]))
            for point in points
        ]

        # Keep every cluster nonempty by moving points from clusters with extras.
        counts = [labels.count(c) for c in range(n_clusters)]
        for empty in range(n_clusters):
            if counts[empty] != 0:
                continue

            movable = [i for i, c in enumerate(labels) if counts[c] > 1]
            i = max(
                movable,
                key=lambda i: (dist2(points[i], centers[labels[i]]), -i),
            )
            counts[labels[i]] -= 1
            labels[i] = empty
            counts[empty] = 1

        centers = [
            (
                sum(points[i][0] for i in range(n) if labels[i] == c)
                / counts[c],
                sum(points[i][1] for i in range(n) if labels[i] == c)
                / counts[c],
            )
            for c in range(n_clusters)
        ]

        if labels == previous_labels:
            break
        previous_labels = labels

    clusters = [
        [i for i, label in enumerate(labels) if label == c]
        for c in range(n_clusters)
    ]
    return sorted(clusters, key=lambda cluster: cluster[0])
