import json
import math


def numeric_correlation_from_json(json_text):
    """Return pairwise Pearson correlations for columns containing only numbers."""
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data must be a non-empty JSON object")

    if any(not isinstance(values, list) for values in data.values()):
        raise ValueError("Each column must be a list")

    lengths = {len(values) for values in data.values()}
    if len(lengths) != 1:
        raise ValueError("Columns must have equal lengths")
    if lengths == {0}:
        raise ValueError("Data must contain at least one row")

    # A column is numeric only if every value is a finite number.
    numeric = {}
    for name, values in data.items():
        if all(
            isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(value)
            for value in values
        ):
            numeric[name] = [float(value) for value in values]

    result = {name: {} for name in numeric}

    for name_a, values_a in numeric.items():
        mean_a = sum(values_a) / len(values_a)
        centered_a = [value - mean_a for value in values_a]
        sum_sq_a = sum(value * value for value in centered_a)

        for name_b, values_b in numeric.items():
            if name_a == name_b:
                result[name_a][name_b] = 1.0
                continue

            mean_b = sum(values_b) / len(values_b)
            centered_b = [value - mean_b for value in values_b]
            sum_sq_b = sum(value * value for value in centered_b)

            denominator = math.sqrt(sum_sq_a * sum_sq_b)
            result[name_a][name_b] = (
                sum(a * b for a, b in zip(centered_a, centered_b)) / denominator
                if denominator
                else math.nan  # Pearson correlation is undefined for a constant column.
            )

    return result
```

Columns containing non-numeric values are ignored. Correlations involving a constant column are `NaN`, since Pearson correlation is undefined in that case.

