import json
import math


def numeric_correlation_from_json(json_text):
    """Return the Pearson correlation matrix for columns containing only numbers."""
    def reject_nonstandard_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        data = json.loads(json_text, parse_constant=reject_nonstandard_constant)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Input must be valid JSON") from exc

    if not isinstance(data, dict):
        raise ValueError("JSON data must be an object")

    if any(not isinstance(values, list) for values in data.values()):
        raise ValueError("Each column must be a list")

    lengths = {len(values) for values in data.values()}
    if len(lengths) > 1:
        raise ValueError("All columns must have equal lengths")
    if not data or (lengths and next(iter(lengths)) == 0):
        raise ValueError("Data must not be empty")

    # Treat booleans as non-numeric, even though bool is a subclass of int in Python.
    columns = {
        name: values
        for name, values in data.items()
        if all(
            isinstance(value, (int, float)) and not isinstance(value, bool)
            for value in values
        )
    }

    result = {name: {} for name in columns}
    centered = {}
    sums_of_squares = {}

    for name, values in columns.items():
        mean = math.fsum(values) / len(values)
        deviations = [value - mean for value in values]
        centered[name] = deviations
        sums_of_squares[name] = math.fsum(d * d for d in deviations)

    for name_a in columns:
        for name_b in columns:
            denominator = math.sqrt(sums_of_squares[name_a]) * math.sqrt(
                sums_of_squares[name_b]
            )
            if denominator == 0:
                # Pearson correlation is undefined when either column is constant.
                correlation = float("nan")
            else:
                numerator = math.fsum(
                    a * b for a, b in zip(centered[name_a], centered[name_b])
                )
                correlation = numerator / denominator
            result[name_a][name_b] = correlation

    return result
