import math
import re

def tfidf_matrix(documents):
    tokenized = [
        re.findall(r"[A-Za-z0-9]+", document.lower())
        for document in documents
    ]

    words = sorted({word for tokens in tokenized for word in tokens})
    n = len(documents)
    df = {
        word: sum(word in set(tokens) for tokens in tokenized)
        for word in words
    }
    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in words
    }

    rows = []
    for tokens in tokenized:
        counts = {}
        for word in tokens:
            counts[word] = counts.get(word, 0) + 1

        row = [counts.get(word, 0) * idf[word] for word in words]
        norm = math.sqrt(sum(score * score for score in row))
        rows.append([score / norm for score in row] if norm else row)

    return words, rows
