import numpy as np

def linear_regression_r2(data, target):
    if target not in data:
        raise KeyError(f"Target column {target!r} is not in data")

    y = np.asarray(data[target], dtype=float)
    features = [column for column in data if column != target]

    # Include an intercept; with no predictors, this fits the target mean.
    if features:
        X = np.column_stack(
            [np.ones(len(y))] +
            [np.asarray(data[column], dtype=float) for column in features]
        )
    else:
        X = np.ones((len(y), 1))

    coefficients, *_ = np.linalg.lstsq(X, y, rcond=None)
    predictions = X @ coefficients

    ss_res = np.sum((y - predictions) ** 2)
    ss_tot = np.sum((y - np.mean(y)) ** 2)

    # R-squared is undefined for a constant target; return 1 for a perfect
    # fit and 0 otherwise, matching common library conventions.
    if ss_tot == 0:
        return float(1.0 if ss_res == 0 else 0.0)

    return float(1.0 - ss_res / ss_tot)
