def complete_row_histogram(data, bins):
    if bins <= 0:
        raise ValueError("bins must be a positive integer")

    columns = list(data)
    row_count = len(data[columns[0]]) if columns else 0

    valid_rows = [
        i for i in range(row_count)
        if all(data[column][i] is not None for column in columns)
    ]

    cleaned = {
        column: [float(data[column][i]) for i in valid_rows]
        for column in columns
    }

    values = [value for column in columns for value in cleaned[column]]
    if not values:
        return cleaned, None

    minimum = min(values)
    maximum = max(values)
    if minimum == maximum:
        return cleaned, None

    width = (maximum - minimum) / bins
    counts = [0] * bins

    for value in values:
        index = int((value - minimum) / width)
        # Include the maximum value in the final bin.
        index = min(index, bins - 1)
        counts[index] += 1

    return cleaned, counts
