def complete_row_histogram(data, bins):
    if bins <= 0:
        raise ValueError("bins must be positive")

    if not data:
        return {}, None

    columns = list(data)
    lengths = {len(data[col]) for col in columns}
    if len(lengths) != 1:
        raise ValueError("all columns must have equal length")

    row_count = lengths.pop()
    keep = [
        i for i in range(row_count)
        if all(data[col][i] is not None for col in columns)
    ]

    cleaned = {
        col: [float(data[col][i]) for i in keep]
        for col in columns
    }

    values = [value for col in columns for value in cleaned[col]]
    if not values:
        return cleaned, None

    low, high = min(values), max(values)
    if low == high:
        return cleaned, None

    width = (high - low) / bins
    counts = [0] * bins

    for value in values:
        index = int((value - low) / width)
        # Include the maximum value in the final bin.
        if index == bins:
            index = bins - 1
        counts[index] += 1

    return cleaned, counts
```

With standard equal-width bins spanning the pooled minimum and maximum, the example’s counts are `[4, 4]`, not `[5, 3]`: the bin boundary is 4.5. The stated `[5, 3]` would require a different bin boundary, such as 5.

