from bisect import bisect_right
from operator import index


def complete_row_histogram(data, bins):
    """Drop rows containing None and histogram the remaining values."""
    try:
        bins = index(bins)
    except TypeError:
        raise TypeError("bins must be an integer") from None
    if bins <= 0:
        raise ValueError("bins must be positive")

    lengths = {len(values) for values in data.values()}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    row_count = next(iter(lengths), 0)
    kept_rows = [
        row for row in range(row_count)
        if all(values[row] is not None for values in data.values())
    ]

    cleaned = {
        name: [float(values[row]) for row in kept_rows]
        for name, values in data.items()
    }
    pooled = [value for column in cleaned.values() for value in column]

    if not pooled or min(pooled) == max(pooled):
        return cleaned, None

    low, high = min(pooled), max(pooled)
    edges = [low + (high - low) * i / bins for i in range(bins + 1)]
    counts = [0] * bins

    for value in pooled:
        # Include the maximum in the final bin.
        bin_index = min(bisect_right(edges, value) - 1, bins - 1)
        counts[bin_index] += 1

    return cleaned, counts
