from sklearn.cluster import KMeans


def cluster_matched_pairs(first, second):
    matched_ids = [key for key in first if key in second]
    if not matched_ids:
        raise ValueError("first and second have no shared ids")

    points = [[first[key], second[key]] for key in matched_ids]
    if len(points) < 2:
        raise ValueError("At least two matched ids are required for k-means with k=2")

    labels = KMeans(n_clusters=2, random_state=0, n_init=10).fit_predict(points)

    # Relabel so the cluster containing the first point is always 0.
    return (labels != labels[0]).astype(int).tolist()
