            x, y = columns[i], columns[j]
            sum_x2 = sum((v - means[i]) ** 2 for v in x)
            sum_y2 = sum((v - means[j]) ** 2 for v in y)

            if not x or sum_x2 == 0 or sum_y2 == 0:
                corr = float("nan")  # Pearson correlation is undefined here.
            else:
                cross = sum(
                    (x[k] - means[i]) * (y[k] - means[j])
                    for k in range(len(x))
                )
                corr = cross / math.sqrt(sum_x2 * sum_y2)

            result[a][b] = corr

    return result
