        for j, name_b in enumerate(header):
            centered_a = [x - means[i] for x in columns[i]]
            centered_b = [x - means[j] for x in columns[j]]

            numerator = math.fsum(a * b for a, b in zip(centered_a, centered_b))
            sum_sq_a = math.fsum(a * a for a in centered_a)
            sum_sq_b = math.fsum(b * b for b in centered_b)

            # Correlation is undefined when either column is constant.
            denominator = math.sqrt(sum_sq_a) * math.sqrt(sum_sq_b)
            result[name_a][name_b] = (
                numerator / denominator if denominator else float("nan")
            )

    return result
