import csv
import math


def correlation_matrix_from_csv(csv_text):
    rows = list(csv.reader(csv_text.splitlines()))
    if not rows:
        raise ValueError("CSV must contain a header")

    headers = rows[0]
    if not headers:
        raise ValueError("CSV must contain at least one column")

    data = []
    for row in rows[1:]:
        if not row:  # Skip blank lines
            continue
        if len(row) != len(headers):
            raise ValueError("Each row must have the same number of fields as the header")
        data.append([float(value) for value in row])

    if len(data) < 2:
        raise ValueError("At least two data rows are required")

    columns = list(zip(*data))
    centered = []
    sums_of_squares = []

    for column in columns:
        mean = math.fsum(column) / len(column)
        values = [value - mean for value in column]
        centered.append(values)
        sums_of_squares.append(math.fsum(value * value for value in values))

    result = {name: {} for name in headers}

    for i, name_a in enumerate(headers):
        for j, name_b in enumerate(headers):
            if i == j:
                result[name_a][name_b] = 1.0
                continue

            denominator = math.sqrt(sums_of_squares[i] * sums_of_squares[j])
            if denominator == 0:
                raise ValueError("Correlation is undefined for a constant column")

            covariance_sum = math.fsum(
                a * b for a, b in zip(centered[i], centered[j])
            )
            result[name_a][name_b] = covariance_sum / denominator

    return result
