from collections import Counter

def document_term_matrix(texts, stop_words):
    stop_words = {word.lower() for word in stop_words}
    document_counts = []
    all_terms = set()

    for text in texts:
        words = []
        current = []

        for char in text.lower():
            if char.isalnum():
                current.append(char)
            elif current:
                word = "".join(current)
                if word not in stop_words:
                    words.append(word)
                current = []

        if current:
            word = "".join(current)
            if word not in stop_words:
                words.append(word)

        counts = Counter(words)
        document_counts.append(counts)
        all_terms.update(counts)

    terms = sorted(all_terms)
    counts = [
        [document.get(term, 0) for term in terms]
        for document in document_counts
    ]
    return terms, counts
