import numpy as np

def filtered_regression_coefficients(rows, height, weight, columns):
    target = columns[0]
    predictors = columns[1:]

    matching = [
        row for row in rows
        if row[columns[1]] > height and row[columns[2]] < weight
    ]

    if not matching:
        return None

    y = np.array([row[target] for row in matching], dtype=float)
    x = np.array(
        [[1.0] + [row[name] for name in predictors] for row in matching],
        dtype=float,
    )

    coefficients, *_ = np.linalg.lstsq(x, y, rcond=None)

    return {
        name: float(coefficient)
        for name, coefficient in zip(["const"] + predictors, coefficients)
    }
