from datetime import date, timedelta

def second_friday_price_schedule(start_date, prices):
    start = date.fromisoformat(start_date)
    year, month = start.year, start.month
    schedule = []

    for price in prices:
        while True:
            first_day = date(year, month, 1)
            days_to_first_friday = (4 - first_day.weekday()) % 7
            second_friday = first_day + timedelta(days=days_to_first_friday + 7)

            if second_friday >= start:
                schedule.append((second_friday.isoformat(), price))
                break

            # Advance to the next month
            if month == 12:
                year, month = year + 1, 1
            else:
                month += 1

        # Advance after assigning this month's date
        if month == 12:
            year, month = year + 1, 1
        else:
            month += 1

    return schedule
