import math

def last_column_skewness(rows):
    if not rows or not rows[0]:
        raise ValueError("table must have at least one row and one column")

    values = [row[-1] for row in rows if row[-1] is not None]
    if not values:
        return float("nan")

    n = len(values)
    mean = math.fsum(values) / n
    m2 = math.fsum((x - mean) ** 2 for x in values) / n

    if m2 == 0:
        return float("nan")

    m3 = math.fsum((x - mean) ** 3 for x in values) / n
    return float(m3 / (m2 ** 1.5))
```

This uses the biased coefficient \(m_3 / m_2^{3/2}\). It returns `nan` when there are no non-missing values or the values have zero variance, since skewness is undefined in those cases.

