from collections import Counter
from math import fsum


def column_summary_stats(table, mapping, features):
    result = {}

    for feature in features:
        if feature not in table:
            raise ValueError(f"Requested feature {feature!r} is not in the table")

        values = [mapping.get(value, value) for value in table[feature]]
        if not values:
            raise ValueError(f"Cannot compute statistics for empty column {feature!r}")

        mean = fsum(values) / len(values)
        ordered = sorted(values)
        middle = len(ordered) // 2

        if len(ordered) % 2:
            median = float(ordered[middle])
        else:
            median = (ordered[middle - 1] + ordered[middle]) / 2

        counts = Counter(values)
        highest_count = max(counts.values())
        mode = min(value for value, count in counts.items()
                   if count == highest_count)

        variance = fsum((value - mean) ** 2 for value in values) / len(values)

        result[feature] = {
            "mean": mean,
            "median": median,
            "mode": mode,
            "variance": variance,
        }

    return result
