        self.found_table = False
        self.in_table = False
        self.nested_tables = 0
        self.headers = []
        self.rows = []
        self.current_row = None
        self.cell_kind = None
        self.cell_parts = []

    def _finish_cell(self):
        if self.cell_kind is None:
            return

        text = "".join(self.cell_parts).strip()
        if self.cell_kind == "th":
            self.headers.append(text)
        elif self.current_row is not None:
            self.current_row.append(text)

        self.cell_kind = None
        self.cell_parts = []

    def _finish_row(self):
        self._finish_cell()
        if self.current_row is not None:
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        if tag == "table":
            if not self.found_table:
                self.found_table = True
                self.in_table = True
            elif self.in_table:
                self.nested_tables += 1
            return

        if not self.in_table or self.nested_tables:
            return

        if tag == "tr":
            self._finish_row()
            self.current_row = []
        elif tag in ("th", "td"):
            self._finish_cell()
            self.cell_kind = tag

    def handle_endtag(self, tag):
        if tag == "table":
            if self.nested_tables:
                self.nested_tables -= 1
            elif self.in_table:
                self._finish_row()
                self.in_table = False
            return

        if not self.in_table or self.nested_tables:
            return

        if tag in ("th", "td"):
            self._finish_cell()
        elif tag == "tr":
            self._finish_row()

    def handle_data(self, data):
        if self.in_table and not self.nested_tables and self.cell_kind:
            self.cell_parts.append(data)


