            return

        if tag == "table":
            if not self.found_table:
                self.found_table = True
                self.table_depth = 1
            elif self.table_depth:
                self.table_depth += 1
            return

        if not self.table_depth:
            return

        if tag == "tr" and self.table_depth == 1:
            self._finish_row()
            self.in_row = True
            self.row_cells = []
            self.row_has_td = False
        elif tag in ("th", "td") and self.table_depth == 1 and self.in_row:
            self._finish_cell()
            self.cell_kind = tag
            self.cell_text = []

    def handle_endtag(self, tag):
        if self.done:
            return

        if tag in ("th", "td") and self.table_depth == 1:
            self._finish_cell()
        elif tag == "tr" and self.table_depth == 1:
            self._finish_row()
        elif tag == "table" and self.table_depth:
            self.table_depth -= 1
            if self.table_depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.cell_kind is not None:
            self.cell_text.append(data)

    def _finish_cell(self):
        if self.cell_kind is None:
            return

        text = "".join(self.cell_text).strip()
        if self.cell_kind == "th":
            self.headers.append(text)
        else:
            self.row_cells.append(text)
            self.row_has_td = True

        self.cell_kind = None
        self.cell_text = []

    def _finish_row(self):
        self._finish_cell()
        if self.in_row and self.row_has_td:
            self.rows.append(self.row_cells)
        self.in_row = False
        self.row_cells = []
        self.row_has_td = False


