import math

def row_zscores_and_correlation(data):
    """Return the row-wise z-score matrix and its column correlation matrix.

    Rows with zero standard deviation, or columns with undefined correlations,
    raise ValueError.
    """
    if not data:
        return [], []

    n_rows = len(data)
    n_cols = len(data[0])

    if any(len(row) != n_cols for row in data):
        raise ValueError("data must be rectangular")
    if n_cols == 0:
        return [[] for _ in data], []

    zscores = []
    for row in data:
        mean = sum(row) / n_cols
        variance = sum((x - mean) ** 2 for x in row) / n_cols
        std = math.sqrt(variance)
        if std == 0:
            raise ValueError("cannot standardize a constant row")
        zscores.append([(x - mean) / std for x in row])

    # Center each column for the Pearson correlation calculation.
    columns = [
        [zscores[r][c] for r in range(n_rows)]
        for c in range(n_cols)
    ]
    means = [sum(col) / n_rows for col in columns]
    centered = [
        [x - means[c] for x in columns[c]]
        for c in range(n_cols)
    ]
    norms = [math.sqrt(sum(x * x for x in col)) for col in centered]

    if any(norm == 0 for norm in norms):
        raise ValueError("correlation is undefined for a constant column")

    correlations = [
        [
            sum(centered[i][r] * centered[j][r] for r in range(n_rows))
            / (norms[i] * norms[j])
            for j in range(n_cols)
        ]
        for i in range(n_cols)
    ]

    return zscores, correlations
