def row_zscores_and_correlation(data):
    """Return (row-wise z-scores, Pearson correlations between columns).

    Zero-variance rows produce NaN z-scores; correlations involving
    undefined or constant columns are NaN.
    """
    if not data:
        return [], []

    ncols = len(data[0])
    if any(len(row) != ncols for row in data):
        raise ValueError("data must be a rectangular matrix")
    if ncols == 0:
        return ([[] for _ in data], [])

    # Standardise each row using its population standard deviation.
    zscores = []
    for row in data:
        mean = sum(row) / ncols
        std = sqrt(sum((x - mean) ** 2 for x in row) / ncols)
        zscores.append(
            [(x - mean) / std for x in row] if std != 0
            else [nan] * ncols
        )

    # Compute Pearson correlations between columns.
    nrows = len(zscores)
    means = [
        sum(zscores[r][c] for r in range(nrows)) / nrows
        for c in range(ncols)
    ]
    centered = [
        [zscores[r][c] - means[c] for r in range(nrows)]
        for c in range(ncols)
    ]
    sums_of_squares = [
        sum(x * x for x in centered[c])
        for c in range(ncols)
    ]

    correlations = []
    for i in range(ncols):
        row = []
        for j in range(ncols):
            denominator = sqrt(sums_of_squares[i] * sums_of_squares[j])
            numerator = sum(centered[i][r] * centered[j][r]
                            for r in range(nrows))
            row.append(numerator / denominator if denominator != 0 else nan)
        correlations.append(row)

    return zscores, correlations
```

A zero population standard deviation makes that row’s z-scores undefined, so this implementation represents them as `NaN`. Correlations for constant or otherwise undefined columns are also `NaN`.

