from math import sqrt


def row_zscores_and_correlation(data):
    """Return the row-wise z-score matrix and its column correlation matrix.

    Raises ValueError when a row has zero variance or a column correlation
    is undefined (for example, when a column has zero variance).
    """
    if not data:
        return [], []

    n_cols = len(data[0])
    if any(len(row) != n_cols for row in data):
        raise ValueError("data must be rectangular")

    if n_cols == 0:
        return [[] for _ in data], []

    zscores = []
    for row in data:
        mean = sum(row) / n_cols
        std = sqrt(sum((x - mean) ** 2 for x in row) / n_cols)
        if std == 0:
            raise ValueError("cannot standardise a row with zero variance")
        zscores.append([(x - mean) / std for x in row])

    n_rows = len(zscores)
    col_means = [
        sum(zscores[r][c] for r in range(n_rows)) / n_rows
        for c in range(n_cols)
    ]
    centered = [
        [zscores[r][c] - col_means[c] for c in range(n_cols)]
        for r in range(n_rows)
    ]
    col_norms = [
        sqrt(sum(centered[r][c] ** 2 for r in range(n_rows)))
        for c in range(n_cols)
    ]

    if any(norm == 0 for norm in col_norms):
        raise ValueError("cannot compute correlation for a constant column")

    correlations = [
        [
            sum(centered[r][i] * centered[r][j] for r in range(n_rows))
            / (col_norms[i] * col_norms[j])
            for j in range(n_cols)
        ]
        for i in range(n_cols)
    ]

    return zscores, correlations
```

