import numpy as np

def principal_component_variances(x, y, labels):
    if not (len(x) == len(y) == len(labels)):
        raise ValueError("x, y, and labels must have the same number of series")

    result = {}
    for xi, yi, label in zip(x, y, labels):
        if len(xi) != len(yi):
            raise ValueError("Each x series must match its corresponding y series")
        if len(xi) < 2:
            raise ValueError("Each dataset must contain at least two points")

        points = np.column_stack((xi, yi))
        covariance = np.cov(points, rowvar=False, ddof=1)
        variances = np.linalg.eigvalsh(covariance)[::-1]
        result[label] = variances.tolist()

    return result
```

The eigenvalues of the sample covariance matrix are the principal-component variances, returned from largest to smallest. This uses NumPy.

