def last_column_histogram(rows, bins=20):
    if not rows:
        raise ValueError("rows must not be empty")
    if not isinstance(bins, int) or isinstance(bins, bool) or bins <= 0:
        raise ValueError("bins must be a positive integer")
    if any(not row for row in rows):
        raise ValueError("each row must contain at least one value")

    values = [float(row[-1]) for row in rows]
    low, high = min(values), max(values)

    edges = [
        low + (high - low) * i / bins
        for i in range(bins + 1)
    ]
    edges[0], edges[-1] = low, high

    counts = [0] * bins
    if low == high:
        # With zero range, place all values in the final bin.
        counts[-1] = len(values)
    else:
        width = (high - low) / bins
        for value in values:
            index = min(int((value - low) / width), bins - 1)
            counts[index] += 1

    return counts, edges
```

The maximum value is included in the final bin. If all values are identical, the edges are repeated and all values are counted in that final bin.

