from datetime import date

def forecast_closing_prices(dates, prices):
    if len(dates) != len(prices):
        raise ValueError("dates and prices must have the same length")
    if not dates:
        raise ValueError("at least one date and price is required")

    days = [date.fromisoformat(d).toordinal() for d in dates]
    latest_day = max(days)

    mean_day = sum(days) / len(days)
    mean_price = sum(prices) / len(prices)

    denominator = sum((day - mean_day) ** 2 for day in days)
    if denominator == 0:
        raise ValueError("dates must include at least two distinct days")

    slope = sum(
        (day - mean_day) * (price - mean_price)
        for day, price in zip(days, prices)
    ) / denominator
    intercept = mean_price - slope * mean_day

    return [
        float(intercept + slope * (latest_day + offset))
        for offset in range(1, 8)
    ]
```

This fits the regression using elapsed calendar days, so the input dates can be unsorted or nonconsecutive.

