import fnmatch
import re


def extract_matches_from_files(files, name_pattern, value_pattern):
    def natural_key(name):
        return [
            (1, int(part)) if part.isdigit() else (0, part.casefold())
            for part in re.split(r"(\d+)", name)
        ]

    selected = [name for name in files if fnmatch.fnmatchcase(name, name_pattern)]
    if not selected:
        raise ValueError(f"No file names match {name_pattern!r}")

    regex = re.compile(value_pattern)
    results = []

    for name in sorted(selected, key=natural_key):
        matches = []
        for match in regex.finditer(files[name]):
            if regex.groups == 1:
                matches.append(match.group(1) or "")
            else:
                matches.append(match.group(0))
        results.append((name, matches))

    return results
