def chi_square_independence(xs, ys):
    if not xs or not ys:
        raise ValueError("lists must not be empty")
    if len(xs) != len(ys):
        raise ValueError("lists must have equal lengths")

    row_totals = {}
    col_totals = {}
    counts = {}

    for x, y in zip(xs, ys):
        row_totals[x] = row_totals.get(x, 0) + 1
        col_totals[y] = col_totals.get(y, 0) + 1
        counts[x, y] = counts.get((x, y), 0) + 1

    r, c = len(row_totals), len(col_totals)
    if r < 2 or c < 2:
        raise ValueError("each variable must have at least two categories")

    n = len(xs)
    statistic = 0.0
    for x, row_total in row_totals.items():
        for y, col_total in col_totals.items():
            expected = row_total * col_total / n
            observed = counts.get((x, y), 0)
            statistic += (observed - expected) ** 2 / expected

    return statistic, (r - 1) * (c - 1)
