def chi_square_independence(xs, ys):
    if not xs or not ys:
        raise ValueError("Lists must not be empty")
    if len(xs) != len(ys):
        raise ValueError("Lists must have equal lengths")

    x_categories = list(dict.fromkeys(xs))
    y_categories = list(dict.fromkeys(ys))

    if len(x_categories) < 2 or len(y_categories) < 2:
        raise ValueError("Each variable must have at least two categories")

    x_counts = {x: 0 for x in x_categories}
    y_counts = {y: 0 for y in y_categories}
    cells = {(x, y): 0 for x in x_categories for y in y_categories}

    for x, y in zip(xs, ys):
        x_counts[x] += 1
        y_counts[y] += 1
        cells[x, y] += 1

    n = len(xs)
    statistic = sum(
        (observed - x_counts[x] * y_counts[y] / n) ** 2
        / (x_counts[x] * y_counts[y] / n)
        for (x, y), observed in cells.items()
    )
    dof = (len(x_categories) - 1) * (len(y_categories) - 1)

    return statistic, dof
```

