def chi_square_independence(xs, ys):
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    if not xs:
        raise ValueError("the lists must not be empty")

    x_categories = list(dict.fromkeys(xs))
    y_categories = list(dict.fromkeys(ys))

    if len(x_categories) < 2 or len(y_categories) < 2:
        raise ValueError("each variable must have at least two categories")

    x_index = {category: i for i, category in enumerate(x_categories)}
    y_index = {category: j for j, category in enumerate(y_categories)}

    table = [[0] * len(y_categories) for _ in x_categories]
    for x, y in zip(xs, ys):
        table[x_index[x]][y_index[y]] += 1

    row_totals = [sum(row) for row in table]
    col_totals = [
        sum(table[i][j] for i in range(len(x_categories)))
        for j in range(len(y_categories))
    ]
    total = len(xs)

    statistic = 0.0
    for i, row in enumerate(table):
        for j, observed in enumerate(row):
            expected = row_totals[i] * col_totals[j] / total
            statistic += (observed - expected) ** 2 / expected

    dof = (len(x_categories) - 1) * (len(y_categories) - 1)
    return statistic, dof
