    if len(xs) != len(ys):
        raise ValueError("Input lists must have the same length")

    x_categories = list(dict.fromkeys(xs))
    y_categories = list(dict.fromkeys(ys))

    if len(x_categories) < 2 or len(y_categories) < 2:
        raise ValueError("Each variable must have at least two categories")

    row_totals = {x: 0 for x in x_categories}
    col_totals = {y: 0 for y in y_categories}
    observed = {}

    for x, y in zip(xs, ys):
        row_totals[x] += 1
        col_totals[y] += 1
        observed[x, y] = observed.get((x, y), 0) + 1

    n = len(xs)
    statistic = 0.0

    for x in x_categories:
        for y in y_categories:
            expected = row_totals[x] * col_totals[y] / n
            actual = observed.get((x, y), 0)
            statistic += (actual - expected) ** 2 / expected

    dof = (len(x_categories) - 1) * (len(y_categories) - 1)
    return statistic, dof
