from bisect import bisect_right

def histogram_bins(values, bins):
    values = list(values)

    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be a positive integer")
        if not values:
            raise ValueError("values must not be empty when bins is an integer")

        low, high = min(values), max(values)
        width = (high - low) / bins
        edges = [float(low + i * width) for i in range(bins + 1)]
    else:
        edges = [float(edge) for edge in bins]
        if len(edges) < 2 or any(a >= b for a, b in zip(edges, edges[1:])):
            raise ValueError("bin edges must be strictly increasing")

    counts = [0] * (len(edges) - 1)

    for value in values:
        if value < edges[0] or value > edges[-1]:
            continue
        if value == edges[-1]:
            counts[-1] += 1
        else:
            index = bisect_right(edges, value) - 1
            counts[index] += 1

    return counts, edges
