from bisect import bisect_right

def histogram_bins(values, bins):
    values = list(values)
    if not values:
        raise ValueError("values must not be empty")

    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be a positive integer")

        low, high = float(min(values)), float(max(values))
        if low == high:
            raise ValueError("cannot create equal-width bins when all values are equal")

        edges = [low + (high - low) * i / bins for i in range(bins)]
        edges.append(high)
    else:
        edges = [float(edge) for edge in bins]
        if len(edges) < 2 or any(a >= b for a, b in zip(edges, edges[1:])):
            raise ValueError("bin edges must be strictly increasing")

    counts = [0] * (len(edges) - 1)

    for value in values:
        if value < edges[0] or value > edges[-1]:
            continue

        index = bisect_right(edges, value) - 1
        if index == len(counts):  # Include the final right edge.
            index -= 1
        counts[index] += 1

    return counts, edges
