from bisect import bisect_right

def histogram_bins(values, bins):
    values = [float(value) for value in values]

    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be a positive integer")
        if not values:
            raise ValueError("values cannot be empty when bins is an integer")

        low, high = min(values), max(values)
        if low == high:
            # Give identical values a nonzero range to bin into.
            low -= 0.5
            high += 0.5

        width = (high - low) / bins
        edges = [low + i * width for i in range(bins)] + [high]
    else:
        edges = [float(edge) for edge in bins]
        if len(edges) < 2:
            raise ValueError("at least two bin edges are required")
        if any(left >= right for left, right in zip(edges, edges[1:])):
            raise ValueError("bin edges must be strictly increasing")

    counts = [0] * (len(edges) - 1)

    for value in values:
        if value < edges[0] or value > edges[-1]:
            continue
        if value == edges[-1]:
            counts[-1] += 1
        else:
            counts[bisect_right(edges, value) - 1] += 1

    return counts, [float(edge) for edge in edges]
