        if bins <= 0:
            raise ValueError("bins must be a positive integer")
        if not values:
            raise ValueError("cannot infer bin edges from empty values")

        low, high = min(values), max(values)
        if low == high:
            # Give identical values a nonzero-width range.
            low, high = low - 0.5, high + 0.5

        edges = [
            float(low + (high - low) * i / bins)
            for i in range(bins + 1)
        ]
        edges[-1] = float(high)
    else:
        edges = [float(edge) for edge in bins]
        if len(edges) < 2 or any(a >= b for a, b in zip(edges, edges[1:])):
            raise ValueError("bin edges must be strictly increasing")

    counts = [0] * (len(edges) - 1)

    for value in values:
        if value < edges[0] or value > edges[-1]:
            continue

        # The final bin includes its right edge; other bins are half-open.
        index = len(counts) - 1 if value == edges[-1] else bisect_right(edges, value) - 1
        counts[index] += 1

