from collections import Counter


def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit P2 or P5 PGM image."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise ValueError("image data must be bytes-like")
    data = bytes(data)

    if len(data) < 2 or data[:2] not in (b"P2", b"P5"):
        raise ValueError("not a P2 or P5 PGM image")
    magic = data[:2]
    pos = 2

    whitespace = b" \t\r\n\v\f"

    def next_token(pos):
        # Skip whitespace and comments.
        while pos < len(data):
            if data[pos] in whitespace:
                pos += 1
            elif data[pos] == ord("#"):
                while pos < len(data) and data[pos] not in b"\r\n":
                    pos += 1
            else:
                break

        start = pos
        while pos < len(data) and data[pos] not in whitespace + b"#":
            pos += 1
        if start == pos:
            return None, pos
        return data[start:pos], pos

    def positive_integer(token, name):
        if token is None or not token or any(c < ord("0") or c > ord("9") for c in token):
            raise ValueError(f"invalid {name}")
        value = int(token)
        if value <= 0:
            raise ValueError(f"invalid {name}")
        return value

    # Read and validate the header.
    width_token, pos = next_token(pos)
    height_token, pos = next_token(pos)
    maxval_token, pos = next_token(pos)

    width = positive_integer(width_token, "width")
    height = positive_integer(height_token, "height")
    if maxval_token != b"255":
        raise ValueError("only 8-bit PGM images (maxval 255) are supported")

    pixel_count = width * height

    if magic == b"P5":
        # The binary raster starts after one header separator. Treat CRLF as
        # one line ending; do not skip further bytes, since they may be pixels.
        if pos >= len(data) or data[pos] not in whitespace:
            raise ValueError("missing separator before P5 raster")
        if data[pos:pos + 2] == b"\r\n":
            pos += 2
        else:
            pos += 1

        raster = data[pos:]
        if len(raster) != pixel_count:
            raise ValueError("incorrect P5 raster length")
        return dict(Counter(raster))

    # P2: read exactly width * height decimal pixel values.
    values = []
    while True:
        token, pos = next_token(pos)
        if token is None:
            break
        if not token or any(c < ord("0") or c > ord("9") for c in token):
            raise ValueError("invalid P2 pixel value")
        value = int(token)
        if value > 255:
            raise ValueError("P2 pixel value out of range")
        values.append(value)
        if len(values) > pixel_count:
            raise ValueError("too many P2 pixel values")

    if len(values) != pixel_count:
        raise ValueError("incorrect number of P2 pixel values")
    return dict(Counter(values))
```

For P5, the parser consumes just the required header separator (treating CRLF as one line ending); skipping arbitrary whitespace there could accidentally discard valid pixel bytes. P2 comments and whitespace are accepted between tokens.

```python
def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit P2 or P5 PGM image."""
    if not isinstance(data, bytes) or not data.startswith((b"P2", b"P5")):
        raise ValueError("invalid PGM data")

    whitespace = b" \t\n\r\v\f"

    def next_token(pos):
        # Skip whitespace and comments before the next token.
        while pos < len(data):
            if data[pos] in whitespace:
                pos += 1
            elif data[pos] == ord("#"):
                newline = data.find(b"\n", pos)
                pos = len(data) if newline == -1 else newline + 1
            else:
                break

        start = pos
        while pos < len(data) and data[pos] not in whitespace and data[pos] != ord("#"):
            pos += 1
        if start == pos:
            return None, pos
        return data[start:pos], pos

    def decimal(token):
        if token is None or not token or any(c < ord("0") or c > ord("9") for c in token):
            raise ValueError("invalid PGM number")
        return int(token)

    try:
        magic, pos = next_token(0)
        if magic not in (b"P2", b"P5"):
            raise ValueError("unsupported PGM variant")

        width_token, pos = next_token(pos)
        height_token, pos = next_token(pos)
        maxval_token, pos = next_token(pos)

        width = decimal(width_token)
        height = decimal(height_token)
        maxval = decimal(maxval_token)
        if width <= 0 or height <= 0 or not 1 <= maxval <= 255:
            raise ValueError("invalid PGM dimensions or maximum value")

        count = width * height

        if magic == b"P5":
            # The raster starts after the required whitespace separator.
            if pos >= len(data) or data[pos] not in whitespace:
                raise ValueError("missing PGM raster separator")
            if data[pos:pos + 2] == b"\r\n":
                pos += 2
            else:
                pos += 1

            pixels = data[pos:]
            if len(pixels) != count or any(value > maxval for value in pixels):
                raise ValueError("invalid PGM raster")

        else:
            pixels = []
            for _ in range(count):
                token, pos = next_token(pos)
                value = decimal(token)
                if value > maxval:
                    raise ValueError("pixel value exceeds PGM maximum")
                pixels.append(value)

            # Only whitespace and comments may follow the ASCII raster.
            if next_token(pos)[0] is not None:
                raise ValueError("extra data after PGM raster")

        histogram = {}
        for value in pixels:
            histogram[value] = histogram.get(value, 0) + 1
        return histogram

    except (TypeError, OverflowError) as exc:
        raise ValueError("invalid PGM data") from exc
