def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit P2 or P5 PGM image."""
    if not isinstance(data, (bytes, bytearray)):
        raise ValueError("data must be bytes")

    data = bytes(data)
    whitespace = b" \t\r\n\v\f"

    def token(pos):
        # Skip whitespace and comments before the next token.
        while pos < len(data):
            if data[pos] in whitespace:
                pos += 1
            elif data[pos] == ord("#"):
                newline = data.find(b"\n", pos)
                pos = len(data) if newline == -1 else newline + 1
            else:
                break

        start = pos
        while pos < len(data) and data[pos] not in whitespace and data[pos] != ord("#"):
            pos += 1
        if start == pos:
            raise ValueError("missing PGM header or pixel data")
        return data[start:pos], pos

    def positive_integer(raw):
        if not raw or any(c < ord("0") or c > ord("9") for c in raw):
            raise ValueError("invalid integer in PGM")
        value = int(raw)
        if value <= 0:
            raise ValueError("dimensions and maxval must be positive")
        return value

    if not data.startswith((b"P2", b"P5")):
        raise ValueError("unsupported or missing PGM magic number")

    magic, pos = token(0)
    if magic not in (b"P2", b"P5"):
        raise ValueError("unsupported PGM variant")

    width_raw, pos = token(pos)
    height_raw, pos = token(pos)
    maxval_raw, pos = token(pos)

    width = positive_integer(width_raw)
    height = positive_integer(height_raw)
    maxval = positive_integer(maxval_raw)
    if maxval > 255:
        raise ValueError("PGM is not 8-bit")

    count = width * height

    if magic == b"P5":
        # The binary raster starts after one whitespace separator.
        if pos >= len(data) or data[pos] not in whitespace:
            raise ValueError("missing separator before P5 raster")
        if data[pos:pos + 2] == b"\r\n":
            pos += 2
        else:
            pos += 1

        pixels = data[pos:]
        if len(pixels) != count or any(value > maxval for value in pixels):
            raise ValueError("invalid P5 raster")
    else:
        values = []
        while True:
            try:
                raw, pos = token(pos)
            except ValueError:
                break
            if not raw or any(c < ord("0") or c > ord("9") for c in raw):
                raise ValueError("invalid P2 pixel value")
            value = int(raw)
            if value > maxval:
                raise ValueError("P2 pixel value exceeds maxval")
            values.append(value)

        if len(values) != count:
            raise ValueError("incorrect number of P2 pixels")
        pixels = values

    histogram = {}
    for value in pixels:
        histogram[value] = histogram.get(value, 0) + 1
    return histogram
