def grayscale_histogram(data):
    """Return the pixel-value histogram of an 8-bit P2 or P5 PGM image."""
    if not isinstance(data, bytes):
        raise ValueError("image data must be bytes")

    whitespace = b" \t\r\n\v\f"
    n = len(data)

    def next_token(pos):
        # Skip whitespace and comments before the next header or P2 token.
        while pos < n:
            if data[pos] in whitespace:
                pos += 1
            elif data[pos] == ord("#"):
                newline = data.find(b"\n", pos)
                pos = n if newline == -1 else newline + 1
            else:
                break

        start = pos
        while pos < n and data[pos] not in whitespace and data[pos] != ord("#"):
            pos += 1
        if start == pos:
            return None, pos
        return data[start:pos], pos

    def integer(token):
        if token is None or not token or any(c < 48 or c > 57 for c in token):
            raise ValueError("invalid PGM integer")
        return int(token)

    magic, pos = next_token(0)
    if magic not in (b"P2", b"P5"):
        raise ValueError("unsupported or invalid PGM format")

    width = integer(next_token(pos)[0])
    height, pos = next_token(pos)[0], None  # parsed below to keep token positions clear
    # Re-read the header fields in order.
    width = integer(next_token(next_token(0)[1])[0])
    height_token, pos = next_token(next_token(next_token(0)[1])[1])
    height = integer(height_token)
    maxval_token, pos = next_token(pos)
    maxval = integer(maxval_token)

    if width <= 0 or height <= 0 or not 1 <= maxval <= 255:
        raise ValueError("invalid dimensions or maximum pixel value")
    count = width * height

    if magic == b"P5":
        # The binary raster starts after the single separator following maxval.
        if pos >= n or data[pos] not in whitespace:
            raise ValueError("missing separator before P5 raster")
        pos += 1
        if data[pos - 1:pos] == b"\r" and pos < n and data[pos] == ord("\n"):
            pos += 1

        pixels = data[pos:]
        if len(pixels) != count or any(value > maxval for value in pixels):
            raise ValueError("invalid P5 raster")
        histogram = {}
        for value in pixels:
            histogram[value] = histogram.get(value, 0) + 1
        return histogram

    histogram = {}
    for _ in range(count):
        token, pos = next_token(pos)
        value = integer(token)
        if value > maxval:
            raise ValueError("pixel value exceeds maxval")
        histogram[value] = histogram.get(value, 0) + 1

    if next_token(pos)[0] is not None:
        raise ValueError("too many P2 pixel values")
    return histogram
