from collections import Counter


def grayscale_histogram(data):
    """Return a pixel-value histogram for an 8-bit P2 or P5 PGM image."""
    if not isinstance(data, (bytes, bytearray, memoryview)):
        raise ValueError("PGM data must be bytes-like")
    data = bytes(data)

    whitespace = b" \t\n\r\v\f"

    def token(pos):
        # Skip header whitespace and comments.
        while pos < len(data):
            if data[pos] in whitespace:
                pos += 1
            elif data[pos] == ord("#"):
                while pos < len(data) and data[pos] not in b"\r\n":
                    pos += 1
            else:
                break

        start = pos
        while pos < len(data) and data[pos] not in whitespace + b"#":
            pos += 1
        if start == pos:
            raise ValueError("incomplete PGM header")
        return data[start:pos], pos

    def decimal(raw):
        if not raw or any(c < ord("0") or c > ord("9") for c in raw):
            raise ValueError("invalid PGM number")
        return int(raw)

    try:
        magic, pos = token(0)
        if magic not in (b"P2", b"P5"):
            raise ValueError("unsupported PGM format")

        width_raw, pos = token(pos)
        height_raw, pos = token(pos)
        maxval_raw, pos = token(pos)

        width = decimal(width_raw)
        height = decimal(height_raw)
        maxval = decimal(maxval_raw)

        if width <= 0 or height <= 0 or not 1 <= maxval <= 255:
            raise ValueError("invalid PGM dimensions or maxval")

        count = width * height

        if magic == b"P5":
            # The raster follows one header separator; preserve any following
            # whitespace bytes, since they may be pixel values.
            if pos >= len(data):
                raise ValueError("missing PGM raster")
            if data[pos] in whitespace:
                if data[pos:pos + 2] == b"\r\n":
                    pos += 2
                else:
                    pos += 1
            elif data[pos] == ord("#"):
                while pos < len(data) and data[pos] not in b"\r\n":
                    pos += 1
                if pos >= len(data):
                    raise ValueError("missing PGM raster separator")
                if data[pos:pos + 2] == b"\r\n":
                    pos += 2
                else:
                    pos += 1
            else:
                raise ValueError("missing PGM raster separator")

            pixels = data[pos:]
            if len(pixels) != count or any(value > maxval for value in pixels):
                raise ValueError("invalid PGM raster")
            return dict(Counter(pixels))

        # P2: parse exactly width * height decimal pixel values.
        values = []
        while True:
            try:
                raw, pos = token(pos)
            except ValueError:
                break
            value = decimal(raw)
            if value > maxval:
                raise ValueError("pixel value exceeds maxval")
            values.append(value)
            if len(values) > count:
                raise ValueError("too many PGM pixels")

        if len(values) != count:
            raise ValueError("wrong number of PGM pixels")
        return dict(Counter(values))

    except (IndexError, OverflowError) as exc:
        raise ValueError("invalid PGM image") from exc
