def classical_seasonal_decomposition(values, period, model="additive"):
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or isinstance(period, bool) or period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    trend = [None] * n

    if period % 2:  # Odd-period centred moving average
        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:  # Average adjacent period-length moving averages
        half = period // 2
        for i in range(half, n - half):
            left = sum(values[i - half:i + half]) / period
            right = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (left + right) / 2

    by_phase = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                by_phase[i % period].append(value - trend[i])
            else:
                by_phase[i % period].append(value / trend[i])

    phase_averages = [sum(items) / len(items) for items in by_phase]

    if model == "additive":
        offset = sum(phase_averages) / period
        seasonal_by_phase = [average - offset for average in phase_averages]
    else:
        scale = sum(phase_averages) / period
        seasonal_by_phase = [average / scale for average in phase_averages]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]

    resid = [None] * n
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                resid[i] = value - trend[i] - seasonal[i]
            else:
                resid[i] = value / (trend[i] * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "resid": resid}
