def classical_seasonal_decomposition(values, period, model="additive"):
    """Decompose an evenly spaced series using classical moving averages."""
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    if isinstance(period, bool) or not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    # Compute the period-length moving averages.
    moving_averages = [
        sum(values[start:start + period]) / period
        for start in range(n - period + 1)
    ]

    trend = [None] * n
    if period % 2:  # Odd period: the moving averages are already centred.
        half = period // 2
        for start, average in enumerate(moving_averages):
            trend[start + half] = average
    else:  # Even period: centre by averaging adjacent moving averages.
        half = period // 2
        for start in range(len(moving_averages) - 1):
            trend[start + half] = (
                moving_averages[start] + moving_averages[start + 1]
            ) / 2

    # Estimate one seasonal value for each position in the period.
    by_phase = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                by_phase[i % period].append(value - trend[i])
            else:
                by_phase[i % period].append(value / trend[i])

    seasonal_by_phase = [
        sum(samples) / len(samples) for samples in by_phase
    ]

    # Normalize seasonal values so they sum to zero (additive) or average
    # to one (multiplicative).
    if model == "additive":
        seasonal_mean = sum(seasonal_by_phase) / period
        seasonal_by_phase = [
            value - seasonal_mean for value in seasonal_by_phase
        ]
    else:
        seasonal_mean = sum(seasonal_by_phase) / period
        seasonal_by_phase = [
            value / seasonal_mean for value in seasonal_by_phase
        ]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]
    resid = [None] * n

    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                resid[i] = value - trend[i] - seasonal[i]
            else:
                resid[i] = value / (trend[i] * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "resid": resid}
