def classical_seasonal_decomposition(values, period, model="additive"):
    """Decompose an evenly spaced series using a centred moving average."""
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    if isinstance(period, bool) or not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    trend = [None] * n

    # For even periods, average adjacent moving averages to centre them.
    if period % 2:
        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half : i + half + 1]) / period
    else:
        half = period // 2
        moving_averages = [
            sum(values[start : start + period]) / period
            for start in range(n - period + 1)
        ]
        for i in range(half, n - half):
            left = i - half
            trend[i] = (moving_averages[left] + moving_averages[left + 1]) / 2

    # Estimate one seasonal value for each position in the period.
    phase_values = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                phase_values[i % period].append(value - trend[i])
            else:
                if trend[i] == 0:
                    raise ValueError("multiplicative decomposition requires nonzero trend values")
                phase_values[i % period].append(value / trend[i])

    seasonal_by_phase = [
        sum(items) / len(items) for items in phase_values
    ]

    # Normalize seasonal values: mean zero for additive, mean one for multiplicative.
    mean_seasonal = sum(seasonal_by_phase) / period
    if model == "additive":
        seasonal_by_phase = [value - mean_seasonal for value in seasonal_by_phase]
    else:
        if mean_seasonal == 0:
            raise ValueError("cannot normalize multiplicative seasonal values")
        seasonal_by_phase = [value / mean_seasonal for value in seasonal_by_phase]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]
    resid = [None] * n

    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == "additive":
                resid[i] = value - trend[i] - seasonal[i]
            else:
                resid[i] = value / (trend[i] * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "resid": resid}
