def classical_seasonal_decomposition(values, period, model='additive'):
    """Decompose an evenly spaced series into trend, seasonal, and residual parts."""
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError("period must be a positive integer")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    # Compute the centred moving average. For an even period, centre by
    # averaging two adjacent period-length moving averages.
    trend = [None] * n
    half = period // 2

    for i in range(half, n - half):
        if period % 2:
            trend[i] = sum(values[i - half:i + half + 1]) / period
        else:
            first = sum(values[i - half:i + half]) / period
            second = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (first + second) / 2

    # Estimate a seasonal value for each position within the period.
    by_phase = [[] for _ in range(period)]
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == 'additive':
                by_phase[i % period].append(value - trend[i])
            else:
                by_phase[i % period].append(value / trend[i])

    seasonal_by_phase = [sum(group) / len(group) for group in by_phase]

    # Normalize seasonal values: additive effects sum to zero; multiplicative
    # factors average to one.
    if model == 'additive':
        adjustment = sum(seasonal_by_phase) / period
        seasonal_by_phase = [x - adjustment for x in seasonal_by_phase]
    else:
        adjustment = sum(seasonal_by_phase) / period
        seasonal_by_phase = [x / adjustment for x in seasonal_by_phase]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]

    resid = [None] * n
    for i, value in enumerate(values):
        if trend[i] is not None:
            if model == 'additive':
                resid[i] = value - trend[i] - seasonal[i]
            else:
                resid[i] = value / (trend[i] * seasonal[i])

    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}
