def classical_seasonal_decomposition(values, period, model="additive"):
    """Decompose an evenly spaced series using classical moving averages."""
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    if isinstance(period, bool) or not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")

    values = list(values)
    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two full periods")

    # Compute period-wide moving averages.
    window_averages = [
        sum(values[start:start + period]) / period
        for start in range(n - period + 1)
    ]

    # Odd periods have a centered window. For even periods, average adjacent
    # window averages to center the trend between them.
    trend = [None] * n
    if period % 2:
        offset = period // 2
        for start, average in enumerate(window_averages):
            trend[start + offset] = average
    else:
        offset = period // 2
        for start in range(len(window_averages) - 1):
            trend[start + offset] = (
                window_averages[start] + window_averages[start + 1]
            ) / 2

    # Estimate one seasonal value for each position in the period.
    seasonal_groups = [[] for _ in range(period)]
    for i, trend_value in enumerate(trend):
        if trend_value is not None:
            if model == "additive":
                seasonal_groups[i % period].append(values[i] - trend_value)
            else:
                seasonal_groups[i % period].append(values[i] / trend_value)

    seasonal_by_phase = [
        sum(group) / len(group) for group in seasonal_groups
    ]

    # Center additive effects at zero, or scale multiplicative effects to mean 1.
    if model == "additive":
        adjustment = sum(seasonal_by_phase) / period
        seasonal_by_phase = [value - adjustment for value in seasonal_by_phase]
    else:
        adjustment = sum(seasonal_by_phase) / period
        seasonal_by_phase = [value / adjustment for value in seasonal_by_phase]

    seasonal = [seasonal_by_phase[i % period] for i in range(n)]

    resid = [None] * n
    for i, trend_value in enumerate(trend):
        if trend_value is not None:
            if model == "additive":
                resid[i] = values[i] - trend_value - seasonal[i]
            else:
                resid[i] = values[i] / (trend_value * seasonal[i])

    return {"trend": trend, "seasonal": seasonal, "resid": resid}
