def standardize_pair(a, b):
    if len(a) != len(b):
        raise ValueError("a and b must have the same length")

    if not a:
        return []

    def standardize(column):
        mean = sum(column) / len(column)
        variance = sum((x - mean) ** 2 for x in column) / len(column)
        std_dev = sqrt(variance)

        if std_dev == 0:
            return [0.0] * len(column)

        return [(x - mean) / std_dev for x in column]

    standardized_a = standardize(a)
    standardized_b = standardize(b)

    return [[x, y] for x, y in zip(standardized_a, standardized_b)]
