import csv
import io
import math
import re
import statistics


_NUMBER = re.compile(
    r"[+-]?(?:(?:\d+|(?:\d{1,3}(?:,\d{3})+))(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?"
)


def summarize_numeric_csv(csv_text):
    rows = csv.reader(io.StringIO(csv_text))
    try:
        headers = next(rows)
    except StopIteration:
        return {"means": {}, "std_devs": {}, "f_value": None}

    columns = [[] for _ in headers]

    for row in rows:
        if not row:  # Ignore blank lines
            continue
        for i in range(len(headers)):
            columns[i].append(row[i].strip() if i < len(row) else "")

    numeric = {}
    for header, values in zip(headers, columns):
        if not values or not all(_NUMBER.fullmatch(value) for value in values):
            continue
        nums = [float(value.replace(",", "")) for value in values]
        if all(math.isfinite(x) for x in nums):
            numeric[header] = nums

    means = {name: statistics.mean(values) for name, values in numeric.items()}
    std_devs = {
        name: statistics.stdev(values) if len(values) >= 2 else None
        for name, values in numeric.items()
    }

    f_value = None
    groups = list(numeric.values())
    if len(groups) >= 2:
        total_n = sum(map(len, groups))
        grand_mean = sum(sum(group) for group in groups) / total_n
        ss_between = sum(
            len(group) * (statistics.mean(group) - grand_mean) ** 2
            for group in groups
        )
        ss_within = sum(
            sum((x - statistics.mean(group)) ** 2 for x in group)
            for group in groups
        )

        df_between = len(groups) - 1
        df_within = total_n - len(groups)
        if df_within > 0:
            ms_between = ss_between / df_between
            ms_within = ss_within / df_within
            f_value = (
                ms_between / ms_within
                if ms_within != 0
                else (math.inf if ms_between != 0 else math.nan)
            )

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
```

