                    raise ValueError
                columns[i].append(number)
            except ValueError:
                columns[i].append(None)

    numeric_columns = {}
    for name, values in zip(header, columns):
        if values and all(value is not None for value in values):
            numeric_columns[name] = values

    means = {
        name: math.fsum(values) / len(values)
        for name, values in numeric_columns.items()
    }
    std_devs = {}
    for name, values in numeric_columns.items():
        if len(values) < 2:
            std_devs[name] = None  # Sample standard deviation is undefined
        else:
            mean = means[name]
            std_devs[name] = math.sqrt(
                math.fsum((value - mean) ** 2 for value in values)
                / (len(values) - 1)
            )

    groups = list(numeric_columns.values())
    f_value = None

    if len(groups) >= 2:
        total_count = sum(map(len, groups))
        if total_count > len(groups):
            grand_mean = math.fsum(map(math.fsum, groups)) / total_count
            between = math.fsum(
                len(group) * (means[name] - grand_mean) ** 2
                for name, group in numeric_columns.items()
            )
            within = math.fsum(
                (value - means[name]) ** 2
                for name, group in numeric_columns.items()
                for value in group
            )

            if within == 0:
                f_value = math.inf if between > 0 else math.nan
            else:
                f_value = (between / (len(groups) - 1)) / (
                    within / (total_count - len(groups))
                )

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
```

A column is included only if every data-row value parses as a finite number. If a numeric column has only one value, its sample standard deviation is `None`; the F statistic is also `None` when there are too few observations to estimate within-group variance.

