import csv
import io
import math
import statistics


def summarize_numeric_csv(csv_text):
    rows = list(csv.reader(io.StringIO(csv_text)))
    if not rows:
        return {"means": {}, "std_devs": {}, "f_value": None}

    headers = rows[0]
    data_rows = [row for row in rows[1:] if row and any(cell.strip() for cell in row)]

    groups = {}
    for i, name in enumerate(headers):
        values = []
        for row in data_rows:
            if i >= len(row):
                break
            try:
                value = float(row[i].strip().replace(",", ""))
            except ValueError:
                break
            if not math.isfinite(value):
                break
            values.append(value)
        else:
            if values:
                groups[name] = values

    means = {name: statistics.mean(values) for name, values in groups.items()}
    std_devs = {
        name: statistics.stdev(values) if len(values) >= 2 else None
        for name, values in groups.items()
    }

    f_value = None
    if len(groups) >= 2:
        all_values = [value for values in groups.values() for value in values]
        total_n = len(all_values)
        residual_df = total_n - len(groups)

        if residual_df > 0:
            grand_mean = statistics.mean(all_values)
            ss_between = sum(
                len(values) * (statistics.mean(values) - grand_mean) ** 2
                for values in groups.values()
            )
            ss_within = sum(
                sum((value - statistics.mean(values)) ** 2 for value in values)
                for values in groups.values()
            )

            if ss_within == 0:
                f_value = math.inf if ss_between > 0 else None
            else:
                f_value = (ss_between / (len(groups) - 1)) / (ss_within / residual_df)

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
```

