import csv
import io
import math
import re

_NUMBER = re.compile(
    r"[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?"
)


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    headers = next(reader, [])

    columns = [[] for _ in headers]
    valid = [True] * len(headers)

    for row in reader:
        if not row:  # Ignore blank lines
            continue

        for i in range(len(headers)):
            if i >= len(row):
                valid[i] = False
                continue

            text = row[i].strip()
            if not _NUMBER.fullmatch(text):
                valid[i] = False
                continue

            value = float(text.replace(",", ""))
            if not math.isfinite(value):
                valid[i] = False
            else:
                columns[i].append(value)

    groups = {
        headers[i]: columns[i]
        for i in range(len(headers))
        if valid[i] and columns[i]
    }

    means = {
        name: math.fsum(values) / len(values)
        for name, values in groups.items()
    }

    # Sample standard deviation is undefined for a single observation.
    std_devs = {}
    for name, values in groups.items():
        if len(values) < 2:
            std_devs[name] = math.nan
        else:
            mean = means[name]
            std_devs[name] = math.sqrt(
                math.fsum((x - mean) ** 2 for x in values) / (len(values) - 1)
            )

    f_value = None
    if len(groups) >= 2:
        k = len(groups)
        total_n = sum(len(values) for values in groups.values())
        grand_mean = math.fsum(
            math.fsum(values) for values in groups.values()
        ) / total_n

        ss_between = math.fsum(
            len(values) * (means[name] - grand_mean) ** 2
            for name, values in groups.items()
        )
        ss_within = math.fsum(
            (x - means[name]) ** 2
            for name, values in groups.items()
            for x in values
        )

        df_within = total_n - k
        if df_within > 0:
            if ss_within == 0:
                f_value = math.inf if ss_between > 0 else math.nan
            else:
                f_value = (ss_between / (k - 1)) / (ss_within / df_within)

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
