                valid[i] = False
            else:
                columns[i].append(value)

    groups = {
        headers[i]: columns[i]
        for i in range(len(headers))
        if valid[i] and columns[i]
    }

    means = {}
    std_devs = {}

    for name, values in groups.items():
        mean = sum(values) / len(values)
        means[name] = mean
        std_devs[name] = (
            math.sqrt(sum((x - mean) ** 2 for x in values) / (len(values) - 1))
            if len(values) > 1
            else float("nan")
        )

    f_value = None
    if len(groups) >= 2:
        all_values = [x for values in groups.values() for x in values]
        grand_mean = sum(all_values) / len(all_values)
        ss_between = sum(
            len(values) * (means[name] - grand_mean) ** 2
            for name, values in groups.items()
        )
        ss_within = sum(
            sum((x - means[name]) ** 2 for x in values)
            for name, values in groups.items()
        )

        df_between = len(groups) - 1
        df_within = len(all_values) - len(groups)

        if df_within <= 0:
            f_value = float("nan")
        elif ss_within == 0:
            f_value = float("inf") if ss_between > 0 else float("nan")
        else:
            f_value = (ss_between / df_between) / (ss_within / df_within)

    return {"means": means, "std_devs": std_devs, "f_value": f_value}
