def matrix_tensor_product(P, T):
    n = len(T)

    if any(len(row) != n for row in P):
        raise ValueError("Each row of P must match T's first dimension")

    # With an empty first dimension, T has no A or B dimensions to iterate over.
    if n == 0:
        return ([[] for _ in P], [[] for _ in P])

    product = [
        [
            [
                sum(P[m][k] * T[k][a][b] for k in range(n))
                for b in range(len(T[0][a]))
            ]
            for a in range(len(T[0]))
        ]
        for m in range(len(P))
    ]

    sums = [[sum(cell) for cell in row] for row in product]
    return product, sums
