from datetime import datetime

def temperature_month_day_grid(records):
    if not records:
        raise ValueError("records must not be empty")

    required = {"Date", "Time", "Temperature"}
    values = {}
    months = set()
    days = set()

    for record in records:
        if not required.issubset(record):
            raise ValueError("Each record must contain Date, Time, and Temperature")

        date = datetime.strptime(record["Date"], "%Y-%m-%d").date()
        month, day = date.month, date.day
        months.add(month)
        days.add(day)

        # If a month/day occurs more than once, the last record wins.
        values[(month, day)] = float(record["Temperature"])

    return [
        [values.get((month, day)) for day in sorted(days)]
        for month in sorted(months)
    ]
