from math import fsum, sqrt
from numbers import Real


def standardize_and_correlate(table):
    if not table:
        raise ValueError("table must not be empty")

    columns = list(table)
    lengths = [len(table[name]) for name in columns]
    if len(set(lengths)) != 1:
        raise ValueError("all columns must have equal length")

    n = lengths[0]
    if n == 0:
        raise ValueError("columns must contain at least one value")

    numeric = [
        name for name in columns
        if all(isinstance(value, Real) for value in table[name])
    ]
    if not numeric:
        raise ValueError("table must have at least one numeric column")

    standardized = {name: list(table[name]) for name in columns}
    for name in numeric:
        values = table[name]
        mean = fsum(values) / n
        std = sqrt(fsum((value - mean) ** 2 for value in values) / n)
        if std == 0:
            raise ValueError(f"numeric column {name!r} has zero variance")
        standardized[name] = [(value - mean) / std for value in values]

    corr = []
    for a in numeric:
        row = []
        for b in numeric:
            if a == b:
                row.append(1.0)
            else:
                value = fsum(
                    x * y
                    for x, y in zip(standardized[a], standardized[b])
                ) / n
                row.append(max(-1.0, min(1.0, value)))
        corr.append(row)

    return standardized, corr
