from math import sqrt
from numbers import Real


def standardize_and_correlate(table):
    """Standardize real-valued columns and return their Pearson correlation matrix.

    Boolean values and empty columns are not treated as numeric. A constant
    numeric column standardizes to zeros; its off-diagonal correlations are 0.
    """
    if not table:
        raise ValueError("table must not be empty")

    columns = list(table.items())
    lengths = {len(values) for _, values in columns}
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    numeric_names = [
        name for name, values in columns
        if values and all(isinstance(value, Real) and not isinstance(value, bool)
                          for value in values)
    ]
    if not numeric_names:
        raise ValueError("table must contain at least one numeric column")

    standardized = {}
    z_columns = []

    for name, values in columns:
        if name not in numeric_names:
            standardized[name] = list(values)
            continue

        data = [float(value) for value in values]
        mean = sum(data) / len(data)
        std = sqrt(sum((value - mean) ** 2 for value in data) / len(data))
        z = [(value - mean) / std for value in data] if std else [0.0] * len(data)

        standardized[name] = z
        z_columns.append(z)

    n = len(z_columns[0])
    corr = []
    for i, left in enumerate(z_columns):
        row = []
        for j, right in enumerate(z_columns):
            if i == j:
                row.append(1.0)
            else:
                row.append(sum(a * b for a, b in zip(left, right)) / n)
        corr.append(row)

    return standardized, corr
```

