import math
import numbers


def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    columns = list(table.items())
    lengths = {len(values) for _, values in columns}
    if len(lengths) != 1:
        raise ValueError("columns must have equal lengths")

    n = lengths.pop()
    if n == 0:
        raise ValueError("table has no rows")

    numeric = [
        (name, values)
        for name, values in columns
        if all(isinstance(value, numbers.Real) for value in values)
    ]
    if not numeric:
        raise ValueError("table has no numeric columns")

    standardized = {name: list(values) for name, values in columns}
    z_columns = []

    for name, values in numeric:
        data = [float(value) for value in values]
        mean = sum(data) / n
        variance = sum((value - mean) ** 2 for value in data) / n
        std = math.sqrt(variance)
        if std == 0:
            raise ValueError(f"numeric column {name!r} has zero variance")

        z = [(value - mean) / std for value in data]
        standardized[name] = z
        z_columns.append(z)

    corr = [
        [sum(a * b for a, b in zip(left, right)) / n for right in z_columns]
        for left in z_columns
    ]

    return standardized, corr
```

A constant numeric column raises `ValueError` because its Pearson correlations are undefined.

