import math

def feature_correlation_matrix(samples):
    """Return the Pearson correlation matrix for the columns of samples.

    Correlations involving a constant feature are undefined and returned as NaN.
    """
    if not samples:
        return []

    n_features = len(samples[0])
    if any(len(row) != n_features for row in samples):
        raise ValueError("All rows must have the same length")

    columns = list(zip(*samples))
    means = [math.fsum(col) / len(samples) for col in columns]
    centered = [
        [value - means[j] for j, value in enumerate(row)]
        for row in samples
    ]
    sums_sq = [
        math.fsum(row[j] ** 2 for row in centered)
        for j in range(n_features)
    ]

    result = []
    for i in range(n_features):
        row = []
        for j in range(n_features):
            denominator = math.sqrt(sums_sq[i] * sums_sq[j])
            if denominator == 0:
                row.append(float("nan"))
            elif i == j:
                row.append(1.0)
            else:
                numerator = math.fsum(
                    values[i] * values[j] for values in centered
                )
                row.append(max(-1.0, min(1.0, numerator / denominator)))
        result.append(row)

    return result
```

For example, `feature_correlation_matrix([[1, 1], [2, 3], [3, 2]])` returns `[[1.0, 0.5], [0.5, 1.0]]`.

