def feature_correlation_matrix(samples):
    if not samples:
        return []

    n_features = len(samples[0])
    n_rows = len(samples)

    columns = [
        [row[j] for row in samples]
        for j in range(n_features)
    ]
    means = [sum(col) / n_rows for col in columns]
    centered = [
        [value - means[j] for value in columns[j]]
        for j in range(n_features)
    ]
    sums_of_squares = [
        sum(value * value for value in col)
        for col in centered
    ]

    matrix = []
    for i in range(n_features):
        row = []
        for j in range(n_features):
            denominator = (sums_of_squares[i] * sums_of_squares[j]) ** 0.5
            if denominator == 0:
                # Pearson correlation is undefined when either feature is constant.
                row.append(0.0)
            else:
                numerator = sum(a * b for a, b in zip(centered[i], centered[j]))
                row.append(max(-1.0, min(1.0, numerator / denominator)))
        matrix.append(row)

    return matrix
