from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._row_stack = []
        self._cell_stack = []

    def handle_starttag(self, tag, attrs):
        if tag == "tr":
            self.rows.append([])
            self._row_stack.append(len(self.rows) - 1)
        elif tag == "td" and self._row_stack:
            row_index = self._row_stack[-1]
            cell_index = len(self.rows[row_index])
            self.rows[row_index].append("")
            self._cell_stack.append((row_index, cell_index, []))

    def handle_endtag(self, tag):
        if tag == "td":
            self._finish_cell()
        elif tag == "tr" and self._row_stack:
            row_index = self._row_stack.pop()
            while self._cell_stack and self._cell_stack[-1][0] == row_index:
                self._finish_cell()

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_data(self, data):
        # Include text inside nested tags, while preserving spaces between it.
        for _, _, parts in self._cell_stack:
            parts.append(data)

    def _finish_cell(self):
        if self._cell_stack:
            row_index, cell_index, parts = self._cell_stack.pop()
            self.rows[row_index][cell_index] = "".join(parts).strip()

    def close(self):
        super().close()
        while self._cell_stack:
            self._finish_cell()


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    return parser.rows
```

