from html.parser import HTMLParser


class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.row_stack = []
        self.cells = []

    def handle_starttag(self, tag, attrs):
        if tag == "tr":
            row = []
            self.rows.append(row)
            self.row_stack.append(row)
        elif tag == "td" and self.row_stack:
            row = self.row_stack[-1]
            row.append("")
            self.cells.append({"row": row, "index": len(row) - 1, "parts": []})

    def handle_endtag(self, tag):
        if tag == "td" and self.row_stack:
            row = self.row_stack[-1]
            for i in range(len(self.cells) - 1, -1, -1):
                if self.cells[i]["row"] is row:
                    self._finish_cell(i)
                    break
        elif tag == "tr" and self.row_stack:
            row = self.row_stack[-1]
            for i in range(len(self.cells) - 1, -1, -1):
                if self.cells[i]["row"] is row:
                    self._finish_cell(i)
            self.row_stack.pop()

    def handle_data(self, data):
        # Include text inside nested tags; outer cells also receive their
        # descendants' text.
        for cell in self.cells:
            cell["parts"].append(data)

    def _finish_cell(self, index):
        cell = self.cells.pop(index)
        cell["row"][cell["index"]] = "".join(cell["parts"]).strip()

    def finish(self):
        while self.cells:
            self._finish_cell(len(self.cells) - 1)


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    parser.finish()
    return parser.rows
```

