        fraction = position - low
        return sorted_values[low] + fraction * (
            sorted_values[high] - sorted_values[low]
        )

    result = {}
    for key, values in values_by_key.items():
        ordered = sorted(values)
        result[key] = {
            "mean": sum(values) / len(values),
            "median": quantile(ordered, 0.5),
            "q1": quantile(ordered, 0.25),
            "q3": quantile(ordered, 0.75),
        }

    return result
```

Invalid JSON raises `ValueError` (`json.loads` raises `JSONDecodeError`, a subclass of `ValueError`). The quartiles use linear interpolation at positions `(n - 1) * p`.

```python
import json


def summarize_values_by_key(json_text):
    def reject_constant(value):
        raise ValueError(f"Invalid JSON value: {value}")

    try:
        data = json.loads(json_text, parse_constant=reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, list) or any(not isinstance(obj, dict) for obj in data):
        raise ValueError("Expected a JSON list of objects")

    values_by_key = {}
    for obj in data:
        for key, value in obj.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Value for {key!r} must be a number")
            values_by_key.setdefault(key, []).append(value)

    def percentile(sorted_values, p):
        position = (len(sorted_values) - 1) * p
        lower = int(position)
        upper = min(lower + 1, len(sorted_values) - 1)
        fraction = position - lower
        return sorted_values[lower] + fraction * (
            sorted_values[upper] - sorted_values[lower]
        )

    result = {}
    for key, values in values_by_key.items():
        values.sort()
        n = len(values)
        result[key] = {
            "mean": sum(values) / n,
            "median": percentile(values, 0.5),
            "q1": percentile(values, 0.25),
            "q3": percentile(values, 0.75),
        }

    return result
```

```python
import json
import math


def summarize_values_by_key(json_text):
    def reject_constant(value):
        raise ValueError(f"Invalid JSON constant: {value}")

    try:
        data = json.loads(json_text, parse_constant=reject_constant)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, list) or any(not isinstance(obj, dict) for obj in data):
        raise ValueError("Expected a JSON list of objects")

    values_by_key = {}
    for obj in data:
        for key, value in obj.items():
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Value for {key!r} must be a number")
            if not math.isfinite(value):
                raise ValueError(f"Value for {key!r} must be finite")
            values_by_key.setdefault(key, []).append(value)

    def percentile(sorted_values, p):
        position = (len(sorted_values) - 1) * p
        lower = math.floor(position)
        upper = math.ceil(position)
        fraction = position - lower
        return sorted_values[lower] * (1 - fraction) + sorted_values[upper] * fraction

    result = {}
    for key, values in values_by_key.items():
        values.sort()
        result[key] = {
            "mean": sum(values) / len(values),
            "median": percentile(values, 0.5),
            "q1": percentile(values, 0.25),
            "q3": percentile(values, 0.75),
        }

    return result
